NAME = 'Tausug: Tausug Kitab Injil'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: "Asal ha tagnaan, yaun na in Parman, iban in Parman asal naghahambuuk iban Tuhan, karna' in Parman amu na in Tuhan.",
        2: 'Iban asal dayn ha panagnaan pa, naghahambuuk na in Parman iban Tuhan.',
        3: "In unu-unu katān naawn, piyaawn sin Parman dayn ha kabayaan sin Tuhan. Wayruun hangsulag unu-unu in naawn bang bukun guwa' dayn ha Parman.",
        4: "Damikkiyan in Parman amuna in puunan sin kabuhi' sabunnal, iban in puunan sin kabuhi' sabunnal amuna in ilaw dumihil sawa pa pikilan sin mānusiya'.",
        5: "In ilaw ini sumi'nag na ha lawm sin katigidluman ha lawm dunya, iban in katigidluman di' makapūng sin ilaw ini.",
        6: 'Manjari awn hambuuk tau kiyawakilan sin Tuhan. In ngān niya hi Yahiya.',
        7: "Diyaak siya sin Tuhan mamayta' pa manga tau pasal sin ilaw ini, ha supaya in mānusiya' katān makarungug iban magparachaya sin bayta' pasal sin ilaw.",
        8: "Bukun hi Yahiya in piyagbahasa ilaw. Karna' in siya naraak sadja mamayta' pasal sin ilaw.",
        9: "Na, in Parman amuna tuud in bunnal ilaw, amu in limahil mari pa dunya dumihil kasawahan pa pikilan sin mānusiya' katān.",
        10: "Sagawa' sin dī siya ha dunya wala' siya kīla sin manga mānusiya', minsan da siya in nagpapanjari sin unu-unu katān dayn ha kabayaan sin Tuhan.",
        11: "Miyari siya pa hula' napī' niya hulaan, sagawa' minsan in manga pagkahi niya hangka-bangsa, wala' da timayma' kaniya.",
        12: "Sagawa' hisiyu-siyu in timayma' ha amu in piyagbahasa Parman iban nagparachaya isab kaniya, dīhilan niya sila kapatutan mahinang manga anak sin Tuhan.",
        13: "Ampa in kahinang kanila anak sin Tuhan bukun biya' kaagi sin pag'anak sin tau dī ha dunya, amu in guwa' dayn ha kabayaan atawa ganta' sin mānusiya'. Sagawa' mahinang sila manga anak sin Tuhan dayn ha kabayaan sin Tuhan.",
        14: "Manjari in piyagbahasa Parman nagbaran mānusiya', limahil mari pa dunya iban himangka-hula' kātu'niyu. Jukup in kasi-lasa niya iban siya in magpakita' sin katān kasabunnalan. Kīta' namu' in sahaya iban kawasa niya amu in sahaya iban kawasa matūp tuud ha hambuuk-buuk Anak Tuhan.",
        15: "Hi Yahiya in namayta' pasal sin amu in piyagbahasa Parman. Namichara siya matanug, laung niya, “Siya na ini in bakas piyag'iyan ku kaniyu. Laung ku, ‘Siya in sumunud kāku', sagawa' labi in kawasa niya dayn kāku', sabab in siya asal awn na ha wala' pa aku natau.’” (Amu yan in bayta' hi Yahiya.)",
        16: "Pagga jukup in kasi-lasa niya, in kitaniyu katān awn kahampitan. Magdurugang in tulung-tabang niya kātu'niyu amu in i'hilas tuud sin atay niya.",
        17: "Hi Musa in nagpasampay pa manga mānusiya' sin sara' piyanaug sin Tuhan, sagawa' hi Īsa Almasi, amu in piyagbahasa Parman in nagpasampay pa manga mānusiya' sin kasi-lasa iban sin kasabunnalan sin Tuhan.",
        18: "Wayruun mānusiya' in nakakita' ha Tuhan, luwal da amu in hambuuk-buuk Anak niya, karna' in siya asal amuna tuud in Tuhan. Siya in nagpaingat ha manga mānusiya' pasal sin Tuhan Ama' niya, sabab in sila asal hambuuk da.",
        19: "Manjari biya' ha ini in bayta' hi Yahiya pasal sin Almasi. Awn hambuuk waktu diyaak sin manga Yahudi, amu in nagkakaput sara' agama ha Awrusalam, in manga imam iban sin manga tau mananabang ha manga imam, madtu kan Yahiya mangasubu bang hisiyu tuud siya.",
        20: "Wala' naglibun hi Yahiya kanila. Biyaytaan niya sila sin kasabunnalan, laung niya, “Bukun aku in Almasi.”",
        21: "Laung nila, “Bang kaw bukun in Almasi, hisiyu kaw tuud? Ikaw baha' hi Ilyas?” “Bukun,” in sambung hi Yahiya. “Ikaw ka in nabi amu in tiyatagaran sin bangsa natu' Israil?” “Bukun,” in sambung hi Yahiya.",
        22: "Laung sin manga imam, “Na, baytai kami bang hisiyu kaw, sabab subay tuud awn hikabayta' namu' pa manga tau nagdaak kāmu' miyari. Baytai kami sin pasal mu bang hisiyu kaw tuud.”",
        23: "Siyambungan sila hi Yahiya sin manga lapal-kabtangan amu in sibu' tuud iban sin bayta' kiyasulat hi Nabi Isayas ha lawm Kitab. Laung niya, “Aku in tau manawag-tawag ha hula' paslangan mahunit paghulaan. Laung ku ha manga tau, ‘Pabuntula niyu in dān labayan sin Panghu'!’”",
        24: "Na, in manga imam naraak sin manga Parisi, amu in hambuuk tumpuk sin magkakaput sin sara' agama Yahudi, nangasubu na isab kan Yahiya.",
        25: "Laung nila, “Bang kaw bukun in Almasi atawa hi Ilyas atawa in nabi amu in piyagtatagaran sin bangsa natu' Yahudi, mayta' kaw mangligu' ha manga tau?”",
        26: "In sambung hi Yahiya, “In aku miyari nangligu' ha manga tau sin tubig. Sagawa' awn hambuuk tau in labi dayn kāku'. Yan siya limalamugay kaniyu, sa' di' niyu siya kaingatan.",
        27: "Miyari siya pa dunya simunud kāku', sagawa' minsan humubad sin hukut tawmpa' niya, di' aku tūpun sabab landu' tuud mataas in kawasa niya dayn kāku'.”",
        28: "Na, amu na yan in kimugdan kan Yahiya ha waktu siya duun nagliligu' ha manga tau ha hula' Bitani ha dapit pa subangan sin suba' Jurdan.",
        29: "Na, pag'adlaw hambuuk kīta' hi Yahiya hi Īsa miyamanaw sūng mawn kaniya. Laung hi Yahiya, “Yan na in giyanti' anak bili-bili pagkulbanan pa Tuhan, karna' siya in piyalahil sin Tuhan mamuas ha manga mānusiya' dayn ha manga dusa nila!",
        30: "Siya na ini in piyag'iyan ku kaniyu. Bakas ta kamu biyaytaan, laung ku, ‘Awn tau sumunud kāku', sagawa' labi tuud mataas in kawasa niya dayn kāku', sabab in siya asal naawn ha wala' pa aku natau.’",
        31: "In bunnal niya, wala' ku kiyaingatan bang hisiyu in tau naraak sin Tuhan sumunud kāku', sagawa' miyari aku nangligu' ha manga tau iban tubig ha supaya siya mapanyata' pa manga tau bangsa Israil.”",
        32: "Manjari nanuysuy na hi Yahiya ha manga mulid niya pasal sin Almasi. Laung niya, “Ha wala' ku pa kiyaingatan bang hisiyu in naraak sin Tuhan sumunud kāku', awn kiyabayta' kāku' sin Tuhan, amu in nagdaak kāku' mangligu' ha manga tau sin tubig. Laung niya kāku', ‘Bang mu kakitaan in Rū sin Tuhan, tumulun magpanyata' mawn pa hambuuk tau iban tumutug duun kaniya, in hāti niya, siya na yan in tau sumangun sin Rū Mahasuchi sin Tuhan pa manga mānusiya'.’ Na, nabunnal tuud in bayta' sin Tuhan, sabab kīta' ku tuud timulun dayn ha surga' in Rū sin Tuhan, nagpasalupa biya' māpati, ampa timapu' mawn kan Īsa.”",
        33: "Manjari nanuysuy na hi Yahiya ha manga mulid niya pasal sin Almasi. Laung niya, “Ha wala' ku pa kiyaingatan bang hisiyu in naraak sin Tuhan sumunud kāku', awn kiyabayta' kāku' sin Tuhan, amu in nagdaak kāku' mangligu' ha manga tau sin tubig. Laung niya kāku', ‘Bang mu kakitaan in Rū sin Tuhan, tumulun magpanyata' mawn pa hambuuk tau iban tumutug duun kaniya, in hāti niya, siya na yan in tau sumangun sin Rū Mahasuchi sin Tuhan pa manga mānusiya'.’ Na, nabunnal tuud in bayta' sin Tuhan, sabab kīta' ku tuud timulun dayn ha surga' in Rū sin Tuhan, nagpasalupa biya' māpati, ampa timapu' mawn kan Īsa.”",
        34: "Na, laung hi Yahiya, “In yan kīta' ku tuud iban bihaun baytaan ta na kamu tuud sin kasabunnalan, sin in hi Īsa amuna tuud in Anak Tuhan.”",
        35: "Manjari, pag'adlaw hambuuk duun na isab hi Yahiya timitindug iban sin duwa mulid niya ha higad sin Sapa' Jurdan.",
        36: "Sakali kīta' hi Yahiya hi Īsa limabay sarta' laung niya, “Yan na in giyanti' bili-bili pagkulbanan pa Tuhan!”",
        37: 'Pagdungug sin duwa mulid hi Yahiya sin bichara niya, magtūy sila imurul kan Īsa.',
        38: "Sagawa' pagharap hi Īsa pa ulihan, kīta' niya in duwangka-tau miyumurul kaniya, laung niya kanila, “Mayta' kamu imurul kāku'?” In sambung nila, “Rabbi, hariin in kiyaruunan mu?” (In hāti sin Rabbi, Tuwan Guru).",
        39: "Laung hi Īsa kanila, “Agad kamu mari kāku' bat niyu kakitaan.” Manjari miyagad na sila iban kīta' nila na in kiyaruunan niya. Iyabutan na sila dūm didtu sabab in kaagad nila kan Īsa awn na kulang-labi lisag upat sin mahapun.",
        40: 'In ngān sin hambuuk amu in miyurul miyagad kan Īsa, hi Andariyas, taymanghud hi Simun Pitrus.',
        41: "Manjari magtūy hi Andariyas miyadtu naglawag ha taymanghud niya hi Simun. Kiyabaakan niya mān, laung hi Andariyas, “Kiyabaakan namu' na in Almasi.”",
        42: "Sakali diyā niya madtu hi Simun kan Īsa. Iyatud siya hi Īsa ampa namung, amu agi, “Ikaw hi Simun, anak hi Yahiya, sagawa' danglayan ta kaw Kipas.” (In ngān Kipas sali' da iban Pitrus. In hāti niya batu.)",
        43: "Manjari, pag'adlaw hambuuk napikil hi Īsa limanjal pa hula' Jalil. Sakali nagbaak sila kay Pilip. Laung hi Īsa kaniya. “Kari kaw agad kāku'!”",
        44: "In hi Pilip ini tau Bitsayda, amu in hula' hi Andariyas kay Pitrus.",
        45: "Na, magtūy hi Pilip naglawag kan Natanyal. Kiyabaakan niya mayan, laung niya kan Natanyal, “Kiyabaakan namu' na in piyagbayta' hi Musa kiyasulat ha lawm Kitab Tawrat iban sin piyagbayta' sin manga kanabihan, amu in kiyasulat nila ha manga Kitab. In piyagbayta' nila amuna hi Īsa, anak hi Yusup dayn ha Nasarit.”",
        46: "Sakali laung hi Natanyal, “Uy! Mayta', awn tau marayaw dayn ha Nasarit?” In sambung hi Pilip, “Kari kaw agad bat mu kakitaan.”",
        47: "Manjari, pagkita' hi Īsa kan Natanyal sūng mawn kaniya, namung hi Īsa, laung niya, “Yari na in tau, amu in tantu tuud bangsa Israil. Bukun siya panipu!”",
        48: "Laung hi Natanyal kaniya, “Biya' diin in kaingat mu kāku'?” In sambung hi Īsa, “Sin way pa kaw natawag hi Pilip, kīta' ta kaw simisilung ha sawm kahuy tina.”",
        49: "Magtūy simambung hi Natanyal kan Īsa, laung niya, “Tuwan Guru ikaw na tuud in Anak Tuhan, iban ikaw in Sultan sin bangsa namu' Israil!”",
        50: "Laung hi Īsa kaniya, “Nagparachaya na kaw magtūy kāku' sawkat ta na kaw biyaytaan sin kīta' ta kaw similung ha sawm kahuy tina? Ingat kaw ha susūngun awn manga hinang ku kakitaan mu labi makainu-inu dayn ha yan!”",
        51: "Iban laung hi Īsa kanila, “Tantu tuud baytaan ta kamu sin tuman, kakitaan niyu maukab in lawang langit iban magnaug-gaban in manga malāikat sin Tuhan mari kāku', amu in Anak Mānusiya'.”",
    },
    2: {
        1: "Limabay mayan duway adlaw dayn ha kapagbichara hi Īsa kay Natanyal, awn nagtiyaun ha dāira sin Kana ha hula' Jalil. Didtu in ina' hi Īsa nangluruk.",
        2: 'Nataabbit da isab hinda Īsa iban sin manga mulid niya pa pagtiyaunan.',
        3: "Manjari didtu mayan sila ha pagtiyaunan, in tubig anggul naubus na sin manga luruk. Na, laung sin ina' hi Īsa kaniya, “Kiyaubusan na sila tubig anggul.”",
        4: "Sagawa' in sambung hi Īsa ha ina' niya, laung niya, “Ina', ayaw na kaw magsusa sin pasal yan. Aku na in makaingat ha yan. Way pa miyabut in waktu sin pagpaguwa' ku sin kusug ku.”",
        5: "Sagawa' minsan biya' hādtu in sambung hi Īsa, biyaytaan sin ina' niya in manga daraakun ha bāy pagtiyaunan, laung niya, “Hinanga niyu in unu-unu daakan kaniyu hi Īsa.”",
        6: "Manjari awn duun unum puga pagluluunan tubig hipag'ayl sin manga Yahudi. In luun sin hambuuk puga awn manga kawhaan taglima bingki' tubig.",
        7: "Sakali laung hi Īsa ha manga daraakun duun, “Hipua niyu sin tubig in unum puga yan.” Saruun-duun liyuunan nila in puga hīpu' tuud.",
        8: 'Ubus laung hi Īsa kanila, “Na, sawk na kamu ampa niyu dāha madtu pa tau nagkakaput sin paghinang.” Pagdā nila madtu,',
        9: "kīnaman na sin tau nagkakaput sin paghinang in tubig amu in nahinang na tubig anggul. Wala' niya kiyaingatan bang dayn hāin kiyawa' in tubig anggul, sagawa' in manga daraakun nagsāwk sin tubig, nakaingat. Hangkan tiyawag sin tau nagkakaput sin paghinang in pangantin usug,",
        10: "laung niya, “In kamatauran ha paghinangan in hipainum nila tagna' in tubig anggul marayaw tuud. Na, bang mataud na in nainum sin manga luruk, hipainum nila in tubig anggul bukun marayaw tuud. Sagawa' in ikaw dugaing. Sampay pa bihaun masi tubig anggul marayaw tuud in hipagpainum mu, sa' labi awla in dayaw sin ini.”",
        11: "Na, duun ha kawman Kana ha Jalil timagna' hi Īsa nagpaawn mu'jijat, amu in hinang makainu-inu. Duun niya tagna' napakita' in kusug sin kawasa niya, lāgi' nagparachaya tuud kaniya in manga mulid niya.",
        12: "Pag'ubus yadtu limūd na hi Īsa pa dāira Kapirnaum nag'agad iban sin ina' niya, manga taymanghud niya iban sin manga mulid niya. Himanti' sila duun manga pilay adlaw.",
        13: "Sakali maray' mayan in paghinang sin manga Yahudi sin Haylaya Paglappas dayn ha Kamatay, timukad hi Īsa iban sin manga mulid niya madtu pa Awrusalam.",
        14: "Pagdatung nila pa Awrusalam, simūd hi Īsa pa lawm halaman sin Bāy sin Tuhan. Pagsūd niya, kīta' niya in manga tau nagdaragang sapi' iban manga bili-bili iban manga assang. Kīta' niya da isab in manga tau mananambi' sīn dayn ha bangsa dugaing pa sīn sin bangsa Yahudi, naglilingkud ha manga lamisahan nila.",
        15: "Na, diyugalan hi Īsa pagkita' niya ha manga yan. Hangkan kimā' siya lubid hīnang lulubak ampa niya diyūy in katān hayup, in manga bili-bili iban manga sapi' pa guwa' sin halaman sin Bāy sin Tuhan. Biyalintuwad niya in lamisahan sin manga tau mananambi' sīn sin sīn dayn ha hula' dugaing, iban piyulak-palik niya in manga pisita nila.",
        16: "Ubus ampa niya īyan in manga tau magdaragang assang, laung niya, “Dāha niyu pa guwa' in manga dagangan niyu yan. Ayaw niyu hinanga tabu' in bāy ini amu in Bāy sin Tuhan, Ama' ku!”",
        17: "Na, magtūy kiyatumtuman sin manga mulid niya in kiyasulat ha lawm Kitab, amu agi, “Ū, Tuhan landu' tuud in tuyu' ku magparuli sin bāy mu minsan amuna in makamula kāku'.”",
        18: "Manjari magtūy miyawn nangasubu kan Īsa in manga nakura' sin manga Yahudi. Laung nila kan Īsa, “Unu ta' in kapatutan mu yan magpaguwa' kanila? Bang bunnal dayn ha Tuhan in kapatutan mu, pakitaa kami hambuuk mu'jijat, amu in tanda' sin awn kapatutan mu.”",
        19: 'In sambung hi Īsa kanila, “Lubuha niyu in Bāy sin Tuhan ini, hāti ha lawm sin tūy adlaw tibuukun ku magbalik patindugun.”',
        20: "Laung sin manga nakura' Yahudi, “Uy, mapatindug mu magbalik in Bāy sin Tuhan ini ha lawm tūy adlaw? Minsan in lugay naghinang ha yan awn ka'patan tag'unum tahun!”",
        21: "Na, wala' nila kiyahātihan in maana sin bichara hi Īsa sabab in Bāy sin Tuhan piyag'iyan hi Īsa amuna in anggawta'-baran niya.",
        22: "Hangkan naabut mayan in waktu nabuhi' nagbalik hi Īsa dayn ha kamatay, kiyatumtuman sin manga mulid niya in bichara hi Īsa pasal sin bāy. Kiyahātihan nila na in maana sin bichara niya. Na, nagparachaya na tuud sila sin manga kiyasulat ha lawm Kitab iban sin manga bichara hi Īsa.",
        23: "Manjari sin sa'bu hi Īsa duun ha Awrusalam himadil sin Haylaya Paglappas dayn ha Kamatay, mataud tau in nagparachaya kaniya sabab kīta' nila in manga mu'jijat nahinang niya.",
        24: "Sagawa' wala' piyangandul hi Īsa in baran niya kanila sabab asal niya kiyaiingatan bang unu in ha pikilan iban lawm atay sin mānusiya' katān.",
        25: "Minsan siya di' na baytaan sin manga addat-mangaddat sin manga mānusiya' sabab asal niya kaingatan in ha lawm atay sin manga mānusiya'.",
    },
    3: {
        1: "Manjari awn hambuuk nakura' sin manga Yahudi agad ha hambuuk tumpuk sin agama nila, amu in pagtawagun Parisi. In ngān niya hi Nikudimus.",
        2: "Sakali hambuuk dūm miyadtu hi Nikudimus kan Īsa dimā nagbichara. Laung niya, “Tuwan, kaingatan namu' in ikaw hambuuk guru piyakari sin Tuhan himindu' kāmu', karna' di' kaw makapaawn sin manga mu'jijat bang kaw wala' dīhilan barakat sin Tuhan.”",
        3: "Sagawa' in sambung hi Īsa kaniya, amu agi, “Baytaan ta kaw sin kasabunnalan, bang in tau di' hipag'anak magbalik, way lamud niya ha pamarinta sin Tuhan.”",
        4: "Laung hi Nikudimus, “Biya' diin kaagi in tau maas hipag'anak magbalik? Tantu di' na siya makasūd magbalik pa lawm tiyan sin ina' niya iban hipag'anak magbalik!”",
        5: "In sambung hi Īsa kaniya, laung niya, “Baytaan ta kaw sin kasabunnalan, bang in tau di' hipag'anak dayn ha tubig iban da isab dayn ha Rū sin Tuhan, way lamud niya ha pamarinta sin Tuhan.",
        6: "In tau hipag'anak sin mānusiya', mānusiya' da isab. Sagawa' bang in tau hipag'anak magbalik sin Rū sin Tuhan, in siya nahinang na anak sin Tuhan.",
        7: "Na, ayaw kaw mainu-inu sin bichara ku sin subay kaw hipag'anak magbalik.",
        8: "In Rū sin Tuhan biya' da sapantun sin hangin, makapagbaya' bang pakain in tudjuhan niya. Kananaman ta in hangin sagawa' di' ta kaingatan bang guwa' dayn diin atawa tudju pakain. Na, biya' da isab ha yan in hantang sin Rū sin Tuhan bang hipag'anak magbalik in mānusiya' dayn ha kusug sin Rū.”",
        9: "Laung hi Nikudimus, “Ay kaw, biya' diin in kaagi sin biya' ha yan?”",
        10: "In sambung hi Īsa kaniya, “Mayta' mu di' kahātihan in panghindu' ku ini? Malayngkan, hambuuk kaw guru lalagguun sin bangsa Israil.",
        11: "Baytaan ta kaw sin kasabunnalan. Nagnasīhat kami sin kiyaingatan namu' iban simaksi' kami sin kiyakitaan namu'. Sagawa' di' kamu magparachaya sin bayta' namu'.",
        12: "Bang kamu di' magparachaya sin hindu' ku ha pasal sin kahālan sin dunya, na tantu di' da kamu isab magparachaya kāku' bang ta kamu hinduan sin kahālan sin surga'.",
        13: "Wayruun mānusiya' in nakakadtu pa surga' luwal da in aku, amu in Anak Mānusiya'. In aku miyari dayn ha surga' sabab amu yan in asal hulaan ku.”",
        14: "Laung pa isab hi Īsa, “Sin masa nakauna yadtu, ha waktu hi Musa iban sin manga bangsa Israil didtu ha hula' paslangan mahunit paghulaan, giyantung hi Musa pa usuk in hās hīnang dayn ha tumbaga ha supaya bang aturun sin manga tau bakas nakutkut sin hās, kaulian sila. Na, biya' da isab ha yan in hantang sin amu in Anak Mānusiya'. Subay aku hikalansang pa usuk pagpatayan tau ampa patindugun,",
        15: "ha supaya hisiyu-siyu in magparachaya kāku' makabāk kabuhi' salama-lama ha lawm ukum milik sin Tuhan.”",
        16: "Landu' tuud malasa in Tuhan ha manga mānusiya', hangkan atas niya piyalahil pa dunya in hambuuk-buuk Anak niya amu in miyatay, ha supaya hisiyu-siyu in magparachaya kaniya di' makapanarka' ha adlaw mahuli iban makabāk siya kabuhi' salama-lama.",
        17: "In maksud sin Tuhan nagpakari ha Anak niya pa dunya bukun manghukum ha manga mānusiya', sagawa' lumappas kanila, bat sila di' kabutangan sin hukuman sin Tuhan.",
        18: "Na, hisiyu-siyu in magparachaya ha Anak Tuhan, di' tuud siya kugdanan sin hukuman sin Tuhan, sagawa' hisiyu-siyu in di' magparachaya kaniya, na in tau yan asal kiyugdan na sin hukuman sabab wala' siya nagparachaya ha hambuuk-buuk Anak Tuhan.",
        19: "In Anak Tuhan, amu in piyagbahasa ilaw, miyari pa lawm dunya dumihil kasawahan ha manga mānusiya', sagawa' mabaya' in manga mānusiya' sin katigidluman dayn sin kasawahan sabab mangī' in manga hinang nila. Na, amu yan in sabab hangkan in mānusiya' kugdanan sin hukuman.",
        20: "Na, in tau mangī' in hinang niya marugal ha ilaw yan. Di' siya mabaya' humarap pa ilaw yan sabab di' siya mabaya' kakitaan in manga hinang niya mangī'.",
        21: "Sagawa' in tau naghihinang sin marayaw mabaya' humarap pa ilaw, ha supaya tumampal sin in siya naghinang marayaw sabab sin pagkahagad niya ha Tuhan.",
        22: "Pag'ubus, miyadtu hinda Īsa pa hula' Yahudiya iban sin manga mulid niya. Dimuun sila manga pilay adlaw iban nagligu' sila ha manga tau.",
        23: "Ha waktu yadtu wala' pa najīl hi Yahiya. Didtu isab siya nagligu' ha manga tau ha hula' Inun, amu in masuuk pa hula' Salim, sabab mataud tubig didtu. Daran in manga tau madtu kaniya magpaligu'.",
        24: "Ha waktu yadtu wala' pa najīl hi Yahiya. Didtu isab siya nagligu' ha manga tau ha hula' Inun, amu in masuuk pa hula' Salim, sabab mataud tubig didtu. Daran in manga tau madtu kaniya magpaligu'.",
        25: "Manjari, in manga kaibanan mulid hi Yahiya naglugat iban sin hambuuk Yahudi pasal sin addat sin pagligu' ha aturan sin agama.",
        26: "Sakali miyadtu in manga mulid hi Yahiya kaniya, amu agi, “Tuwan Guru, katumtuman mu in hambuuk tau piyagbayta' mu kāmu' amu in iban mu didtu ha hansipak sin Suba' Jurdan? Na, nagligu' na siya ha manga tau iban mataud tuud tau in sūng madtu kaniya!”",
        27: 'In sambung hi Yahiya kanila, “Wayruun tau in tagakawasa bang bukun dayn ha Tuhan.',
        28: "Iban makasaksi' kamu sin bakas piyamung ku sin bukun aku in Almasi, sagawa' naraak aku mari piyauna dayn kaniya magsakap sin dān labayan niya.",
        29: "Bang sawpama awn tau maniyaun, in pangantin usug in tagsuku' ha pangantin babai, bukun in bagay niya. Na, in bagay sin pangantin usug, amu in miyuna dayn kaniya, kumuyag tuud bang niya karungugan na in tingug sin pangantin usug. Na, biya' da isab ha yan in hantang namu' kay Īsa. Jumukup na in kakuyagan ku",
        30: "bang hi Īsa tumaas na mabantug, hāti in aku maba' na in kabantugan ku.”",
        31: "Na, bang in tau limahil dayn ha surga' tantu makawasa tuud siya dayn ha katān. Sagawa' bang dayn ha dunya sadja in tau, na, in kaingatan iban hikahindu' niya amuna in kahālan ha lawm dunya. Sagawa' in tau naug dayn ha surga' makawasa tuud dayn ha katān.",
        32: "Na pagga siya naug dayn ha surga', in hindu' niya pasal sin manga kīta' iban diyungug niya ha surga', sagawa' hangkatiyu' da tuud in magparachaya ha hindu' niya.",
        33: "Sagawa' hisiyu-siyu in magparachaya tuud ha hindu' niya amuna in dumihil tanda' sin bunnal tuud in Tuhan,",
        34: "sabab in Almasi, amu in piyalahil sin Tuhan pa dunya, mamayta' pasal sin bayta' sin Tuhan, karna' in Almasi kapag'agihan sin Rū sin Tuhan, amu in piyatutug sin Tuhan duun kaniya.",
        35: 'Malasa tuud in Tuhan ha Anak niya, iban dīhil niya in katān kusug iban kawasa kaniya.',
        36: "Hisiyu-siyu in magparachaya ha amu in Anak Tuhan, awn kabuhi' niya salama-lama, sagawa' hisiyu-siyu in di' magparachaya ha Anak Tuhan, di' siya kaawnan sin kabuhi' salama-lama. Gām mayan di' maīg in mulka' sin Tuhan dayn kaniya.",
    },
    4: {
        1: "Manjari kiyabaytaan in manga tau Parisi sin mataud tau in miyagad iban nagpaligu' kan Īsa dayn kan Yahiya.",
        2: "In bunnal niya, bukun hi Īsa in nagligu' ha manga tau, sa' manga mulid niya in nagligu'.",
        3: "Na, pag'ingat hi Īsa sin manga suysuy ini, minīg siya iban sin manga mulid niya dayn ha hula' Yahudiya, ampa sila miyadtu nagbalik pa hula' Jalil.",
        4: 'Sakali in dān tudju pa Jalil subay lumabay dayn ha Samariya.',
        5: "Na, limabay hinda Īsa dayn ha dān yan, sampay naabut nila in hambuuk kawman sin hula' Samariya pagngānan Sikar. In dāira ini masuuk madtu pa lupa' amu in piyusaka' hi Ya'kub ha anak niya hi Yusup sin masa nakauna yadtu.",
        6: "Manjari duun ha lupa' yaun, awn hambuuk kuppung amu in bakas hīnang hi Ya'kub. Sakali limingkud hi Īsa duun ha higad sin kuppung sabab liyaul siya, iban ugtu suga na.",
        7: "Hāti in manga mulid niya miyadtu pa lawm dāira namī pagkaun. Na, nakalingkud mayan hi Īsa, awn hambuuk babai Samariya in miyawn simawk tubig. Manjari laung hi Īsa ha babai ini, “Inda', dihili aku tubig inumun.”",
        8: "Hāti in manga mulid niya miyadtu pa lawm dāira namī pagkaun. Na, nakalingkud mayan hi Īsa, awn hambuuk babai Samariya in miyawn simawk tubig. Manjari laung hi Īsa ha babai ini, “Inda', dihili aku tubig inumun.”",
        9: "Laung sin babai kan Īsa, “In kita, bukun hangka-bangsa. In ikaw hambuuk Yahudi, ampa in aku tau Samariya, hāti mangayu' kaw kāku' tubig?” Hangkan in babai imiyan biya' hādtu, sabab di' mag'iyasipi in manga Yahudi iban sin manga tau Samariya.",
        10: "In sambung hi Īsa ha babai, laung niya, “Bang mu sadja kaingatan bang unu in hirihil sin Tuhan ha manga mānusiya', iban bang mu kaingatan bang hisiyu tuud aku amu in mangayu' tubig bihaun, na mangayu' da kaw isab tubig dayn kāku'. Na, painumun ta kaw sin tubig amu in makabuhi' ha tau.”",
        11: "Laung sin babai kan Īsa, “Tuwan, biya' diin in kasawk mu sin tubig makabuhi' ha tau sin wayruun hipanawk mu? Ampa in kuppung ini malawm.",
        12: "In naghinang sin kuppung ini hi Ya'kub, amu in kaapu'-apuan natu'. Nakainum sila magtawtay'anak sin tubig ini sampay pa manga kahayupan nila. Na, pikil mu baha', makawasa kaw dayn kan Ya'kub?”",
        13: 'In sambung hi Īsa, “In katān makainum sin tubig dayn ha kuppung ini, tantu uhawun da magbalik.',
        14: "Sagawa' hisiyu-siyu in makainum sin tubig hirihil ku kaniya, tantu di' siya uhawun magbalik kasaumulan. Karna' in tubig hirihil ku kaniya mahinang biya' tuburan sin tubig ha lawm atay niya, amu in dumihil kaniya kabuhi' salama-lama.”",
        15: "Laung sin babai, “Tuwan, painuma aku sin tubig piyag'iyan mu yan ha supaya aku di' na uhawun magbalik, iban ha supaya aku di' na mari magbalik sumawk tubig.”",
        16: 'Laung hi Īsa kaniya, “Kadtu kaw kawaa in bana mu ampa kamu balik mari.”',
        17: 'In sambung sin babai, “Wayruun bana ku bihaun.” Laung hi Īsa, “Bunnal in agi mu sin wayruun bana mu bihaun,',
        18: "sabab minsan kaw nakalabay na nagbana nakalima, in usug iban mu nag'uukum bihaun, bukun kamu halal kawin. Kasabunnalan in biyayta' mu kāku'.”",
        19: 'Laung sin babai kan Īsa, “Tuwan, bat hambuuk nabi kaw hāti yan!',
        20: "In manga kaapu'-apuan namu' yadtu, manga tau Samariya, dī ha būd ini in pagpudjihan nila ha Tuhan. Sagawa' laung sin manga kamu bangsa Yahudi subay ha Awrusalam in pagpudjihan ha Tuhan.”",
        21: "Laung hi Īsa kaniya, “Inda', kahagad na kaw sin bayta' ku kaymu. Dumatung da in waktu sin pagpudji natu' ha Tuhan, Ama' natu', bukun ha būd ini atawa ha Awrusalam.",
        22: "In kamu manga tau Samariya di' niyu kaingatan bang hisiyu tuud in piyupudji niyu. Sagawa' in manga kami bangsa Yahudi kaingatan namu' in piyupudji namu' sabab in manglalappas ha mānusiya' guwa' dayn ha bangsa Yahudi.",
        23: "Na, bihaun dimatung na in waktu sin pagpudji sin manga tau dayn ha lawm atay nila tuud iban dayn ha kasabunnalan. Karna' biya' ha yan in kabayaan sin Tuhan bang in tau magpudji kaniya.”",
        24: "Iban laung hi Īsa, “Tuhan in puunan sin nyawa, lāgi' in siya nyawa da isab. Bukun siya biya' sin mānusiya' tagabaran. Hangkan hisiyu-siyu in mamudji kaniya subay tuud dayn ha lawm atay iban dayn ha kasabunnalan.”",
        25: "Laung sin babai kan Īsa, “Asal kaingatan ku ha waktu susūngun dumatung mari in Almasi. Pagdatung niya mari, hibayta' niya kātu'niyu in unu-unu katān.”",
        26: "In sambung hi Īsa kaniya, laung niya, “In piyag'iyan mu yan amuna in diyarā mu nagbichara bihaun.”",
        27: "Ha sa'bu hi Īsa nagbibichara iban sin babai, dimatung na in manga mulid hi Īsa. Landu' tuud sila nainu-inu pagkita' nila nagbibichara hi Īsa iban sin babai. Sagawa' wayruun tuud minsan hambuuk kanila in timawakkal mangasubu ha babai bang unu in gawi niya atawa nangasubu kan Īsa bang mayta' niya diyā nagbichara in babai.",
        28: 'Na, binīn sin babai in kibut niya, ampa siya nagbalik pa kawman nanuysuy ha manga tau.',
        29: "Laung niya ha manga tau, “Kari kamu agad kāku' kimita' sin tau amu in namayta' kāku' sin katān bakas nahinang ku. Bukun baha' siya na in Almasi?”",
        30: "Na, in manga tau kiyabaytaan duun ha kawman miyadtu na kimita' kan Īsa.",
        31: "Sin wala' pa dimatung mawn in manga tau, siyagina na hi Īsa sin manga mulid niya pakaunun. Laung nila, “Tuwan Guru, bang kaw isab kimaun na muna!”",
        32: "Sagawa' in sambung hi Īsa kanila, “Awn da kakaun ku amu in di' niyu kaingatan.”",
        33: "Na, nag'asubu-iyasubuhi na in manga mulid niya. Laung nila, “Awn baha' tau dimā mari kaniya kakaun?”",
        34: "“In makarihil kāku' kusug,” laung hi Īsa, “in magad sin daakan sin Tuhan, amu in nagdaak kāku' mari, subay ku ubusun hinangun in katān daakan niya.",
        35: "Na, biya' na sin agi niyu upat bulan pa in lugay ampa makapag'ani in tau sin tiyanum niya. Sa' baytaan ta kamu, bihaun waktu na sin pag'ani. Atura niyu ba in manga tau sūng mari. In sila yan biya' sapantun manga tiyanum amu in matūp na anihun. Bukun na mawgay magparachaya na sila kāku'!",
        36: "Na, hisiyu-siyu in tau makarā ha manga tau magad sin hindu' ku, awn tungbas kaniya marayaw, iban in manga tau mapaagad nila, awn na kabuhi' salama-lama. Na, bang ibārat nagtanum, in tau nagtanum iban sin tau nag'aani kūgan sila karuwa bang sila makaani na. Na, biya' da isab ha yan in hantang sin tau nagpamahalayak sin Bayta' Marayaw iban sin mangangawa' tau magpaagad sin hindu' ku, magkūg-kuyag sila karuwa.”",
        37: "Laung pa isab hi Īsa, “Bunnal tuud in agi sin kamaasan natu' yadtu, amu agi, ‘Dugaing in magtanum, dugaing isab in umaani!’",
        38: "Na, in kamu yan kiyawakilan ku umani sin bukun niyu tiyanum. Dugaing in nagsangsa', sa' kamu in magkawa' magpajatu sin bunga.”",
        39: 'Manjari mataud tau Samariya in nagparachaya kan Īsa, sabab sin bichara sin babai, amu agi, “Biyaytaan aku sin tau sin katān bakas nahinang ku.”',
        40: "Na, hangkan nakakawn mayan in manga tau Samariya kan Īsa, piyangayu' nila kan Īsa pahantiun duun kanila. Na, himanti' hi Īsa duun kanila duway adlaw.",
        41: "Lāgi' dayn ha sabab sin pagnasīhat hi Īsa ha manga tau timaud in nagparachaya kaniya.",
        42: "Iban laung sin manga tau Samariya ha babai, “Bihaun magparachaya na tuud kami kan Īsa bukun sadja ha pasal sin suysuy mu, sa' diyungug namu' na tuud in hindu' niya. Iban kaingatan namu' na sin siya na tuud in Manglalappas ha manga mānusiya' dī ha dunya.”",
        43: "Na, pag'ubus hinda Īsa nakahanti' duun duway adlaw, limanjal na sila pa Jalil.",
        44: "Asal nakapamung hi Īsa, laung niya, “In hambuuk nabi di' siya lagguun ha luggiya' hula' niya.”",
        45: "Pagdatung nila pa Jalil siyampang na sila sin manga tau duun, sabab in manga tau ini bakas nakakita' sin katān nahinang hi Īsa ha adlaw pagjamu ha sa'bu nila didtu ha Awrusalam himadil sin Haylaya Paglappas dayn ha Kamatay.",
        46: "Pag'ubus yadtu nagbalik na hinda Īsa pa kawman Kana ha Jalil. Duun ha Kana napapanjari hi Īsa tubig anggul in tubig. Sakali awn hambuuk upisyal dayn ha Kapirnaum, amu in kiyarihilan kawasa sin sultan, in nakasa'bu isab duun. In anak niya usug tagasakit.",
        47: "Pag'ingat niya sin yaun hi Īsa ha Jalil bakas dayn ha Yahudiya, miyadtu siya kan Īsa jimunjung paagarun pa Kapirnaum ha supaya kaulian in anak niya nasasakit pangsan.",
        48: "Laung hi Īsa kaniya, “Subay sadja kamu makakita' manga tanda' iban manga mu'jijat ampa kamu magparachaya.”",
        49: "In sambung sin upisyal, “Andu' Tuwan, agad na kaw mari kāku' sabab in anak ku ha ūt na sin kamatay iban kabuhi'.”",
        50: "Laung hi Īsa kaniya, “Kadtu na kaw uwi'. Uli' na in anak mu!” Na, nagkahagad in tau ini sin bichara kaniya hi Īsa iban magtūy na siya minuwi'.",
        51: "Na, ha sa'bu niya miyanaw tudju pa bāy niya, piyaglanggal siya sin manga daraakun niya. Laung nila kaniya, “In anak mu uli' na!”",
        52: "Sakali iyasubu niya sila, laung niya, “Manga lisag pila imuli' in sakit niya?” Laung nila, “Naīg in hinglaw niya lisag hambuuk sin kahapun mahapun.”",
        53: "Na, kiyatumtuman sin ama' sin bata'-bata' sin amuna isab yadtu in waktu sin pagbichara hi Īsa kaniya, amu agi, “Uli' na in anak mu!” Na, dayn didtu nagparachaya siya kan Īsa iban sin manga tau ha lawman niya.",
        54: "Na, amu yan in hikaruwa mu'jijat nahinang hi Īsa pag'ubus niya nagbalik dayn ha Yahudiya pa Jalil.",
    },
    5: {
        1: "Manjari manga pilay adlaw mayan nakalabay, timukad hinda Īsa pa Awrusalam suma'bu sin hambuuk hinang pagjamu sin manga Yahudi.",
        2: 'Na, duun ha Awrusalam awn tubig amu in pagtawagun, bang ha bahasa Yahudi, Bitsatta, masuuk pa hambuuk lawang sin dāira amu in pagngānan Lawang Bili-bili. Iban awn duun lima bāy-bāy pagsisilungan ha daig sin tubig.',
        3: "Na, mataud tuud tau nasasakit in kimukulang duun ha bāy-bāy. In kaibanan buta, iban in kaibanan pingka', di' makapanaw, iban in kaibanan nagpapatay in baran.",
        4: "In manga tau nasasakit ini, timatagad duun sin pagbukal sin tubig, sabab awn waktu mawn in malāikat sin Tuhan magpabukal sin tubig. Na hisiyu-siyu in makakadtu muna ha sa'bu nagbubukal in tubig kaulian in sakit niya, minsan sakit unu.",
        5: 'Manjari awn hambuuk tau nasasakit duun. Katluan tagwalu tahun na in lugay niya nāsakit.',
        6: "Pagkita' hi Īsa, kiyaingatan niya magtūy sin malugay na in sakit niya. Manjari iyasubu siya hi Īsa, amu agi, “Mabaya' kaw kaulian?”",
        7: "Laung sin tau nāsakit kan Īsa, “Huun, Tuwan, sagawa' wayruun makabuhat kāku' mawn pa lawm tubig bang in tubig magbukal na. Iyampa namān aku imilud, awn na magtūy makauna dayn kāku'.”",
        8: 'Na, laung hi Īsa kaniya, “Tindug na kaw. Mumusa na in kulangan mu ampa kaw panaw na.”',
        9: "Saruun-duun kiyaulian in tau nāsakit. Miyumus niya na in kulangan niya ampa siya miyanaw. Na, in adlaw yadtu, adlaw Sabtu', amu in adlaw paghali-hali iban pagpudji pa Tuhan sin manga bangsa Yahudi.",
        10: "Sakali laung sin manga nakura' sin manga Yahudi ha tau bakas nāsakit, “Uy, adlaw ini, adlaw paghali-hali iban pagpudji pa Tuhan. Langgal sara' natu' in magmumus kaw sin kulangan mu yan.”",
        11: "In sambung sin tau bakas nāsakit, laung niya, “In agi sin tau nagpauli' sin sakit ku, hipamumus na in kulangan ku iban diyaak niya na aku papanawun.”",
        12: "In agi sin manga nakura' Yahudi, “Hisiyu in tau dimaak kaymu biya' hādtu?”",
        13: "Sagawa' di' kaingatan sin tau bakas nāsakit bang hisiyu in tau nagpauli' kaniya, sabab mataud tuud tau duun ha daig tubig iban in hi Īsa minīg magtūy.",
        14: "Manjari pagpuas yadtu, kīta' hi Īsa nagbalik in tau amu in bakas nāsakit didtu ha lawm Bāy sin Tuhan. Laung hi Īsa kaniya, “Kitaa ba, kiyaulian na in sakit mu. Hangkan ayaw na kaw maghinang sin manga hinang makarusa ha supaya wayruun mangī' kumugdan kaymu labi pa dayn sin bakas sakit mu.”",
        15: "Na, pag'ubus, gimuwa' na in tau bakas nāsakit ampa miyadtu namayta' ha manga nakura' Yahudi sin hi Īsa in tau nagpauli' sin sakit niya.",
        16: "Hangkan sainagun sin manga nakura' Yahudi pinjalaun nila hi Īsa, sabab nagpauli' siya sin tau nasasakit ha adlaw hipaghali-hali pa Tuhan.",
        17: "Sagawa' in sambung hi Īsa kanila, laung niya, “In Tuhan, Ama' ku, di' magbugtu' in paghinang niya. Na, damikkiyan in aku subay ku isab di' bugtuun in paghinang ku.”",
        18: "Pagdungug sin manga nakura' Yahudi sin bichara hi Īsa diyugalan tuud sila. Kimusug na tuud in baya' nila mamunu' kan Īsa sabab bukun sadja pasal sin pagpauli' niya ha tau nasasakit ha adlaw hipaghali-hali iban pagpudji pa Tuhan, sagawa' imiyan siya sin Ama' niya in Tuhan, iban piyakita' niya sin siya sibu' iban Tuhan.",
        19: "Manjari laung hi Īsa ha manga nakura' Yahudi, “Baytaan ta kamu sin kasabunnalan. Di' ku mahinang in manga nahinang ku yan bang baran-baran ku sadja, sagawa' unu-unu in kīta' ku hīhinang sin Tuhan, Ama' ku, amu isab in agarun ku hinangun. Sibu' tuud in hinang sin Ama' iban sin Anak.",
        20: "Karna' dayn ha sabab landu' tuud in lasa kāku' sin Tuhan, Ama' ku, piyaiingat niya kāku' in katān hinang niya. Ha susūngun awn pa hipahinang sin Tuhan, Ama' ku, amu in labi pa dayn sin manga nahinang ku hayn-duun iban mainu-inu tuud kamu.",
        21: "In Tuhan, Ama' ku, makarihil kabuhi' ha miyamatay. Na, damikkiyan in aku, Anak niya, makarihil kabuhi' ha hisiyu-siyu tau miyamatay kabayaan ku buhiun.",
        22: "Lāgi' bukun Tuhan, Ama' ku, in manghukum ha manga mānusiya', sabab kiyasuku' niya na kāku' in kawasa manghukum ha manga mānusiya',",
        23: "ha supaya aku lagguun sin mānusiya' katān biya' da isab sin paglaggu' nila ha Tuhan. Hisiyu-siyu in di' manglaggu' kāku', hāti niya wala' niya da isab liyaggu' in Tuhan amu in nagpakari kāku'.”",
        24: "Laung pa isab hi Īsa kanila, “Baytaan ta kamu sin kasabunnalan. Hisiyu-siyu in dumungug sin bichara ku iban magparachaya ha nagdaak kāku' mari, awn kabuhi' niya salama-lama, iban di' na siya kugdanan sin hukuman pakadtuun pa narka'. Mapuas na siya dayn ha kasiksaan salama-lama. Gām mayan awn na kabuhi' niya kasaumulan.",
        25: "Baytaan ta kamu sin kasabunnalan,” laung hi Īsa, “bihaun dimatung na in waktu, awn makabuhi' magbalik ha manga patay bang sila dumungug sin suwara ku amu in Anak Tuhan, iban kaawnan na sila sin kabuhi' salama-lama.",
        26: "Karna' in aku biya' da tuud isab Tuhan, Ama' ku, amu in puunan sin kabuhi' sabab sin kawasa kiyarihil niya kāku'.",
        27: "Lāgi' asal aku kiyarihilan kawasa sin Tuhan, Ama' ku, manghukum ha manga mānusiya' sabab aku in Anak Mānusiya'.",
        28: "“Sagawa' ayaw kamu mainu-inu sin pamung ku ini. Ha susūngun in katān patay makarungug da sin suwara ku, amu in suwara sin Anak Mānusiya'.",
        29: "Na, pagdungug nila sin suwara ku, magtūy sila mabuhi' magbalik iban gumuwa' na sila dayn ha lawm kubul. Na, in sasuku' sin bakas nakahinang marayaw mabuhi' na magbalik dayn ha kamatay, iban karihilan na kabuhi' salama-lama, sagawa' in sasuku' sin bakas nakahinang mangī', mabuhi' da isab magbalik ha supaya sila kabutangan hukuman sin narusa nila.”",
        30: "Laung pa isab hi Īsa, “Di' aku makahinang unu-unu bang baran-baran ku sadja. Minsan in manghukum bukun hinang sin baran-baran ku, sa' in yan daakan sin Tuhan kāku'. Hangkan in panghukum ku mabuntul tuud sabab kabayaan sin Tuhan in iyaagad ku, amu in nagdaak nagpakari kāku'. Bukun kabayaan ku in iyaagad ku.",
        31: "“Lāgi' bang aku sadja in mamayta' kaniyu pasal sin baran ku di' kamu magkahagad sin bunnal in bichara ku.",
        32: "Sagawa' awn dugaing namayta' kaniyu pasal ku, ampa kaingatan ku in bayta' niya pasal ku bunnal tuud.",
        33: '“Piyakadtu niyu in manga daraakun niyu nangusihat kan Yahiya. Na biyaytaan niya sila sin kasabunnalan pasal ku.',
        34: "Malayngkan, di' aku magkagunahan tau mamayta' sin pasal ku, sagawa' siyabbut ku hi Yahiya kaniyu ha supaya kamu malappas.",
        35: "In hi Yahiya biya' sapantun hambuuk palitaan nalalaga dumihil kasawahan pa manga mānusiya'. Kiyaamuhan kamu sin hindu' niya, sagawa' hangkaray' da.",
        36: "“Sagawa' awn da mamayta' pasal ku amu in labi pa dayn sin bayta' hi Yahiya. In hinang ku amuna in mamayta' kaniyu sin pasal ku. Naraak aku sin Tuhan, Ama' ku, tumalus sin hinang kiyasuku' niya hipahinang kāku'. Na, in yan amuna in tanda' sin in aku kiyawakilan sin Tuhan mari.",
        37: "Lāgi' minsan in Tuhan, Ama' ku, amu in nagdaak mari kāku', simaksi' da isab sin pasal ku. Sagawa' wala' tuud kamu dimungug sin suwara niya, iban wala' niyu tuud kīta' in jāt niya.",
        38: "Iban wala' himūp pa lawm atay niyu in Parman niya, sabab di' kamu magparachaya ha amu in naraak niya mari.",
        39: "Matuyu' tuud kamu mangadji' sin luun sin manga Kitab sabab in pangannal niyu bang niyu pangadjiun in luun sin manga Kitab makabaak kamu kabuhi' salama-lama. Na, in manga Kitab piyangadji' niyu yan namayta' sin pasal ku!",
        40: "Sagawa' matugas in atay niyu. Masi kamu di' magparachaya kāku' minsan da aku in makarihil kaniyu sin kabuhi' salama-lama.”",
        41: "Laung pa isab hi Īsa, “Bukun kalagguan dayn ha mānusiya' in kabayaan ku.",
        42: "Sagawa' kaingatan ku bang unu in ha lawm atay niyu. Wayruun lasa niyu ha Tuhan.",
        43: "Miyari aku iban kawasa kiyarihil kāku' sin Tuhan, Ama' ku, sagawa' di' kamu magkahagad kāku'. Sagawa' bang awn tau dugaing magpakita' kaniyu sin kawasa niya magkahagad kamu kaniya.",
        44: "Asal di' kamu makakahagad kāku' sabab in piyagtutuyuan niyu in kabantugan dayn ha pagkahi niyu mānusiya'. Wayruun tuyu' niyu sin kabantugan dayn ha hambuuk-buuk Tuhan.",
        45: "“Na, ayaw kamu magpikil sin aku in mamayta' sin manga dusa niyu pa Tuhan, Ama' ku, bang maabut na in adlaw paghukum. Sabab in hi Musa amu in bakas nagpasampay kaniyu sin sara' iyaagad niyu, amu in mamayta' sin manga dusa niyu.",
        46: "Malayngkan, bang kamu bunnal tuud nagkahagad kan Musa, subay kamu magkahagad kāku', sabab kiyasulat niya ha lawm Kitab in pasal ku.",
        47: "Sagawa' pagga kamu di' magkahagad sin pasal kiyasulat hi Musa, na asal di' da kamu magkahagad sin hibayta' ku kaniyu.”",
    },
    6: {
        1: "Manjari ini, maray' na in haylaya sin bangsa Yahudi, amu in pagtawagun Haylaya Paglappas dayn ha Kamatay. Sakali imuntas na hinda Īsa pa hansipak sin Dagat Jalil, amu in pagtawagun Dagat Tibiri. Mataud tau in miyurul kanila, sabab kīta' nila in manga mu'jijat nahinang hi Īsa biya' na sin pagpauli' sin manga tau nāsakit. Na, pagdatung hinda Īsa, timukad hi Īsa iban sin manga mulid niya pa taas būd-būd, ampa sila limingkud duun.",
        2: "Manjari ini, maray' na in haylaya sin bangsa Yahudi, amu in pagtawagun Haylaya Paglappas dayn ha Kamatay. Sakali imuntas na hinda Īsa pa hansipak sin Dagat Jalil, amu in pagtawagun Dagat Tibiri. Mataud tau in miyurul kanila, sabab kīta' nila in manga mu'jijat nahinang hi Īsa biya' na sin pagpauli' sin manga tau nāsakit. Na, pagdatung hinda Īsa, timukad hi Īsa iban sin manga mulid niya pa taas būd-būd, ampa sila limingkud duun.",
        3: "Manjari ini, maray' na in haylaya sin bangsa Yahudi, amu in pagtawagun Haylaya Paglappas dayn ha Kamatay. Sakali imuntas na hinda Īsa pa hansipak sin Dagat Jalil, amu in pagtawagun Dagat Tibiri. Mataud tau in miyurul kanila, sabab kīta' nila in manga mu'jijat nahinang hi Īsa biya' na sin pagpauli' sin manga tau nāsakit. Na, pagdatung hinda Īsa, timukad hi Īsa iban sin manga mulid niya pa taas būd-būd, ampa sila limingkud duun.",
        4: "Manjari ini, maray' na in haylaya sin bangsa Yahudi, amu in pagtawagun Haylaya Paglappas dayn ha Kamatay. Sakali imuntas na hinda Īsa pa hansipak sin Dagat Jalil, amu in pagtawagun Dagat Tibiri. Mataud tau in miyurul kanila, sabab kīta' nila in manga mu'jijat nahinang hi Īsa biya' na sin pagpauli' sin manga tau nāsakit. Na, pagdatung hinda Īsa, timukad hi Īsa iban sin manga mulid niya pa taas būd-būd, ampa sila limingkud duun.",
        5: "Sakali pagkita' hi Īsa sin manga tau mataud sūng mawn kanila, namung siya ha hambuuk mulid niya hi Pilip, laung niya, “Hariin kita makabī pagkaun hipakaun ha manga tau ini?”",
        6: "(Hangkan nangasubu biya' hādtu hi Īsa, sabab siyulayan niya bang awn da pangandul hi Pilip ha kawasa niya. Malayngkan, asal kaingatan na hi Īsa bang unu in hinangun niya.)",
        7: "In sambung hi Pilip, “Tuwan, minsan in gadji sin hinang walu bulan in hipamī tinapay di' da makakaunan ha taud sin manga tau yan, minsan da hangkatiyu' in hirihil kanila, di' da makajarihan.”",
        8: 'Sakali simambung in hambuuk mulid hi Īsa hi Andariyas, amu in taymanghud hi Simun Pitrus, laung niya,',
        9: "“Yari awn hambuuk bata' usug nagdarā lima tinapay iban duwa ista'. Sagawa' tantu tuud di' ini makajarihan hipakaun ha manga tau mataud ini.”",
        10: "Laung hi Īsa kanila, “Palingkura niyu in manga tau.” (Na, maluag in bayli duun lingkuran nila.) Na, limingkud na duun in manga tau. In taud sin manga tau minsan in usug sadja awn manga lima ngaibu, dugaing pa in manga babai iban sin manga bata'-bata'.",
        11: "Manjari kiyawa' na hi Īsa in tinapay ampa siya nagsarang-sukul pa Tuhan. Pag'ubus ampa niya piyagbahagi'-bahagi' in manga tinapay, piyarihil pa manga tau naglilingkud. Damikkiyan, piyagbahagi'-bahagi' niya da isab in ista' iban kiyarihilan in manga tau pila-pila na in taud sin kabayaan nila.",
        12: "Pagga kiyansuban na in manga tau, laung hi Īsa ha manga mulid niya, “Tipuna niyu in manga kakaun nakapin bat di' makawgun.”",
        13: "Na, tīpun na sin manga mulid hi Īsa in manga tinapay nakapin. Ha lawm sin lima tinapay yadtu piyakaun ha manga tau, in nakapin awn pa hangpu' tagduwa ambung.",
        14: "Sakali pagkita' sin manga tau duun sin mu'jijat nahinang hi Īsa, laung nila pakaniya-pakaniya, “Tantu amuna sa ini in nabi amu in piyag'iyan mari pa dunya!”",
        15: 'Na, asal kiyaingatan hi Īsa sin in manga tau sūng na mawn sumaggaw kaniya iban lugusun nila siya mahinang sultan nila. Hangkan timukad siya pa taas būd-būd isa-isa niya.',
        16: 'Sakali naabut mayan magrib, limūd na in manga mulid hi Īsa madtu pa higad dagat,',
        17: "ampa sila simakat pa taas kumpit asibi'. Na, pagga narūm na, wala' pa nakakawn hi Īsa kanila, timulak na sila harap pa Kapirnaum.",
        18: "Sakali kiyugdan sila sin hangin makusug ha dān iban alun dakula'.",
        19: "Nakarayung mayan sila kulang-labi lima usuk batu, kīta' nila na hi Īsa miyamanaw ha babaw sin dagat sūng mawn pa kumpit nila. Na, miyuga' tuud sila.",
        20: "Sakali laung hi Īsa kanila, “Ayaw kamu mabuga'. Aku sa ini.”",
        21: 'Na, piyasakat nila na hi Īsa pa taas kumpit. Nakasakat mayan hi Īsa, saruun-duun dimatung sila pa lugal kadtuun nila.',
        22: "Na, naadlaw mayan, in manga tau mataud (bakas piyakaun hi Īsa), masi duun ha hansipak sin Dagat Jalil. Kīta' nila sin hambuuk kumpit asibi' in nakatulak dayn duun. Iban kiyaingatan nila sin hi Īsa wala' nakaagad ha manga mulid niya timulak.",
        23: "Na, awn isab manga kumpit asibi' dayn ha dāira Tibiri in dimunggu' mawn pa lugal masuuk pa bakas piyagkaunan sin manga tau mataud pag'ubus hi Panghu' Īsa nagsarang-sukul pa Tuhan.",
        24: "Manjari pag'ingat sin manga tau sin wala' na duun hi Īsa iban sin manga mulid niya, simakat na sila pa manga kumpit asibi' harap pa Kapirnaum naglawag kan Īsa.",
        25: "Pagdatung sin manga tau mawn pa hansipak sin Dagat Jalil, kiyabaakan nila na hi Īsa. Laung nila kaniya, “Tuwan, ka'nu kaw dimatung mari?”",
        26: "In sambung hi Īsa kanila, “Baytaan ta kamu sin mattan. Hangkan niyu aku liyawag sabab kiyansuban kamu sin kakaun kahapun, sagawa' wala' nakasūd pa lawm pikilan niyu bang unu in hātihan sin manga mu'jijat nahinang ku, amu in kīta' niyu.",
        27: "Subay in pagsangsaan niyu bukun sadja amu in kakaun di' da tumatas malugay. Sagawa' subay labi niyu pagsangsaan in kakaun di' magkahagin salama-lama, amu in hikarihil kaniyu sin aku, amu in Anak Mānusiya'. Aku tuud in makarihil kaniyu sin kakaun yan, sabab aku in kiyawakilan sin Tuhan, Ama' ku, dumihil ha yan.”",
        28: "Na, iyasubu nila hi Īsa, laung nila, “Unu baha' in subay namu' hinangun bat namu' maagad in kabayaan sin Tuhan?”",
        29: "In sambung hi Īsa kanila, “Biya' ha ini in kabayaan sin Tuhan hipahinang kaniyu. Subay kamu magparachaya tuud kāku' amu in kiyawakilan sin Tuhan mari.”",
        30: "In sambung nila, “Unu in mu'jijat mapakita' mu kāmu', tanda' sin barakat mu ha supaya kami magparachaya kaymu? Ha waktu sin manga kamaasan natu' yadtu didtu ha hula' paslangan mahunit paghulaan, in kiyaun nila, amu in pagtawagun ‘manna’, hūg dayn ha langit. Biya' na sin kiyabayta' ha lawm Kitab, amu agi, ‘Patulunan niya sila kakaun dayn ha surga'!’ Na, in ikaw unu in mahinang mu?” laung sin manga tau kan Īsa.",
        31: "In sambung nila, “Unu in mu'jijat mapakita' mu kāmu', tanda' sin barakat mu ha supaya kami magparachaya kaymu? Ha waktu sin manga kamaasan natu' yadtu didtu ha hula' paslangan mahunit paghulaan, in kiyaun nila, amu in pagtawagun ‘manna’, hūg dayn ha langit. Biya' na sin kiyabayta' ha lawm Kitab, amu agi, ‘Patulunan niya sila kakaun dayn ha surga'!’ Na, in ikaw unu in mahinang mu?” laung sin manga tau kan Īsa.",
        32: "In sambung hi Īsa kanila, “Baytaan ta kamu sin kasabunnalan. Bukun hi Musa in nagdihil sin kakaun dayn ha surga' ha manga kamaasan natu' yadtu. In Tuhan, Ama' ku, amu in nagdihil kanila sin kakaun dayn ha surga'. Siya da isab in dumihil sin kakaun sabunnal.",
        33: "Karna' in kakaun hirihil sin Tuhan amuna in naraak niya piyanaug dayn ha surga' mari pa dunya, amu in dumihil ha manga mānusiya' sin kabuhi' sabunnal.”",
        34: "Na, laung sin manga tau kan Īsa, “Tuwan, taptap kami dihili sin kakaun piyag'iyan mu yan.”",
        35: "Laung hi Īsa kanila, “Aku na ini in kakaun amu in makarihil sin kabuhi'. Hisiyu-siyu in mari magad kāku' di' na siya hapdiun kasaumulan, iban hisiyu-siyu in magparachaya kāku', di' na siya uhawun kasaumulan.",
        36: "Na, bakas ta na kamu biyaytaan sin minsan niyu aku kakitaan na, di' da kamu magparachaya kāku'.",
        37: "Sagawa' in sasuku' sin asal kiyasuku' kāku' sin Tuhan, Ama' ku, magparachaya da iban mari da magad kāku'. Na, taymaun ku tuud in hisiyu-siyu mari magad kāku'.",
        38: "Sabab in maksud ku miyari pa dunya dayn ha surga' bukun huminang sin kabayaan ku, sagawa' huminang sin kabayaan sin Tuhan amu in nagdaak kāku'.",
        39: "Na, in kabayaan sin Tuhan amu in nagdaak kāku', subay wayruun malawa' dayn kāku' minsan hambuuk dayn ha manga asal kiyasuku' niya kāku'. Lāgi' subay ku sila buhiun katān magbalik dayn ha kamatay ha adlaw mahuli.",
        40: "Karna' in kabayaan sin Tuhan, Ama' ku, in sasuku' sin makakita' kāku', amu in Anak Tuhan, iban nagparachaya kāku', subay dihilan kabuhi' salama-lama, iban ha adlaw mahuli buhiun ku sila magbalik dayn ha kamatay.”",
        41: "Na, kimangī' in atay sin manga tau pasal sin pamung hi Īsa sin in siya amuna in kakaun dayn ha surga'.",
        42: "Hangkan piyagbicharahan nila in pamung hi Īsa, laung nila, “Mayta' in tau ini imiyan dayn ha surga' siya? Bukun ka in siya hi Īsa, anak hi Yusup? Kaingatan natu' in ina'-ama' niya.”",
        43: "In sambung hi Īsa kanila, “Hundung na kamu magbichara biya' ha yan.",
        44: "Way tau mari magad kāku' bang siya di' dihilan baya' sin Tuhan, Ama' ku, amu in nagdaak kāku' mari. Iban buhiun ku siya magbalik dayn ha kamatay ha adlaw mahuli.",
        45: "Kiyasulat sin manga kanabihan ha lawm Kitab, amu agi, ‘In katān mānusiya' hinduan sin Tuhan.’ Na,” laung hi Īsa, “hisiyu-siyu in makarungug iban magkahagad sin hindu' sin Tuhan, Ama' ku, mari da siya magad kāku'.",
        46: "Malayngkan bukun in hāti niya yan bat awn nakakita' ha Tuhan, sabab amura aku in nakakita' ha Tuhan, Ama' ku, karna' in aku dayn ha Tuhan.”",
        47: "Laung pa isab hi Īsa, “Baytaan ta kamu sin kasabunnalan. Hisiyu-siyu in magparachaya kāku' awn kabuhi' niya salama-lama.",
        48: "Aku na ini in kakaun amu in makarihil sin kabuhi'.",
        49: "In manga kaapu'-apuan niyu yadtu miyatay da didtu ha hula' paslangan mahunit paghulaan, minsan ‘manna’ in kiyaun nila.",
        50: "Sagawa' in kakaun dayn ha surga' piyag'iyan ku kaniyu dugaing tuud. Hisiyu-siyu in makakaun ha yan di' siya mapatay.",
        51: "Aku na ini in kakaun dayn ha surga' amu in puunan sin katān kabuhi'. Hisiyu-siyu in kumaun sin kakaun ini awn kabuhi' niya salama-lama. In kakaun hipakaun ku kaniya amuna in unud ku. Hililla' ku in dugu'-nyawa ku ha supaya awn kabuhi' sin mānusiya' katān.”",
        52: "Na, nagpasu' in paglugat sin manga tau pasal sin pamung hi Īsa. Laung nila, “Biya' diin in kaagi sin tau ini magpakaun kātu' sin unud niya?”",
        53: "Laung hi Īsa kanila, “Baytaan ta kamu sin kasabunnalan. Bang kamu di' kumaun sin unud ku amu in Anak Mānusiya', iban di' minum sin dugu' ku wayruun kabuhi' niyu.",
        54: "Hisiyu-siyu in kumaun sin unud ku iban minum sin dugu' ku awn kabuhi' niya salama-lama, iban buhiun ku siya magbalik dayn ha kamatay ha adlaw mahuli.",
        55: "Sabab in unud ku iban dugu' ku amuna in kakaun iban iinumun di' magkahagin sampay kasaumulan.",
        56: "Hisiyu-siyu in kumaun sin unud ku iban minum sin dugu' ku, in pikilan iban atay niya himahambuuk kāku'. Damikkiyan, in aku himahambuuk da isab kaniya.",
        57: "In Tuhan, Ama' ku, amu in nagdaak kāku' mari. Asal siya in puunan sin katān kabuhi'. Na, dayn ha sabab niya awn kabuhi' ku. Damikkiyan biya' da isab ha yan in hisiyu-siyu kumaun kāku', awn kabuhi' niya dayn ha sabab ku.",
        58: "Na, aku in tantu tuud kakaun dayn ha surga'. Bukun biya' sin kakaun kiyaun sin manga kaapu'-apuan niyu yadtu. Sabab minsan sila kimaun hādtu, miyatay da sila. Sagawa' hisiyu-siyu in kumaun sin kakaun tantu tuud dayn ha surga', awn kabuhi' niya kasaumulan.”",
        59: "Amu yan in manga hindu' hi Īsa didtu ha lawm sin langgal ha Kapirnaum.",
        60: "Na, kamatauran sin manga mulid hi Īsa nakarungug sin pagnasīhat niya. Laung nila, “In hindu' niya yan mahunit agarun. Wayruun mabaya' dumungug ha yan!”",
        61: "Sakali asal kiyatalusan hi Īsa in piyagdubduban sin manga tau. Hangkan laung niya kanila, “Maray' kimangī' in atay niyu sin hindu' ku.",
        62: "Na, maray' luba' pa in ngī' sin atay niyu bang niyu kakitaan in aku amu in Anak Mānusiya', magbalik pa surga' (amu in asal hulaan ku).",
        63: "In Rū sin Tuhan amuna in makarihil sin kabuhi' sabunnal. Bang baran-baran niyu hadja wayruun kabuhi' sabunnal makawa' niyu. In hindu' ku amu in makarihil kaniyu kabuhi' sabunnal sabab in yan guwa' dayn ha Rū sin Tuhan.",
        64: "Sagawa',” laung hi Īsa, “in kaibanan kaniyu di' magparachaya.” (Hangkan hi Īsa namung biya' ha ini sabab asal niya kiyaingatan dayn sin tagna' bang hisiyu in manga tau di' magparachaya kaniya iban bang hisiyu in tumipu kaniya ha susūngun.)",
        65: "Laung pa isab hi Īsa, “Hangkan asal ta kamu biyaytaan sin way tau mari magad kāku' bang siya bukun dihilan baya' sin Tuhan, Ama' ku.”",
        66: "Na, dayn ha sabab sin pamung hi Īsa, mataud in manga mulid niya minīg, iban wala' na miyagad kaniya.",
        67: "Hangkan iyasubu hi Īsa in hangpu' tagduwa mulid niya, laung niya, “Na, biya' diin in kamu yan? Mabaya' isab kamu mīg biya' kanila?”",
        68: "In sambung hi Simun Pitrus kaniya, “Tuwan, hisiyu pa in kadtuan namu' dugaing dayn kaymu? Amura hindu' mu in makarihil sin kabuhi' salama-lama.",
        69: "Magparachaya na tuud kami kaymu bihaun iban kaingatan namu' na tuud sin ikaw na in hambuuk-buuk mahasuchi naug dayn ha Tuhan.”",
        70: "In sambung hi Īsa, “In kamu hangpu' tagduwa napī' ku magad kāku'. Sagawa' in hambuuk kaniyu saytan.”",
        71: "In piyag'iyan hi Īsa hi Judas amu in anak hi Simun tau dayn ha Kiriyud. In hi Judas hambuuk sin manga hangpu' tagduwa mulid hi Īsa, sagawa' siya in timipu kan Īsa.",
    },
    7: {
        1: "Pag'ubus yadtu miyanaw hi Īsa ha lawm hula' Jalil. Di' siya mabaya' madtu pa lawm hula' Yahudiya sabab biyabantuhan siya bunuun sin manga nakura' Yahudi.",
        2: "Sakali masuuk na in Paghaylaya amu in waktu sin manga Yahudi maghanti' ha manga kūbung-kūbung.",
        3: "Hangkan laung sin manga taymanghud usug hi Īsa kaniya, “Subay kaw di' dimī. Subay kaw madtu pa Yahudiya ha supaya kakitaan sin manga mulid mu in hinang mu.",
        4: "Wayruun tau magtapuk sin hinang niya bang siya mabaya' mabantug. Na, pagga kaw makahinang sin manga mu'jijat, na kadtu kaw paingata in mānusiya' katān sin pasal mu!” Na, amu yan in bichara sin manga taymanghud hi Īsa.",
        5: "(Minsan in manga taymanghud tuud hi Īsa di' da magparachaya kaniya.)",
        6: "Laung hi Īsa kanila, “Wala' pa naabut in waktu ku madtu magpakita' kanila. Bukun aku biya' kaniyu makakadtu minsan ku'nu waktu.",
        7: "Sabab in kamu di' karugalan sin manga tau. Ampa in aku karugalan nila sabab daran ku sila biyabaytaan sin mangī' in hinang nila.",
        8: "Kadtu na kamu pa paghaylayahan. Di' pa aku madtu pa paghaylayahan, sabab wala' pa naabut in waktu ku madtu.”",
        9: 'Na, amu yan in pamung hi Īsa ha manga taymanghud niya. Nagpabīn siya na muna ha Jalil.',
        10: "Sakali nakataykud mayan in manga taymanghud niya, miyadtu hi Īsa imurul pa paghaylayahan. Sagawa' tapuk kaagi in pagkadtu niya hangkan wala' nakaingat in manga tau sin yaun siya ha paghaylayahan.",
        11: "Manjari didtu ha paghaylayahan piyaglawag hi Īsa sin manga nakura' Yahudi. Piyangasubu nila bang hawnu hi Īsa.",
        12: "Mataud tau ha paghaylayahan in naghagas-hagas pasal hi Īsa. Laung sin kaibanan, “In hi Īsa tau marayaw.” Sagawa' laung isab sin kaibanan, “Bukun siya tau marayaw, sabab mangdupang sadja siya ha manga tau.”",
        13: "Sagawa' wayruun minsan hambuuk tau in timawakkal nagpatampal namichara pasal hi Īsa sabab mabuga' sila ha manga nakura' Yahudi.",
        14: "Maray' mayan matunga' in paghaylaya, miyadtu hi Īsa pa halaman sin Bāy sin Tuhan nanghindu' ha manga tau.",
        15: "Na, nainu-inu tuud in manga nakura' Yahudi sin paghindu' hi Īsa. Laung nila, “Dayn diin baha' nakawa' sin tau ini in ingat niya sin wala' siya minsan nakapangadji'?”",
        16: "In sambung hi Īsa kanila, “In panghindu' ku ini bukun dayn ha ingat ku, sagawa' dayn ha Tuhan amu in nagdaak kāku' mari.",
        17: "Bang in tau matuyu' tuud magad ha kabayaan sin Tuhan, tantu kaingatan niya bang in panghindu' ku ini dayn ha Tuhan atawa dayn ha baran ku sadja.",
        18: "Sabab, bang in tau manghindu' dayn ha ingat niya sadja, hāti niya in tau yan kumā' sadja kalagguan pa baran niya. Sagawa' bang in tau yan matuyu' manglaggu' ha nagdaak kaniya, hāti niya in tau yan mabuntul iban bukun siya pangakkal.",
        19: "Binīn hi Musa kaniyu in sara' daakan sin Tuhan, sagawa' minsan hambuuk kaniyu wayruun da namawgbug sin sara' yan. Na, mayta' aku in kabayaan niyu patayun?”",
        20: "Laung sin manga tau kan Īsa, “Siyasaytan kaw tuud yan! Wayruun sān tau mabaya' mamunu' kaymu.”",
        21: "In sambung hi Īsa kanila, “Hambuuk da mu'jijat in nahinang ku ha adlaw paghali-hali iban pagpudji pa Tuhan, hāti magtūy na kamu nainu-inu katān.",
        22: "In daakan binīn kaniyu hi Musa, subay niyu islamun in manga anak niyu usug. Sagawa' in sara' yan timagna' dayn ha manga kaapu'-apuan niyu, amu in nakauna pa dayn kan Musa. Hangkan minsan adlaw paghali-hali iban pagpudji pa Tuhan mang'islam da kamu ha anak niyu usug.",
        23: "Na, pagga kamu mang'islam ha manga anak niyu minsan adlaw paghali-hali iban pagpudji pa Tuhan ha supaya niyu maagad in sara' daakan hi Musa, na mayta' kamu dugalan kāku' sawkat na aku nagpauli' ha tau nāsakit ha adlaw paghali-hali iban pagpudji pa Tuhan?",
        24: "Ayaw kamu magtūy magpikil sin in aku tau mangī', sawkat na kamu wala' kiyaamuhan sin hinang ku. Gām mayan pabuntula in pamikil niyu.”",
        25: "Na, awn manga kaibanan tau duun dayn ha Awrusalam in nagbichara pasal hi Īsa. Laung nila, “Bukun ka in tau yan amu in piyaglalawag sin manga nakura' natu' Yahudi, kabayaan nila patayun?",
        26: "Kitaa niyu ba, yaun siya namimichara ha mayran madjīlis, sagawa' di' siya minsan lāngun sin manga nakura'. Maray' nakaingat na tuud in manga nakura' sin hi Īsa amuna in Almasi, amu in kiyawakilan sin Tuhan magbaya' ha bangsa natu'.",
        27: "Sagawa',” laung sin manga tau, “bang kunu' mari in Almasi wayruun makaingat bang dayn diin siya. Sagawa' in hi Īsa ini kaingatan natu' bang dayn diin siya.”",
        28: "Na, kiyaingatan hi Īsa in piyagbichara nila. Hangkan, piyatanug niya in tingug niya ha sa'bu niya nanghihindu' ha halaman sin Bāy sin Tuhan. Laung niya, “Bunnal kaingatan niyu aku iban kaingatan niyu bang dayn diin aku, sa' wala' aku miyari dayn ha baya' ku sadja, sagawa' naraak aku mari sin Tuhan amu in di' magputing. Di' niyu kaingatan bang hisiyu tuud siya,",
        29: "sagawa' kaingatan ku siya sabab dayn didtu aku kaniya iban siya in nagdaak kāku' mari.”",
        30: "Manjari apit nila saggawun hi Īsa, sagawa' way minsan hambuuk in nakakaput kaniya sabab wala' pa naabut in waktu sin pagpatay kaniya.",
        31: "Sagawa' mataud in manga tau nagparachaya kan Īsa. Laung nila, “Way na tau dugaing tagaran natu' magbaya' ha bangsa natu'. Hi Īsa na tuud in Almasi sabab way na makaliyu sin taud sin mu'jijat nahinang hi Īsa.”",
        32: "Sakali diyungug sin manga Parisi bang unu in piyaghagas-hagasan sin manga tau pasal hi Īsa. Hangkan in manga Parisi iban sin manga nakura' kaimaman magtūy nagdaak manga pulis jaga madtu sumaggaw kan Īsa.",
        33: "Na, laung hi Īsa ha manga tau natitipun duun, “In aku di' makalugay dī kaniyu. Masuuk na aku muwi' magbalik pa nagdaak kāku' mari.",
        34: "Lawagun niyu aku, sagawa' di' niyu aku kabaakan, sabab di' kamu makakadtu pa hulaan uwian ku.”",
        35: "Na, nagbichara in manga nakura' Yahudi pakaniya-pakaniya, “Pakain baha' in kadtuan sin tau ini ha di' natu' siya kabaakan? Maray' madtu siya pa manga dāira sin bangsa Girik, amu in piyaghuhulaan sin manga pagkahi natu' hangka-bangsa, amu in napulak-palik ha kahula'-hulaan. Maray' madtu siya manghindu' ha manga bangsa Girik.",
        36: "Laung niya, lawagun natu' siya sagawa' di' natu' siya kabaakan, iban di' kitaniyu makakadtu pa hula' kadtuan niya. Unu baha' in hātihan sin bichara niya yan?”",
        37: "Na, naabut mayan in adlaw umbulsatu amu in kahinapusan na sin pagjamu, timindug hi Īsa ampa niya piyatanug in bichara niya, laung niya, “Hisiyu-siyu kamu in mauhaw, kari kamu kāku', painumun ta kamu.",
        38: "Biya' na sin kiyabayta' ha lawm Kitab, ‘Hisiyu-siyu in magparachaya kāku', awn biya' sapantun tubig tumubud way pagbugtu' dayn ha lawm atay niya, amu in makarihil kaniya kabuhi' tantu.’”",
        39: "In piyagbichara hi Īsa ini pasal sin Rū sin Tuhan, amu in tumulun pa hisiyu-siyu magparachaya kaniya. Sagawa' ha waktu yadtu in Rū sin Tuhan wala' pa timulun pa mānusiya', sabab wala' pa naabut in waktu sin pagpakita' sin Tuhan sin kalagguan hi Īsa.",
        40: "Na, pagdungug sin manga tau mataud sin bichara hi Īsa, laung sin kaibanan, “Tantu in tau ini amuna in nabi piyagtatagaran natu'!”",
        41: "Laung isab sin kaibanan, “Siya na yan in Almasi!” Sagawa' laung isab sin kaibanan, “In Almasi di' gumuwa' dayn ha Jalil!",
        42: "Sabab kiyabayta' ha lawm Kitab sin in Almasi hambuuk panubu' hi Sultan Daud iban hipag'anak siya ha Baytlaham, amu in kawman hulaan hi Daud.”",
        43: "Na, nabahagi' in pikilan sin manga tau pasal hi Īsa.",
        44: "In kaibanan tau mabaya' sumaggaw kaniya, sagawa' way minsan hambuuk in nakakaput kaniya.",
        45: "Na, sakali nakabalik na in manga pulis jaga. Iyasubu sila sin manga Parisi iban sin manga nakura' kaimaman, amu agi, “Mayta' niyu siya wala' diyā mari?”",
        46: "In sambung sin manga jaga, “Wayruun pa tau in nakapanghindu' biya' sin dayaw sin panghindu' niya!”",
        47: "Laung sin manga Parisi ha manga jaga, “Sampay tuwi' kamu narupang niya da!",
        48: "Wayruun minsan hambuuk nakura' Yahudi atawa Parisi in magparachaya kaniya.",
        49: "Amura sa yan in magparachaya kaniya in manga tau yan amu in awam sin sara' daakan hi Musa. Hangkan sa in sila yan piyamumurkaan sin Tuhan!”",
        50: 'Sakali namichara hi Nikudimus amu in hambuuk Parisi bakas miyadtu kan Īsa. Laung niya,',
        51: "“Bang ha sara' natu' di' manjari in tau butangan hukuman bang siya wala' pa nasumariya iban di' pa kaingatan bang unu in sara' nalanggal niya.”",
        52: "In sambung nila, “Uy! Maray' kaw isab yan tau dayn ha Jalil. Kitaa madtu pa lawm Kitab bat mu kaingatan sin wayruun tuud nabi in guwa' dayn ha Jalil.”",
        53: "Pag'ubus yadtu, in tau katān nag'uwi' na.",
    },
    8: {
        1: "Sagawa' in hi Īsa miyadtu pa Būd Jaytun.",
        2: "Pagmahinaat, subu-subu pa miyadtu siya nagbalik pa halaman sin Bāy sin Tuhan. Na, in manga tau mataud nagtipun na isab katān mawn kaniya. Na limingkud hi Īsa ampa siya nanghindu' na isab ha manga tau.",
        3: "Sakali miyawn in manga guru sin sara' agama iban manga Parisi nagdā sin hambuuk babai bakas iyabutan nagjina iban sin usug bukun halal kawin niya. Piyatindug nila in babai ha alupan sin manga tau.",
        4: 'Laung nila kan Īsa, “Tuwan Guru, in babai ini mattan tuud iyabutan nagjina iban sin usug bukun halal kawin niya.',
        5: "Ha lawm sara' daakan hi Musa in babai abutan maghinang biya' ha yan subay tiluun sin batu patayun. Na, bang ikaw, unu in hukuman hirihil natu' kaniya?”",
        6: "Na, namung sila biya' ha yan bat nila malusut hi Īsa ha bichara, hāti makabāk sila dān hikatuntut kan Īsa. Sagawa' imanduk hi Īsa ampa siya nagsulat ha lupa' iban sin tudlu' niya.",
        7: "Sagawa' masi namān sila nangangasubu. Na, timunga hi Īsa ampa siya namung. Laung niya, “Hisiyu-siyu kaniyu in wayruun tuud dusa makajari na tumilu' batu ha babai yan.”",
        8: "Pag'ubus imanduk siya nagbalik ampa siya nagsulat ha lupa'.",
        9: "Pagdungug nila sin pamung hi Īsa, nag'inut-inut sila minīg hambuuk-hambuuk. Miyuna in manga tau maas ampa simunud in katān. Na, amura hi Īsa in nakapin duun iban sin babai masi nagtitindug.",
        10: "Timunga hi Īsa ampa siya namung ha babai, laung niya, “Inda', hawnu na in manga tau? Way na minsan hangka-tau nakapin mutang kaymu hukuman?”",
        11: "In sambung sin babai, “Way na, Tuwan.” “Na, marayaw na,” laung hi Īsa, “minsan in aku, di' da isab mutang kaymu sin hukuman patayun. Kadtu na kaw uwi', sagawa' ayaw na kaw maghinang magbalik sin makarusa.”",
        12: "Pag'ubus yadtu namichara na isab hi Īsa nagbalik ha manga tau. Laung niya, “Aku in ilaw amu in makarihil kasawahan ha mānusiya'. Hisiyu-siyu in magad kāku', kasaumulan di' na siya manaw ha katigidluman sabab awn na kasawahan niya amu in makarihil kaniya sin kabuhi' tantu.”",
        13: "Laung sin manga Parisi kaniya, “In ikaw yan magsaksi' sin baran mu. Bang in tau magsaksi' sin baran niya wayruun tau magkahagad kaniya.”",
        14: "In sambung hi Īsa kanila, “Minsan aku magsaksi' sin baran ku, bunnal in bichara ku sabab kaingatan ku bang dayn hayn in giyuwaan ku iban kaingatan ku da isab bang harap pakain in kadtuun ku. Sagawa' in kamu di' niyu kaingatan bang dayn diin in giyuwaan ku iban bang harap pakain in kadtuun ku.",
        15: "In kamu in panara' niyu ha tau labay dayn ha pikilan sadja sin mānusiya'. Ampa in aku di' aku manara' ha tau minsan hisiyu.",
        16: "Malayngkan,” laung hi Īsa, “bang aku in manara', mabuntul sadja in hukuman ku sabab bukun isa-isa ku in manara'. Duwa kami iban sin Ama' ku amu in nagdaak kāku' mari.",
        17: "Biya' na sin kiyabayta' ha lawm sara' niyu, bang awn duwangka-tau sumaksi' ampa magtaayun in daawa nila, hāti niya bunnal in bichara nila.",
        18: "Na, ha tungud sin kasabunnalan sin bichara ku, awn da isab duwa saksi', aku baran ku iban sin Ama' ku amu in nagdaak kāku' mari.”",
        19: "Imasubu in manga Parisi kan Īsa, amu agi, “Hariin in ama' mu?” Sagawa' in sambung hi Īsa, “Bang niyu aku di' kaingatan tantu di' niyu isab kaingatan in Ama' ku, sabab bang niyu kaingatan bang hisiyu aku, tantu kaingatan niyu da isab bang hisiyu in Ama' ku.”",
        20: "Na, in manga yan kiyabichara hi Īsa ha sa'bu siya nanghihindu' didtu ha halaman sin Bāy sin Tuhan, masuuk ha bilik kiyabutangan sin paghuhulugan sarakka. Wayruun tau makasaggaw kaniya sabab wala' pa naabut in waktu kiyaganta' sin Tuhan pagsaggaw kaniya.",
        21: "Manjari biyalikan na isab hi Īsa in bichara niya ha manga tau. Laung niya, “In aku ini sūng na mag'īg dayn dī. Minsan biya' diin in paglawag niyu kāku', di' niyu aku kabaakan. Sampay sadja kamu mapatay di' kamu mapuas dayn ha dusa hangkan di' kamu makaurul pa kadtuan ku.”",
        22: "Na, nag'asubu-iyasubuhi na in manga nakura' Yahudi, laung nila, “Unu baha' in hātihan sin bichara niya di' kitaniyu makaurul pa kadtuan niya? Maray' siya magpatay sin baran niya!”",
        23: "In sambung hi Īsa kanila, “In manga kamu yan tau dī ha dunya. Ampa in aku ini dayn ha surga'. In katān pikilan niyu yan pikilan sin tau dunya, sagawa' in aku bukun biya' sin pikilan niyu.",
        24: "Hangkan biyaytaan ta kamu sin di' kamu mapuas dayn ha dusa niyu sampay sadja kamu mapatay. Bang kamu di' magkahagad sin bayta' ku kaniyu ha pasal sin baran ku, bang hisiyu aku na, biya' na sin agi ku kaniyu sampay sadja kamu mapatay, di' da mapuas in dusa niyu.”",
        25: "Laung nila kan Īsa, “Mayta', hisiyu ba kaw tuud yan?” Laung hi Īsa, “Bakas ta na kamu biyaytaan dayn sin tagna' bang hisiyu aku.",
        26: "Mataud pa in hibichara ku pasal sin manga hinang iban addat niyu amu in mapatut ku butangan hukuman sabab amuna in kabayaan sin nagdaak kāku' mari. Lāgi' in katān bayta' niya bunnal. Amura in biyayta' ku ha manga tau dī ha dunya in diyungug ku dayn kaniya.”",
        27: "Na, wala' kiyahātihan sin manga tau in piyagbichara hi Īsa pasal sin Tuhan, Ama' niya.",
        28: "Hangkan laung hi Īsa kanila, “Bang maabut na in waktu in aku amu in Anak Mānusiya', hikalansang niyu na pa usuk pagpatayan ampa in usuk yan patindugun, na duun niyu na kaingatan bang hisiyu aku. Lāgi' kaingatan niyu da isab sin wala' aku nagbaya'-baya' naghinang unu-unu sin baran-baran ku sadja, sagawa' amura in hindu' ku ha manga tau in daakan kāku' sin Ama' ku.",
        29: "Taptap aku tiyatabang iban biyabawgbugan sin nagdaak kāku' mari pa dunya. Wala' niya aku piyasāran, sabab in hīhinang ku sadja amuna in unu-unu na makasulut kaniya.”",
        30: 'Na, mataud in manga tau nakarungug sin pamung hi Īsa nagparachaya na kaniya.',
        31: "Manjari namung hi Īsa ha manga Yahudi amu in nagparachaya kaniya, laung niya, “Bang niyu kahagarun tuud in hindu' ku kaniyu, in kamu yan mattan tuud mulid ku.",
        32: "Makaingat na kamu sin kasabunnalan tuud dayn ha Tuhan. In yan amu in makalimaya kaniyu dayn ha namamanyaga' kaniyu.”",
        33: "In sambung sin manga Yahudi, “In kami ini panubu' hi Ibrahim. Wala' kami nabanyaga' dayn sin tagna'. Mayta' kaw imiyan malimaya kami dayn ha namamanyaga' kāmu'?”",
        34: "In sambung hi Īsa kanila, “Baytaan ta kamu sin kasabunnalan. Hisiyu-siyu in mabaya' sadja huminang sin makarusa, in siya yan mahinang banyaga' sin baya' niya huminang sin makarusa.",
        35: "Biya' na sin kiyaingatan niyu, in banyaga' bukun lahasiya' sin tagbanyaga' kaniya. Hangkan ku'nu-ku'nu waktu mabutas sila. Sagawa' in anak iban sin ama' di' mabugtu' in pagtalianak nila.",
        36: "Hangkan bang kamu puasun sin amu in Anak Tuhan, na tantu malimaya kamu dayn ha namamanyaga' kaniyu.",
        37: "Kaingatan ku in kamu manga panubu' hi Ibrahim. Sagawa' mabaya' kamu mamunu' kāku' sabab di' niyu matayma' in kasabunnalan sin hindu' ku.",
        38: "In biyayta' ku kaniyu amu in manga kīta' ku didtu ha hulaan sin Ama' ku, sagawa' in kamu, in hīhinang niyu in bayta' kaniyu sin ama' niyu.”",
        39: "In sambung nila kan Īsa, “Hi Ibrahim in ītung namu' ama'.” Sagawa' laung hi Īsa kanila, “Bang kamu bunnal tuud panubu' hi Ibrahim, na subay niyu hinangun in biya' da isab sin nahinang hi Ibrahim.",
        40: "Sagawa' dugaing siya dayn kaniyu. In kamu kabayaan niyu aku patayun sawkat ta na kamu biyaytaan sin kasabunnalan diyungug ku dayn ha Tuhan. Na, in hi Ibrahim wala' tuud nakahinang sin biya' ha yan!",
        41: "In hinang niyu yan biya' da tuud isab sin hinang sin ama' niyu.” “Uy,” laung nila kan Īsa, “in Tuhan amura in hambuuk-buuk tuud Ama' sin manga kami bangsa Yahudi. Iban in kami mattan tuud manga anak niya.”",
        42: "Laung hi Īsa kanila, “Na, bang bunnal in Tuhan Ama' niyu tuud, na lumasa kamu kāku', sabab in aku dayn ha Tuhan, hangkan yari aku dī kaniyu bihaun. Bukun aku miyari dayn ha baya' sadja sin baran ku, sagawa' kiyawakilan aku sin Tuhan mari.",
        43: "Hangkan na kamu di' makahāti sin hindu' ku sabab marugal tuud kamu ha hindu' ku.",
        44: "In Iblis amu in ama' niyu, hangkan amu in kabayaan niya in iyaagad niyu. In siya yan asal mamumunu' dayn sin tagna'. Di' siya mabaya' sin kasabunnalan, sabab wayruun unu-unu kasabunnalan guwa' dayn kaniya. In hinang niya magputing sadja, miyamagad na ha addat niya putingan. Asal siya putingan dayn sin tagna' iban siya na in puunan sin katān puting.",
        45: "Ampa in aku kasabunnalan in katān bayta' ku kaniyu, hangkan di' kamu magkahagad kāku'.",
        46: "Hisiyu dī kaniyu in makaiyan in aku taga dusa? Na pagga kamu di' makaiyan sin in aku taga dusa, na mayta' kamu di' magkahagad sin in bayta' ku kaniyu kasabunnalan?",
        47: "Bang in tau bunnal suku' sin Tuhan, tantu magkahagad siya sin hindu' dayn ha Tuhan. Sagawa' in kamu bukun suku' sin Tuhan, hangkan di' kamu magkahagad sin hindu' dayn kaniya.”",
        48: "Laung sin manga nakura' Yahudi kan Īsa, “Bukun ka bunnal in agi namu' in ikaw tau Samariya bukun tuud Yahudi, iban in ikaw siyasaytan?”",
        49: "In sambung hi Īsa, “Bukun aku siyasaytan, sabab liyalaggu' ku in Ama' ku. Sagawa' in kamu biyababa' niyu aku.",
        50: "Wala' aku naglawag kalagguan pa baran ku. Sagawa' awn da manglaggu' kāku'. Siya in manghukum ha manga tau.",
        51: "Baytaan ta kamu sin kasabunnalan. Hisiyu-siyu in magkahagad sin hindu' ku, di' tuud siya mapatay kasaumulan.”",
        52: "Na, laung sin manga nakura' kan Īsa, “Bihaun kaingatan namu' na tuud sin in ikaw siyasaytan! In kaapu'-apuan namu' hi Ibrahim iban sin manga kanabihan yadtu miyatay na. Sagawa' laung mu hisiyu-siyu in magkahagad sin hindu' mu di' mapatay kasaumulan.",
        53: "Mayta', ha pikil mu labi kaw makawasa dayn ha nanubu' kāmu' hi Ibrahim amu in miyatay na? Iban minsan in manga kanabihan miyatay da isab. Mayta' pangannal mu hisiyu kaw?”",
        54: "In sambung hi Īsa, laung niya, “Bang sawpama in aku maglawag sadja kalagguan pa baran ku, in kalagguan yan way da pūs niya. Sagawa' in manglaggu' kāku', in Ama' ku, amu in piyag'iyan niyu Tuhan niyu.",
        55: "Sagawa' di' niyu kaingatan tuud in Tuhan. Ampa in aku kaingatan ku tuud siya. Bang aku sawpama imiyan di' ku kaingatan in Tuhan, na putingan da isab aku biya' kaniyu. Sagawa' kaingatan ku tuud in Tuhan iban iyaagad ku in katān daakan niya.",
        56: "In hi Ibrahim amu in nanubu' kaniyu kiyūgan tuud pag'ingat niya sin dumatung da in waktu kakitaan niya aku mari pa dunya. Na, pagkita' niya sin pagkari ku kiyūgan tuud siya.”",
        57: "Laung nila kan Īsa, “Biya' diin in kakita' kaymu hi Ibrahim, sin minsan in umul mu wala' pa miyabut kay'man?”",
        58: "“Baytaan ta kamu sin kasabunnalan,” laung hi Īsa, “Ha wala' pa naawn hi Ibrahim, in aku asal awn na.”",
        59: "Pag'ubus hi Īsa nagbichara, kimawa' batu in manga tau hipanilu' kaniya, sagawa' timapuk hi Īsa. Pag'ubus ampa siya gimuwa' dayn ha halaman sin Bāy sin Tuhan.",
    },
    9: {
        1: "Manjari ha sa'bu hi Īsa nagpapanaw, kīta' niya in hambuuk usug buta kariasali.",
        2: "Sakali pagkita' sin manga mulid hi Īsa ha tau buta, iyasubu nila hi Īsa, laung nila, “Tuwan, unu in sabab hangkan in tau yan piyag'anak asal buta? Sabab ka sin dusa niya atawa dusa sin manga maas niya?”",
        3: "In sambung hi Īsa, laung niya, “Nabuta siya bukun pasal sin dusa niya atawa dusa sin maas niya, sagawa' in sabab hangkan in siya yan buta ha supaya mapanyata' duun kaniya in kawasa sin Tuhan (bang siya karihilan na pangita').",
        4: "Bābā kitaniyu buhi' pa, subay natu' hinangun in daakan sin Tuhan, amu in nagdaak kāku' mari. Bang maabut na in waktu natu' matay, di' na kitaniyu makahinang.",
        5: "Ha salugay ku dī ha dunya, aku in ilaw amu in dumihil kasawahan pa pikilan sin mānusiya' katān.”",
        6: "Pag'ubus hi Īsa namichara, limura' siya pa lupa' ampa niya liyamugay in lura' iban lupa' hīnang pisak. Pag'ubus ampa niya piyahid pa mata sin tau buta.",
        7: "Ampa niya īyan in tau buta, laung niya, “Kadtu kaw pama'mus pa tubig Siluwam.” (In hāti sin Siluwam Pagparāhan.) Na, miyadtu na in tau buta nama'mus. Pagbalik niya mawn makakita' na siya.",
        8: "Sakali pagkita' kaniya sin manga pangdaig bāy niya iban sin manga tau nakakita' kaniya magpangayu' sarakka, laung nila, “Bukun ka in tau ini amu in naglilingkud magpangayu' sarakka?”",
        9: "Laung sin kaibanan, “Siya na sa yan.” Sagawa' laung isab sin kaibanan, “Bukun sān, sa' hangka-dagbus sadja sila.” Simambung in tau buta, laung niya, “Aku na sa ini in tau bakas buta.”",
        10: "Na, iyasubu siya sin manga tau, laung nila, “Mayta' kaw makakita' na bihaun?”",
        11: "In sambung niya, laung niya, “In tau amu in pagngānan Īsa in nagpauli' sin mata ku. Hīnang niya pisak in lupa' ampa niya piyahid pa mata ku. Pag'ubus ampa niya aku piyakadtu mama'mus pa tubig Siluwam. Na, miyadtu na aku nama'mus. Na, pag'ubus ku nama'mus makakita' na aku.”",
        12: "Imasubu in manga tau, laung nila, “Hariin na siya?” In sambung niya, “Inday, di' ku kaingatan.”",
        13: 'Manjari diyā sin manga tau madtu pa manga Parisi in tau bakas buta.',
        14: "In adlaw hīnang hi Īsa pisak in lupa' kimugdan adlaw Sabtu', amu in adlaw paghali-hali iban pagpudji pa Tuhan.",
        15: "Na, iyasubu na isab sin manga Parisi in tau bakas buta bang mayta' siya makakita' na. Laung niya kanila, “Biyutangan niya pisak in mata ku. Sakali nakakita' na aku pag'ubus ku piya'musan.”",
        16: "Laung sin kaibanan Parisi, “In tau yan bukun diyaak sin Tuhan, sabab wala' niya iyagad in sara' pasal sin adlaw paghali-hali iban pagpudji pa Tuhan.” Sagawa' laung isab sin kaibanan, “Bang in tau yan baldusa biya' diin in kahinang niya sin hinang mu'jijat biya' ha yan?” Na, nabahagi' nagduwa in pikilan sin manga tau pasal hi Īsa.",
        17: "Hangkan iyasubu na isab nagbalik sin manga Parisi in tau bakas buta. Laung nila, “In agi mu in tau yadtu amu in nagpauli' kaymu. Na, bang ha pikilan mu hisiyu in tau yadtu?” “Hambuuk siya nabi,” in sambung sin tau bakas buta.",
        18: "Na, in manga nakura' Yahudi di' makakahagad sin in tau yaun bakas buta, hāti nakakita' na. Hangkan piyakawa' nila in ina'-ama' niya ampa nila iyasubu.",
        19: "Laung nila ha ina'-ama' sin tau bakas buta, “Anak niyu ka in tau ini amu in piyag'iyan asal buta dayn ha kapag'anak kaniya? Na, mayta' siya makakita' na bihaun?”",
        20: "In sambung sin ina'-ama' niya, “Huun, in siya yan anak namu'. Asal siya buta dayn ha kapag'anak kaniya.",
        21: "Sagawa' di' namu' kaingatan bang mayta' siya makakita' na bihaun iban di' namu' da isab kaingatan bang hisiyu in nakarihil pangita' kaniya. Asubuha niyu na in baran niya. Maingat na sa siya yan mamayta' sabab maumul na siya!”",
        22: "Hangkan namung biya' hādtu in ina'-ama' niya sabab miyuga' sila ha manga nakura' Yahudi. Miyuga' sila sabab kiyapag'isunan sin manga nakura' sin hisiyu-siyu in imiyan sin hi Īsa amuna in Almasi, na di' na siya palamurun ha lawm langgal nila.",
        23: "Hangkan laung sin ina'-ama' niya ha manga nakura', “Asubuha niyu na in baran niya sabab maumul na da siya!”",
        24: "Na, piyatawag nagbalik sin manga nakura' in tau bakas buta ampa nila īyan, laung nila, “Sapa kaw pa Tuhan sin kasabunnalan in bayta' mu! Kaingatan namu' sin in tau nagpauli' kaymu hambuuk baldusa.”",
        25: "In sambung sin tau bakas buta, “Di' ku kaingatan bang siya baldusa iban bukun. Amura in kaingatan ku bakas aku buta, sagawa' bihaun makakita' na aku.”",
        26: "Imasubu na isab in manga nakura', laung nila, “Unu in hīnang niya kaymu? Iyunu niya in mata mu hangkan kaw makakita' na bihaun?”",
        27: "“Bakas ta na kamu biyaytaan,” laung sin tau bakas buta, “sagawa' di' niyu da dungugun in bichara ku. Iban mayta' namān kamu mabaya' humāti magbalik? Maray' isab mabaya' kamu magguru kan Īsa.”",
        28: "Sakali piyamūngmūngan siya sin manga nakura', amu agi kaniya, “Ikaw sa yan in mulid sin tau yan, ampa in kami ini mulid hi Musa.",
        29: "Kaingatan namu' in Tuhan bakas nagparman kan Musa. Ampa in tau yan di' namu' minsan kaingatan bang dayn diin siya!”",
        30: "Na, laung sin tau bakas buta, “Ay kaw naa, makainu-inu kamu yan! In tau yan amu in nakapauli' sin mata ku, hāti di' niyu kaingatan bang dayn diin siya!",
        31: "Asal natu' kaingatan sin in tau baldusa di' dungugun sin Tuhan in unu-unu pangayuun niya. Ampa in tau nagmamabuga' iban miyamagad sin kabayaan sin Tuhan, dungugun sin Tuhan in unu-unu pangayuun niya.",
        32: "Dayn sin tagna' kapaawn sin dunya ini, wayruun pa tau in nakarihil pangita' ha tau buta kariasali.",
        33: "Na, bang in tau yan bukun diyaak sin Tuhan, tantu di' siya makahinang unu-unu biya' ha yan.”",
        34: "Na, diyugalan in manga nakura' ha tau bakas buta. Laung nila kaniya, “Mayta', hisiyu kaw in manghindu' kāmu' biya' ha yan? In ikaw yan dayn ha kapag'anak kaymu asal kaw baldusa na. Hāti manghindu' kaw kāmu'?” Na, saruun-duun diyūy sin manga nakura' in tau bakas buta pa guwa' sin langgal.",
        35: "Sakali pagdungug hi Īsa sin diyūy sin manga nakura' in tau bakas buta, magtūy niya liyawag in tau bakas buta. Kiyabaakan niya mayan, iyasubu niya, laung niya, “Magparachaya ka kaw ha Anak Mānusiya'?”",
        36: 'In sambung sin tau bakas buta, laung niya, “Tuwan, baytai aku bang hisiyu siya, ha supaya aku makapagparachaya kaniya!”',
        37: "Laung hi Īsa kaniya, “Bakas mu na siya kīta' iban siya na in diyarā mu nagbichara bihaun.”",
        38: "Laung sin tau bakas buta, “Panghu' ku, magparachaya na aku kaymu.” Sarta' simujud na siya ha alupan hi Īsa.",
        39: "Laung hi Īsa, “In pagkari ku pa dunya amu in makapanyata' sin mattan kahālan sin manga mānusiya'. In manga tau amu in biya' sapantun buta sabab di' nila kaingatan in kasabunnalan pasal Tuhan, karihilan na pangita', sagawa' in manga tau amu in pangannal nila kaingatan nila in kasabunnalan pasal Tuhan, na mabiya' na sila sapantun buta di' makakita'.”",
        40: "Sagawa' laung sin kaibanan Parisi amu in duun nakarungug sin bichara niya, “Biya' kaw nagpaandig sin in kami ini buta. Na, makakita' sa kami ini.”",
        41: "In sambung hi Īsa kanila, “Bang kamu mattan tuud buta, hāti niya wayruun tuud panghāti niyu sin kasabunnalan, na di' kamu maitung nakarusa. Sagawa' pagga kamu imiyan sin makakita' kamu, hāti niya kiyaiingatan niyu in kasabunnalan, na in kamu yan tantu nakarusa, sabab di' kamu magkahagad sin kasabunnalan.”",
    },
    10: {
        1: "“Bunnal in bichara ku ini kaniyu,” laung hi Īsa, “bang in tau di' sumūd dayn ha lawang pa lawm sin lugal pagbubutangan ha manga bili-bili, sagawa' dumāg siya ha labayan dugaing, na in tau yan sugarul iban manglalangpas.",
        2: "Sagawa' bang in tau sumūd dayn ha lawang, in siya yan amu in mag'iipat ha manga bili-bili.",
        3: "Ukaban siya sin tau tunggu' lawang. Kakilāhan sin manga bili-bili in tingug niya. Tawagun niya in manga bili-bili suku' niya, ngānan dayn ha hambuuk pa hambuuk ampa niya dāhun gumuwa' in manga bili-bili.",
        4: "Duun mayan ha guwa' in katān bili-bili niya, muna siya dayn kanila, ampa in manga bili-bili murul kaniya, karna' kakilāhan sin manga bili-bili in tingug niya.",
        5: "Di' in manga bili-bili magad ha tau dugaing. Gām mayan maguy sila bang awn tau dugaing dumā kanila, sabab di' nila kakilāhan in tingug niya.”",
        6: "Amu yan in isturi diyalil hi Īsa, sagawa' wala' kiyahātihan sin manga tau in maana niya.",
        7: "Hangkan namichara na isab nagbalik hi Īsa ha supaya kahātihan sin manga tau in isturi diyalil niya. Laung niya, “Baytaan ta kamu sin kasabunnalan. In aku amuna in biya' ibārat lawang sūran iban guwaan sin manga bili-bili.",
        8: "Hisiyu-siyu in manga miyuna mari dayn kāku', in sila yan biya' ibārat sugarul iban manglalangpas. Sagawa' in manga tau suku' ku wala' nag'asip sin hindu' nila.",
        9: "Aku in biya' ibārat lawang. Hisiyu-siyu in sumūd labay dayn kāku' malappas siya. Luhaya na siya, lāgi' makabaak na siya sin hikarayaw kaniya.",
        10: "In tau sugarul wayruun dugaing maksud niya dayn sin manakaw, māmunu' iban magpakangī' unu-unu na. Sagawa' in aku, in maksud ku miyari, ha supaya dumihil ha manga mānusiya' sin kabuhi' tantu, amu in ballabi-labihan in kasannyangan.",
        11: "“Aku in biya' ibārat mag'iipat bili-bili. Īipat ku tuud marayaw in manga suku' ku, amu in biya' sapantun manga bili-bili. Hililla' ku in dugu' nyawa ku ha pasalan sin manga tau suku' ku.",
        12: "Sagawa' in tau, amu in giyadjihan sadja magjaga ha manga bili-bili, di' da magparuli tuud ha manga bili-bili, sabab bukun da siya in mag'iipat iban tagdapu sin manga bili-bili. Bang siya makakita' iru' talun harap mawn pa manga bili-bili, magtūy siya maguy. Hibīn niya in manga bili-bili. Na, in manga bili-bili sakmitun, iban masilahag na, apasun sin iru' talun.",
        13: 'Hangkan maguy in tau giyadjihan sabab in siya giyadjihan sadja magjaga ha manga bili-bili, iban wayruun lasa niya ha manga bili-bili.',
        14: "“Aku ini in biya' ibārat mag'iipat ha manga bili-bili iban marayaw tuud in pag'ipat ku kanila. Mag'īngati tuud kami marayaw iban sin Ama' ku. Damikkiyan, in aku iban sin manga bili-bili ku mag'īngati tuud isab marayaw. Iban in aku ini lilla' matay pasalan sin manga bili-bili ku.",
        15: "“Aku ini in biya' ibārat mag'iipat ha manga bili-bili iban marayaw tuud in pag'ipat ku kanila. Mag'īngati tuud kami marayaw iban sin Ama' ku. Damikkiyan, in aku iban sin manga bili-bili ku mag'īngati tuud isab marayaw. Iban in aku ini lilla' matay pasalan sin manga bili-bili ku.",
        16: "Awn pa isab manga bili-bili ku dugaing. Suku' ku da isab sila, sagawa' in sila dayn ha baanan dugaing. Subay ku da isab sila dāhun. Kahagarun nila in hindu' ku. Mahambuuk na sila iban sin manga katān suku' ku iban aku hambuuk-buuk in mag'ipat kanila.",
        17: "“Kalasahan tuud aku sin Ama' ku sabab hililla' ku in dugu'-nyawa ku ha supaya maagad in maksud niya mapatay aku iban mabuhi' aku magbīng.",
        18: "Wayruun tau minsan hisiyu in tagakawasa mamatay kāku', sabab aku in makapagbaya' bang aku mapatay atawa di'. Dayn ha kabayaan ku hililla' in dugu'-nyawa ku. Awn kawasa ku mugtu' sin napas ku, iban awn da isab kawasa ku mamuhi' magbalik ha baran ku. Amu yan in daakan hipahinang kāku' sin Ama' ku.”",
        19: "Na, pagdungug sin manga nakura' Yahudi sin pamung hi Īsa, nabahagi' na isab nagbalik in pikilan nila pasal hi Īsa.",
        20: "Laung sin kamatauran kanila, “Siyasaytan in tau yan! Kiyakangug siya! Mayta' kamu dumungug kaniya?”",
        21: "Sagawa' laung isab sin kaibanan, “Bang in tau yan siyasaytan di' makabichara biya' ha yan, iban in tau siyasaytan di' makapauli' ha tau buta!”",
        22: "Na, manjari naabut na in waktu pagjamu ha Awrusalam amu in pagngānan Pagsuchi sin Bāy sin Tuhan. Nakasa'bu ha timpu mahaggut.",
        23: 'Sakali duun hi Īsa nagpapanaw ha balkun sin Bāy sin Tuhan, amu in pagngānan Balkun hi Sultan Sulayman.',
        24: "Manjari, piyaglibutan hi Īsa sin manga nakura' Yahudi. Laung nila kan Īsa, “Maunu pa in lugay namu' tumagad ampa mu kami baytaan bang hisiyu kaw tuud? Baytai na kami bihaun sin tuman bang ikaw na tuud in Almasi.”",
        25: "In sambung hi Īsa kanila, “Bakas ta na kamu biyaytaan, sa' di' da kamu magkahagad kāku'. Kīta' niyu na sin in manga hinang nahinang ku dayn ha kawasa sin Tuhan. Na, in yan amuna in magpakita' kaniyu bang hisiyu tuud aku.",
        26: "Sagawa' di' da kamu magkahagad kāku', sabab in kamu yan bukun suku' ku.",
        27: "In manga tau suku' ku, amu in ibārat bili-bili īipat ku, magkahagad sin hindu' ku. Kaingatan ku sila iban magad sila kāku'.",
        28: "Dihilan ku sila kabuhi' salama-lama ha lawm ukum-milik sin Tuhan. Di' sila mabutas dayn ha Tuhan kasaumulan. Wayruun makasakmit kanila dayn ha lawm ukuman ku.",
        29: "Sabab in sila kiyasuku' kāku' sin Tuhan Ama' ku. Ampa in Ama' ku makawasa dayn ha katān. Wayruun makasakmit kanila dayn ha lawm ukuman niya.",
        30: "In aku iban sin Ama' ku nahahambuuk.”",
        31: "Na, pagdungug sin manga nakura' sin pamung hi Īsa, miyūt na isab sila batu nagbalik hipanilu' kan Īsa.",
        32: "Laung hi Īsa kanila, “Mataud hinang marayaw in kīta' niyu nahinang ku. In manga yan daakan sin Tuhan piyahinang kāku'. Na, unu dayn ha manga nahinang ku yan in kiyarugalan niyu, hangkan niyu aku batuhun?”",
        33: "In sambung nila kan Īsa, “Bukun kami mamatu kaymu sabab sin unu-unu na nahinang mu marayaw, sagawa' hangkan namu' kaw batuhun, sabab namung kaw pangkal pa Tuhan! In ikaw yan mānusiya' da, hāti imiyan kaw, ikaw in Tuhan!”",
        34: "In sambung hi Īsa kanila, “Kiyasulat ha lawm Kitab niyu in pamung sin Tuhan ha manga mānusiya', amu agi, ‘In kamu yan manga Tuhan!’",
        35: "Na, kiyaiingatan natu' sin di' kapindahan kasaumulan in unu-unu kiyasulat ha lawm Kitab. Na, in manga tau yadtu, amu in kiyapanaugan sin Parman, manga tuhan in pagtawag sin Tuhan kanila.",
        36: "Na, in hāti niya minsan in aku, matūp da isab tawagun Anak sin Tuhan, sabab in aku kiyandī iban kiyawakilan sin Tuhan, Ama' ku, mari pa dunya. Na, pagga biya' ha yan, mayta' kamu imiyan sin in aku namung pangkal pa Tuhan, sawkat na aku imiyan Anak aku sin Tuhan?",
        37: "Bang sawpama in hinang ku ini di' magkugdan iban sin hinang sin Tuhan, Ama' ku, na, ayaw kamu magparachaya kāku'.",
        38: "Sagawa' bang magkugdan in hinang namu', minsan kamu di' na magparachaya sin bichara ku, bang mayan magparachaya kamu ha manga nahinang ku, ha supaya mattan kaingatan niyu na tuud sin in aku iban sin Tuhan, Ama' ku, nahahambuuk tuud.”",
        39: "Sakali ambaya' nila na isab saggawun hi Īsa pasal sin pamung niya, sagawa' nakapaklus hi Īsa dayn kanila.",
        40: "Manjari, miyadtu hi Īsa nagbalik pa hansipak sin Suba' Jurdan, amu in bakas piyagliguan hi Yahiya ha manga tau. Duun siya himanti'.",
        41: "Mataud tau in miyawn kaniya. Laung sin manga tau, “In hi Yahiya wala' nakahinang sin manga mu'jijat, sagawa' in katān bichara niya pasal hi Īsa bunnal.”",
        42: 'Na, mataud tau duun in nagparachaya kan Īsa.',
    },
    11: {
        1: "Manjari awn hambuuk tau nāsakit, in ngān niya hi Lasarus. Duun siya naghuhula' ha dāira Bitani, amu in piyaghuhulaan da isab sin duwa taymanghud niya babai, hi Mariyam kay Marta.",
        2: "In hi Mariyam ini amuna in babai imasag lana mahamut pa siki hi Panghu' Īsa ampa niya tiyarapuhan sin buhuk niya. Na, pagga nāsakit hi Lasarus,",
        3: "nagparā lapal in duwa magtaymanghud babai madtu kan Īsa, amu agi, “Panghu', in bagay mu amu in kalasahan mu nāsakit.”",
        4: "Na, pag'ingat hi Īsa sin paraak kaniya, laung niya, “Bukun nāsakit hi Lasarus ha supaya siya mapatay, sagawa' ha supaya matanyag in kusug sin kawasa sin Tuhan, iban amu isab yan in makarihil kabantugan ha amu in Anak Tuhan.”",
        5: 'Malasa hi Īsa ha tū magtaymanghud, hi Marta, hi Mariyam iban hi Lasarus.',
        6: "Sagawa' pag'ingat niya sin nāsakit hi Lasarus, wala' siya magtūy miyadtu. Timagad pa siya duwa adlaw duun ha kiyaruruunan niya.",
        7: 'Sakali nakalabay mayan in duwa adlaw, laung hi Īsa ha manga mulid niya, “Madtu kitaniyu magbalik pa Yahudiya.”',
        8: "Laung sin manga mulid niya kaniya, “Tuwan Guru, sin ka'nu-ka'nu yaun ambaya' kaw patayun tiluun sin batu kaagi sin manga nakura' Yahudi. Na, hāti, mabaya' pa kaw magbalik madtu?”",
        9: "In sambung hi Īsa, laung niya, “Ayaw kamu mabuga'. Ha lawm sin hangka-adlaw, hangpu' tagduwa kajām masawa in hula'. Bang kitaniyu manaw ha waktu masawa pa in hula', di' kitaniyu makarugtul pa unu-unu kamulahan, sabab kīkita' taniyu in panawan taniyu.",
        10: "Sagawa' bang kitaniyu manaw ha waktu tigidlum na in hula', makarugtul sadja kitaniyu pa kamulahan, sabab di' taniyu kakitaan in panawan taniyu.”",
        11: "Pag'ubus hi Īsa namichara biya' hādtu, giyanapan niya pa in bichara niya, laung niya, “In bagay natu' hi Lasarus nakatūg na, sagawa' madtu aku batiun ku siya.”",
        12: "Laung sin manga mulid niya, “Panghu', bang siya nakatūg, in hāti niya dumayaw na siya.”",
        13: "In hātihan sin bichara hi Īsa, in hi Lasarus miyatay na, sagawa' in panghāti sin manga mulid niya, in hi Lasarus nakatūg na.",
        14: 'Hangkan biyuntulan na sila hi Īsa, laung niya, “In hi Lasarus miyatay na.',
        15: "Sagawa' ha sabab niyu, makuyag aku sin wala' aku didtu ha sa'bu niya nāsakit. Karna' dayn ha pasal sin hinangun ku ini, in kamu magparachaya na tuud kāku'. Sūng na, madtu na kitaniyu kan Lasarus.”",
        16: "Sakali namichara hi Tumas, amu in diyanglayan Kambal. Laung niya ha manga pagkahi niya mulid hi Īsa, “Sūng na kitaniyu magad ha Panghu', ha supaya kitaniyu makaunung matay kaniya!”",
        17: 'Na, pagdatung hinda Īsa pa Bitani, kiyabaytaan siya sin awn na upat adlaw limabay in kapagkubul kan Lasarus.',
        18: "Pagga in Bitani masuuk da pa Awrusalam, awn da manga tū batu in layu',",
        19: 'mataud manga Yahudi in limuruk mawn kan Marta iban hi Mariyam, magparayaw sin atay nila pasal sin kamatay sin taymanghud nila hi Lasarus.',
        20: "Pagdungug hi Marta sin magdaratung na hi Īsa mawn, magtūy siya miyadtu miyāk kan Īsa, sagawa' hi Mariyam wala' minīg dayn ha lawm bāy.",
        21: "Na, nagbāk mān hi Marta kay Īsa, laung hi Marta kan Īsa, “Panghu', bang kaw bakas dī, in taymanghud natu' di' matay!",
        22: "Sagawa' kaingatan ku minsan bihaun hirūl sin Tuhan kaymu in unu-unu pangayuun mu kaniya.”",
        23: "Laung hi Īsa kaniya, “In taymanghud mu mabuhi' da magbalik.”",
        24: "In sambung hi Marta kan Īsa, “Kaingatan ku sin mabuhi' da siya magbalik ha adlaw mahuli.”",
        25: "Laung hi Īsa kaniya, “Aku in makabuhi' magbalik ha manga patay iban aku in puunan sin kabuhi'. Hisiyu-siyu in magparachaya kāku' mabuhi' siya, minsan siya miyamatay na.",
        26: "Iban hisiyu-siyu in buhi' ampa magparachaya kāku', di' tuud siya mapatay. Magparachaya ka kaw sin bichara ku yan?”",
        27: "In sambung hi Marta, “Huun, Panghu', magparachaya tuud aku sin ikaw na in Almasi, amu in Anak Tuhan, iban amu in kiyawakilan sin Tuhan mari pa dunya.”",
        28: "Na, pag'ubus hi Marta namichara, miyadtu siya nagbalik pa bāy ampa niya hiyagas-hagasan hi Mariyam, laung niya, “Yari na in Tuwan Guru. Nangasubu siya bang hawnu kaw.”",
        29: "Pagdungug hi Mariyam, nagtūy siya nag'ūs-'ūs gimuwa' miyāk madtu kan Īsa.",
        30: "Na, in hi Īsa wala' pa nakasampay mawn pa lawm sin kawman. Masi pa siya didtu ha lugal piyagbākan nila kay Marta.",
        31: "Na, in manga luruk Yahudi duun ha bāy, amu in nagpaparayaw sin atay hi Mariyam. Pagkita' nila sin timindug hi Mariyam ampa nag'ūs-'ūs gimuwa' dayn ha bāy, imurul sila, sabab in pangannal nila madtu hi Mariyam pa kubul sin taymanghud niya magtangis.",
        32: "Sagawa' harap hi Mariyam madtu kan Īsa. Na, pagkita' niya na mayan kan Īsa, magtūy siya simujud pa alupan hi Īsa ampa siya namung, laung niya, “Panghu', bang kaw bakas dī, di' matay in taymanghud natu'.”",
        33: "Na, pagkita' hi Īsa kan Mariyam nagtatangis iban sin manga tau luruk timatangis da isab, nabagbag in lawm atay niya, iban landu' siya nasusa.",
        34: "Nangasubu hi Īsa, laung niya, “Hariin niyu siya kiyubul?” Laung nila, “Kari kaw kita', Panghu'!”",
        35: "Timū' in luha' hi Īsa.",
        36: 'Na, laung sin manga tau, “Kitaa niyu ba in lasa niya kan Lasarus.”',
        37: "Sagawa' laung isab sin kaibanan, “Bang siya malasa, mayta' niya wala' piyauli' in sakit hi Lasarus supaya siya di' matay? Pagga in tau dugaing minsan tau buta kiyaulian niya.”",
        38: "Na, nabagbag nagbalik in lawm atay hi Īsa, sarta' miyadtu na siya pa kubul hi Lasarus. In kubul hi Lasarus, biya' lupa sungab batu, tiyatambulan sin batu dakula'.",
        39: "Pagdatung nila pa kubul, laung hi Īsa, “Īgi niyu in batu tambul sin kubul.” Sagawa' laung hi Marta, amu in taymanghud sin miyatay, “Panghu', mabahu' na sān, sabab awn na upat adlaw in lugay niya kiyubul.”",
        40: "Laung hi Īsa kaniya, “Bakas ta na kaw biyaytaan, bang kaw magparachaya, kakitaan mu bang biya' diin in kusug sin kawasa sin Tuhan.”",
        41: "Na, inīgan nila na in batu tambul sin lawang kubul, sarta' himangad hi Īsa ampa siya namichara, laung niya, “Ū, Ama', magsarang-sukul tuud aku kaymu sin diyūl mu kāku' in piyangayu' ku kaymu.",
        42: "Kaingatan ku sin hirūl mu sadja kāku' in unu-unu pangayuun ku kaymu. Sagawa' hiparungug ku ha manga tau ini in bichara ku kaymu ha supaya sila magparachaya sin ikaw tuud in nagdaak kāku' mari.”",
        43: "Pag'ubus ampa siya timawag matanug kan Lasarus. Laung niya, “Lasarus, kari na kaw guwa'!”",
        44: "Sakali gimuwa' na hi Lasarus dayn ha lawm kubul. In baran niya masi pa napuputus sin saput sampay pa siki-lima iban bayhu' niya. Laung hi Īsa, “Īgi niyu na in saput niya bat siya makauwi' na.”",
        45: 'Na, dayn didtu mataud Yahudi amu in nangluruk mawn kan Mariyam in nagparachaya kan Īsa, sabab kiyakitaan nila tuud in nahinang hi Īsa.',
        46: "Sagawa' in kaibanan tau miyadtu pa manga Parisi nagsumbung pasal sin nahinang hi Īsa.",
        47: "Na, hangkan magtūy piyapagtipun sin manga nakura' kaimaman iban sin manga Parisi in manga kunsiyal sin agama Yahudi, amu in magpapanaw sin sara' sin agama Yahudi. Napūn mayan sila, laung nila, “Unuhun natu' na in tau yan, sabab mataud na tuud mu'jijat nahinang niya!",
        48: "Bang natu' siya pasāran maghinang sin hinang niya yan, in tau katān magkahagad na kaniya. Na, dayn ha pasal yan, mulahun sin parinta sin hula' Rūm in Bāy natu' Mahasuchi sampay pa bangsa natu'!”",
        49: "Sakali namichara in hambuuk duun kanila amu in pagngānan Kayapas. Siya in Imam Dakula' sin tahun yadtu. Laung niya, “In kamu yan wayruun tuud pikilan!",
        50: "Wala' niyu ka napikil sin sapādpād magmula in bangsa natu', marayaw pa isab hambuuk sadja tau in mapatay ganti' sin kitaniyu katān.”",
        51: "Na, in pamung hi Kayapas yadtu bukun tuud guwa' dayn ha lawm pikilan niya. Sagawa' pagga siya in Imam Dakula' sin tahun yadtu, biya' siya hambuuk mangingita', namayta' sin in hi Īsa matay ha susūngun sabab-karna' sin bangsa Yahudi.",
        52: "Lāgi' bukun sadja isab ha pasal sin manga bangsa Yahudi, sagawa' ha supaya mahambuuk na hangka-agaran in manga tau amu in nakawkanat ha kahula'-hulaan, bang sila mahinang na manga suku' sin Tuhan.",
        53: "Manjari tagnaan dayn sin adlaw yadtu piyagpikilan na sin manga nakura' Yahudi bang biya' diin in hikapatay nila kan Īsa.",
        54: "Hangkan in hi Īsa di' na magkawn pa katauran tau ha Yahudiya. Gām mayan miyadtu siya iban sin manga mulid niya pa kawman pagngānan Ipraim masuuk pa hula' paslangan mahunit paghulaan. Dimuun siya iban sin manga mulid niya.",
        55: 'Manjari masuuk na in pagjamu sin manga Yahudi amu in pagngānan Haylaya Paglappas dayn ha Kamatay. Na, mataud tau dayn ha kakawm-kawman in timukad madtu pa Awrusalam. Duun mayan sila ha Awrusalam, nagsuchi sila sin baran nila ha supaya sila makalamud maghaylaya.',
        56: "Na, piyaglawag sin manga tau hi Īsa duun ha paghaylayahan. Bang sila matipun na duun ha Bāy sin Tuhan, mag'asubu-iyasubuhi na sila, laung nila, “Ha pikil niyu, mari baha' hi Īsa pa paghaylayahan?”",
        57: "Na, nagdihil daakan in manga nakura' kaimaman iban manga Parisi, sin hisiyu-siyu in makaingat bang haunu hi Īsa subay mamayta' magtūy kanila, ha supaya nila masaggaw hi Īsa.",
    },
    12: {
        1: "Na, awn pa unum adlaw in lugay ampa dumatung in Haylaya Paglappas dayn ha Kamatay, miyadtu hi Īsa pa Bitani, hula' hi Lasarus, amu in tau biyuhi' hi Īsa nagbalik dayn ha kamatay.",
        2: 'Na, duun mayan siya ha Bitani, liyabut siya sin manga tau duun. Duun da isab hi Marta timabang namutang sin pagkaun. In hi Lasarus nagsāw nagkaun kay Īsa iban sin kaibanan tau.',
        3: "Sakali kimawa' hi Mariyam lana mahamut pagngānan narda. In lana mahamut ini maharga' tuud, bukun paltik iban wayruun lamud niya dugaing. Iban in taud niya tunga' kilu. Biyutangan niya lana mahamut in siki hi Īsa ampa niya tiyarapuhan sin buhuk niya. Nagtu'nug ha lawm bāy in hamut sin lana mahamut.",
        4: 'Sakali namichara in hambuuk mulid hi Īsa, hi Judas tau dayn ha Kiriyud, amu in manipu kan Īsa, laung niya,',
        5: '“Gām pa in lana mahamut yan piyagdagang magbīhan timbang gadji sin hambuuk tau ha lawm hangka-tahun. Hāti in bīhan niya hikapagsarakka ha manga miskin.”',
        6: "Hangkan siya namichara biya' hādtu, sabab pangungustaw siya, bukun sabab maluuy siya ha manga miskin. Siya in nagdarā sin pagluluunan sīn nila, iban biyaksa siya magpangawa' dayn ha sīn piyangandul kaniya sin manga pagkahi niya mulid hi Īsa.",
        7: "Sagawa' laung hi Īsa kaniya, “Pasāri na siya. In lana mahamut yan tiyatagama niya bat supaya saddiya na in anggawta'-baran ku bang aku hikubul na ha waktu susūngun.",
        8: "In manga tau miskin matabang niyu ha ku'nu-ku'nu waktu, sagawa' in aku ini di' lumugay dī kaniyu.”",
        9: "Manjari mataud tuud tau nakarungug sin yaun hi Īsa ha Bitani. Hangkan miyadtu sila, bukun sadja isab kumita' kan Īsa, sagawa' mabaya' da isab sila kumita' kan Lasarus, amu in biyuhi' hi Īsa nagbalik dayn ha kamatay.",
        10: "Hangkan nag'isun in manga nakura' kaimaman patayun hi Lasarus hiunung kan Īsa.",
        11: "Sabab dayn ha pasal hi Lasarus mataud manga Yahudi in nagparachaya na kan Īsa, iban wala' na miyagad ha manga kaimaman.",
        12: "Na, pag'adlaw hambuuk in manga tau mataud amu in miyawn pa Awrusalam himadil sin paghinang sin Haylaya Paglappas dayn ha Kamatay, nakarungug sin in hi Īsa magkakawn pa Awrusalam.",
        13: "Hangkan kimawa' sila manga sanga dahunan, ampa sila miyadtu miyāk kan Īsa. Naglami-lami sila nag'ulang, laung nila, “Pudjihun natu' in Tuhan! Bang mayan barakatan in siya amu in kiyawakilan sin Tuhan! Bang mayan barakatan sin Tuhan in magbaya' ha bangsa Israil!”",
        14: "Sakali nakabaak hi Īsa hambuuk kura' amu in piyanguraan niya. Na, naagad tuud in asal kiyasulat ha lawm Kitab, amu agi,",
        15: "“Manga tau ha Awrusalam. Ayaw na kamu mabuga'! Kitaa niyu ba, yan na tudju mawn kaniyu in makapagbaya' kaniyu. Mangura' siya ha kura', amu in anak kura' wala' pa kiyapanguraan.”",
        16: "Ha waktu yadtu wala' kiyahātihan sin manga mulid hi Īsa in pasal sin ini katān. Subay na hi Īsa nakabalik pa surga' iban nagmattan na tuud in kawasa iban kalagguan niya ampa nila kiyatumtuman in kiyabayta' ha lawm Kitab pasal hi Īsa iban kiyatumtuman nila da isab in nahinang nila kaniya.",
        17: "Hangkan mataud tau in miyāk kan Īsa sabab nakarungug sila sin mu'jijat nahinang hi Īsa, amu in pagtāg niya kan Lasarus dayn ha lawm kubul iban biyuhi' nagbalik dayn ha kamatay. In nagsuysuy kanila pasal yan, amu in manga tau bakas duun ha kubul nakakita' ha waktu yadtu sin nahinang hi Īsa.",
        18: "Hangkan mataud tau in miyāk kan Īsa sabab nakarungug sila sin mu'jijat nahinang hi Īsa, amu in pagtāg niya kan Lasarus dayn ha lawm kubul iban biyuhi' nagbalik dayn ha kamatay. In nagsuysuy kanila pasal yan, amu in manga tau bakas duun ha kubul nakakita' ha waktu yadtu sin nahinang hi Īsa.",
        19: "Hangkan, laung sin manga Parisi pa kaibanan Parisi, “Na, kitaa niyu. Napalsu da in palanu natu'. In tau katān magad da kaniya!”",
        20: 'Na, manjari awn isab manga tau bangsa Girik in himadil sin pagpudji ha waktu sin Haylaya ha Awrusalam.',
        21: "Miyadtu sila kan Pilip, hambuuk mulid hi Īsa dayn ha kawman Bitsayda ha hula' Jalil. Laung nila kan Pilip, “Tuwan, mabaya' kami kumita' kan Īsa.”",
        22: "Na, miyadtu hi Pilip namayta' kan Andariyas. Ubus ampa sila karuwa miyadtu namayta' kan Īsa.",
        23: "Laung hi Īsa kanila, “Na, bihaun masuuk na tuud dumatung in waktu kiyaganta' in aku amu in Anak Mānusiya' karihilan na sin kalagguan dakula'.",
        24: "Baytaan ta kamu sin bunnal. In hangsulag binhi' di' tumaud bang di' hitanum pa lupa' biya' sapantun patay hikubul. Sagawa' bang hikatanum na, tumubu' yan iban tumaud in bunga.",
        25: "Na, damikkiyan biya' da isab ha yan in tau. Bang in tau maūg sin kabuhi' niya, iban magpikil sadja sin kabayaan niya mapatay da siya. Sagawa' bang in tau di' maūg sin kabuhi' niya dī ha dunya, taga kabuhi' siya salama-lama.",
        26: "Na, hisiyu-siyu in mabaya' mahinang daraakun ku, subay siya magad kāku' lumabay sin unu-unu haggut-pasu', ha supaya taptap in pag'agad namu'. Iban hisiyu-siyu in maghulas-sangsa' kāku' lagguun siya sin Ama' ku.”",
        27: "Laung pa isab hi Īsa, “Bihaun landu' tuud nasusa in lawm atay ku. Sagawa' minsan biya' ha yan, di' ku pangayuun ha Ama' ku in puasun niya aku dayn ha kabinsanaan kumugdan kāku', sabab hangkan na aku miyari ha supaya lumabay sin kabinsanaan ini.”",
        28: "Ubus ampa namichara hi Īsa pa Tuhan, laung niya, “Ū Ama', dihili kalagguan in ngān mu!” Sakali magtūy awn suwara dayn ha langit, amu agi sin suwara, “Bakas ku na dīhilan kalagguan iban dihilan ku da kalagguan magbalik.”",
        29: "Manjari in manga tau mataud nagtitindug duun nakarungug sin suwara. Laung sin kaibanan, “Uy, nagdawgdug hayn-duun.” Sagawa' laung isab sin kaibanan, “Malāikat sa yadtu in namichara kan Īsa!”",
        30: "Sagawa' laung hi Īsa kanila, “In suwara yadtu piyarungug, bukun ha hikarayaw ku, sagawa' ha hikarayaw niyu.",
        31: "Bihaun naabut na in waktu hirihil in hukuman bang hisiyu tuud in tagakawasa ha manga mānusiya'. Bihaun in Puntukan Saytan amu in nagbabaya' ha manga mānusiya' dī ha dunya, maīg na in kusug sin kawasa niya.",
        32: "Bang aku hikalansang na pa usuk ampa in usuk yan patindugun, na mataud in tau kawaun ku paagarun kāku' dayn ha katilingkal dunya.”",
        33: "Namichara hi Īsa biya' hādtu hipagpahāti ha manga tau bang biya' diin in pagpatay kaniya ha susūngun.",
        34: "Laung sin manga tau mataud, “Kaingatan namu' in bayta' ha lawm Kitab sin in Almasi, mabuhi' salama-lama. Sagawa' in agi mu in tau amu in Anak Mānusiya', subay hikalansang pa usuk ampa in usuk yan patindugun. Na, hisiyu baha' in piyag'iyan mu yan, Anak Mānusiya'?”",
        35: "In sambung hi Īsa kanila, “Bihaun yari pa dī kaniyu in ilaw amu in dumihil kasawahan kaniyu, sagawa' bukun na malugay mīg na in ilaw dayn kaniyu. Hangkan pangandul kamu ha ilaw bābā yari pa dī kaniyu in ilaw, ha supaya kamu di' abutan sin tigidlum. Karna' in tau manaw ha lawm katigidluman di' niya kaingatan in dūngan niya bang harap pakain.",
        36: "Hangkan ha salugay sin ilaw dī kaniyu, pangandul kamu ha ilaw yan, ha supaya kamu mahinang suku' sin ilaw yan.”",
        37: "Pag'ubus hi Īsa nagbichara, minīg siya dayn kanila ampa miyadtu pa di' nila kaingatan. Na, in manga tau masi di' magparachaya kan Īsa minsan da mataud na mu'jijat in kīta' nila nahinang hi Īsa.",
        38: "Na in yan amu in magpakita' sin bunnal tuud in bichara hi Nabi Isayas kiyasulat ha lawm Kitab, amu agi, “Ū Tuhan ku, wayruun magparachaya sin bayta' namu'. In manga tau nakakita' sin kusug sin kawasa mu, hangkatiyu' da in nakahāti.”",
        39: "Lāgi' kiyabayta' da isab hi Isayas bang mayta' in manga tau wala' nagparachaya. Amu agi niya,",
        40: "“Diyūlan sin Tuhan maīg dayn ha mata sin manga tau di' magparachaya in ingat sumilang sin unu-unu kakitaan nila, iban diyūlan sin Tuhan maīg dayn ha pikilan nila in ingat sumilang sin kasabunnalan ha supaya sila di' makahāti. Iban di' magbalik in atay nila kāku',” amu agi sin Tuhan, “bat ku mapuas in manga dusa nila.”",
        41: "In yari kiyasulat hi Isayas sabab kīta' niya in sahaya hi Īsa. Hangkan in piyag'iyan niya yan way dugaing bang bukun hi Īsa.",
        42: "Na, minsan biya' hādtu, mataud manga nakura' Yahudi in nagkahagad kan Īsa, sagawa' wala' sila nagpatampal sabab in kabugaan nila di' na sila palamurun sin manga Parisi ha lawm langgal nila.",
        43: "Lāgi' labi maharga' kanila in masulut nila in kabayaan sin pagkahi nila mānusiya' dayn sin sumulut sin kabayaan sin Tuhan.",
        44: "Manjari namung matanug hi Īsa, laung niya, “Hisiyu-siyu in magparachaya kāku' bukun sadja isab aku in pagparachayahan niya, sagawa' magparachaya da isab siya ha Tuhan amu in nagdaak kāku' mari.",
        45: "Damikkiyan, hisiyu-siyu in nakakita' kāku', sali' niya da tuud kīta' in nagdaak kāku' mari.",
        46: "In aku miyari pa dunya dumihil kasawahan ha manga mānusiya', ha supaya hisiyu-siyu in magparachaya kāku' makaguwa' na siya dayn ha lawm katigidluman.",
        47: "“Na, hisiyu-siyu in makarungug sin bayta' ku ampa siya di' magkahagad, di' ku siya butangan hukuman. Karna' in maksud ku miyari bukun manghukum ha manga mānusiya' sagawa' mamuas kanila dayn ha manga dusa nila.",
        48: "Sagawa' hisiyu-siyu in di' tumayma' kāku' iban di' magparachaya sin bayta' ku, ha adlaw mahuli kugdanan siya sin hukuman. Iban hangkan siya kugdanan sin hukuman sabab wala' niya iyagad in bayta' ku.",
        49: "Sabab in bayta' ku yan bukun guwa' dayn kāku', sagawa' dayn ha Ama' ku. Amura in kiyabichara ku iban kiyahindu' ku kaniyu in daakan kāku' sin Ama' ku amu in nagdaak kāku' mari.",
        50: "Na, kaingatan ku sin in daakan niya makarihil kabuhi' salama-lama. Hangkan unu-unu na in kiyabayta' ku, in yan amuna in daakan kāku' sin Ama' ku.”",
    },
    13: {
        1: "Manjari ha wala' pa timagna' in Haylaya Paglappas dayn ha Kamatay, asal na kiyaingatan hi Īsa sin masuuk na in waktu niya mamutawan dayn ha dunya ini iban magbalik na siya madtu pa Ama' niya. Asal dayn sin tagna' kalasahan tuud hi Īsa in manga tau suku' niya. Hangkan ha waktu ini piyakita' niya tuud in kusug sin lasa niya ha manga tau suku' niya.",
        2: 'Sakali narūm mayan in hi Īsa iban sin manga mulid niya nagsāw nagkaun. In hi Judas, anak hi Simun tau dayn ha Kiriyud asal biyutangan na pamikil manipu kan Īsa kaagi sin Iblis.',
        3: "Asal kiyaiingatan hi Īsa sin in katān kawasa sin Tuhan, Ama' niya, kiyarihil na kaniya. Lāgi' kiyaiingatan niya sin in siya guwa' dayn ha Tuhan iban magbalik da siya pa Tuhan.",
        4: "Sakali timindug hi Īsa dayn ha lamisahan piyagkakaunan nila, ampa niya inīg in hanglapis badju' niya. Ubus ampa siya nanapis sin jimpaw.",
        5: "Pag'ubus, ampa niya biyutangan tubig in pastan, hiyugasan niya na in siki sin manga mulid niya ampa tiyarapuhan niya sin jimpaw piyananapis niya.",
        6: "Na, pagkawn niya mayan humugas sin siki hi Simun Pitrus, di' mabaya' hi Pitrus. Amu agi niya kan Īsa, “Uy, Panghu', ikaw in humugas sin siki ku?”",
        7: "In sambung hi Īsa kaniya, “In hinang ku ini bihaun di' mu kahātihan, sagawa' ha susūngun kahātihan mu da.”",
        8: "Sagawa' laung hi Pitrus, “Tantu di' ta kaw tuud papaghugasun sin siki ku!” In sambung hi Īsa kaniya, “Bang ku di' kahugasan in siki mu, in ikaw di' na maitung mulid ku.”",
        9: "Na, laung hi Simun Pitrus, “Na, pagga biya' ha yan Panghu', bukun sadja siki ku in hugasan mu, sagawa' hugasi sampay pa lima iban ū ku!”",
        10: "Laung hi Īsa, “Bang in tau bakas na namaygu', in baran niya malanu' na. Amu dakuman siki niya in subay hugasan magbalik. In kamu katān suchi in pangatayan, sagawa' awn hambuuk kaniyu in bukun.”",
        11: "Asal kiyaiingatan hi Īsa bang hisiyu in manipu kaniya. Hangkan na siya imiyan, laung niya, “In kamu katān suchi in pangatayan, sagawa' awn hambuuk kaniyu in bukun.”",
        12: "Manjari naubus mayan hi Īsa naghugas sin siki sin manga mulid niya, siyulug niya nagbalik in hanglapis badju' niya ampa siya limingkud nagbalik. Paglingkud niya, iyasubu niya in manga mulid niya, laung niya, “Kiyahātihan niyu da ka in hīnang ku kaniyu hayn-duun?",
        13: "Tuwan iban Panghu' in pagtawag niyu kāku'. Na, nakaamu in pagtawag niyu kāku', sabab aku in guru iban Panghu' niyu.",
        14: "Na, pagga in aku amu in guru iban Panghu' niyu himugas sin siki niyu, na subay niyu singuran in hinang ku. Subay kamu maghugas-hiyugasi sin siki sin kamu hangka-agaran.",
        15: "In hīnang ku yadtu hambuuk suntuan, piyakita' ku kaniyu ha supaya niyu kasinguran.",
        16: "Ini in mattan hibayta' ku kaniyu,” laung hi Īsa. “In tindug bukun makawasa dayn ha nakura'. Damikkiyan, in daraakun bukun makawasa dayn ha nagdaak kaniya.",
        17: "Pagga niyu kahātihan na in hindu' ku yan, na bang niyu yan agarun hinangun awn karayawan niyu!",
        18: "“Malayngkan,” laung hi Īsa, “in bichara ku yan di' kumugdan ha kaniyu katān, sabab asal ku kaingatan bang hisiyu in pinī' ku magad kāku'. Sagawa' maagad tuud in kiyasulat ha lawm Kitab, amu agi, ‘In tau simāw kāku' nagkaun amu in manipu kāku'!’",
        19: "“Biyaytaan ta kamu bihaun sin pasal yan ha wala' pa miyabut, ha supaya bang yan maabut na, magparachaya na kamu bang hisiyu aku.",
        20: "Na, baytaan ta kamu sin mattan. Hisiyu-siyu in tumayma' ha tau diyaak ku, sali' da aku in tiyayma' niya. Damikkiyan, hisiyu-siyu in tumayma' kāku', sali' da isab tiyayma' niya in nagdaak kāku' mari.”",
        21: "Pag'ubus hi Īsa namichara biya' hādtu, landu' tuud siya nasusa. Laung niya ha manga mulid niya, “Baytaan ta kamu sin mattan. Awn hambuuk dī kaniyu in manipu kāku'.”",
        22: "Na, nag'iyaturi in manga mulid niya sarta' nag'inu-inu bang hisiyu in piyag'iyan hi Īsa.",
        23: 'Na, awn hambuuk mulid amu in kalasahan hi Īsa in naglilingkud ha daig niya.',
        24: "In mulid ini sīnyalan hi Simun Pitrus. Laung hi Pitrus, “Asubuha kunu' hi Tuwan bang hisiyu in piyag'iyan niya.”",
        25: "Na, simuuk in mulid ini mawn kan Īsa ampa imiyan, amu agi, “Panghu', hisiyu in tumipu kaymu?”",
        26: "In sambung hi Īsa, “In tau dihilan ku sin tinapay hitublak ku pa lāy pagbabahug-bahugan amuna in tau piyag'iyan ku.” Na, kimā' na hi Īsa tinapay ampa tiyublak pa pagbabahug-bahugan. Ubus ampa niya diyuhal kan Judas, anak hi Simun tau dayn ha Kiriyud.",
        27: "Sakali pagtabuk na mayan hi Judas sin tinapay, nagtūy siya siyūd sin Puntukan Saytan. Laung hi Īsa kaniya, “Ūs-'ūs na kaw bat mu mahinang in hinangun mu!”",
        28: "Sagawa' wala' nakahāti in manga mulid sin bichara hi Īsa kan Judas.",
        29: 'In pangannal sin kaibanan mulid, pagga hi Judas in nagkakaput sin manga sīn nila, na diyaak siya hi Īsa madtu mamī-mī sin pagjamuhan nila atawa dumihil sarakka ha manga miskin.',
        30: "Pagtabuk na mayan hi Judas sin tinapay, magtūy siya gimuwa'. Na, in waktu sin pagguwa' niya yadtu dūm na tuud.",
        31: "Na, nakaīg mayan hi Judas, laung hi Īsa ha manga mulid niya, “Na, bihaun hipakita' na in kalagguan ku, amu in Anak Mānusiya', iban kakitaan da isab in kawasa sin Tuhan dayn ha sabab sin hinang ku.",
        32: "Na, bang ku mapakita' in kawasa sin Tuhan dayn ha hinang ku, na magtūy da isab hipakita' sin Tuhan in kalagguan ku amu in Anak Mānusiya'.",
        33: "“Manga anak mulid ku,” laung hi Īsa, “in aku di' na lumugay dī kaniyu. Bihaun baytaan ta na kamu sin biya' kiyabayta' ku ha manga nakura' Yahudi. Lawagun niyu aku sagawa' di' kamu makaurul kāku' pa kadtuan ku.",
        34: "“Na, bihaun yari awn ba'gu daakan hibīn ku kaniyu. Paglasa-liyasahi kamu biya' sin lasa ku kaniyu.",
        35: 'Bang kamu maglasa-liyasahi na, kaingatan sin manga tau sin in kamu mattan manga mulid ku.”',
        36: "Laung hi Simun Pitrus kaniya, “Mayta' Panghu', pakain kaw?” In sambung hi Īsa, “Bihaun di' kaw makaagad pa kadtuan ku, sagawa' ha susūngun makaurul da kaw kāku'.”",
        37: "Laung hi Pitrus, “Panghu', mayta' aku di' makaagad kaymu? Lilla' aku umunung matay kaymu!”",
        38: "Sagawa' sambung hi Īsa kan Pitrus, “Kabawgbugan mu ka in bichara mu yan sin lilla' kaw umunung matay kāku'? Indani in bichara ku ini. Ha di' pa tumagauk in manuk usug, makatū kaw umiyan, laung mu, di' mu aku kaingatan.”",
    },
    14: {
        1: "Manjari laung hi Īsa ha manga mulid niya, “Ayaw niyu pasusaha in atay niyu. Pangandul sadja kamu pa Tuhan iban pangandul isab kamu kāku'.",
        2: "Ha ukuman sin Tuhan, Ama' ku, mataud in kabutangan. Di' ta kamu baytaan bang yan bukun bunnal. Hangkan madtu aku magbalik pa hulaan ku ha supaya ta kamu katagamahan sin hulaan niyu.",
        3: "Pag'ubus bang ku yan matagama na, magbalik aku mari kumā' kaniyu ampa ta kamu paagarun pa hulaan ku ha supaya in hulaan ku amu isab in hulaan niyu.",
        4: "Na, kaingatan niyu da in dān pa hula' kadtuun ku.”",
        5: "Laung hi Tumas kan Īsa, “Panghu', di' namu' kaingatan in hula' kadtuun mu. Hangkan biya' diin in kaingat namu' sin dān tudju madtu?”",
        6: "In sambung hi Īsa kaniya, “Aku in dān labayan pa Tuhan. Aku in puunan sin kasabunnalan, lāgi' aku da isab in puunan sin kabuhi'. Wayruun makakadtu pa Tuhan, Ama' ku, bang bukun aku in labayan niya.",
        7: "Na, bihaun pagga niyu aku kaingatan na,” laung hi Īsa kanila, “na kaingatan niyu na isab in Ama' ku. Iban tagnaan dayn ha bihaun kaingatan niyu na tuud siya iban kīta' niyu na siya.”",
        8: "Laung hi Pilip kan Īsa, “Panghu', panyataan kāmu' in Ama' mu ampa kami magkahagad.”",
        9: "In sambung hi Īsa kaniya, “Pilip, malugay na aku dī kaniyu, sagawa' masi namān kaw awam pasal ku. Hisiyu-siyu in nakakita' kāku', na biya' niya da kīta' tuud in Ama' ku. Na, mayta' in kabayaan mu subay pa hipanyata' kaymu in Ama' ku?",
        10: "Mayta', Pilip, di' kaw magparachaya sin in aku kakkal himahambuuk ha Ama' ku iban in Ama' ku kakkal himahambuuk kāku'? In katān kiyahindu' ku kaniyu,” laung hi Īsa ha manga mulid niya, “bukun naug dayn kāku' sagawa' dayn ha Ama' ku, amu in kakkal himahambuuk kāku'. In katān hinang ku hinang da isab sin Ama' ku, karna' siya in himinang sin katān yan.",
        11: "Pagparachaya kamu sin bayta' ku sin in aku kakkal himahambuuk ha Ama' ku iban in Ama' ku kakkal himahambuuk kāku'. Bang sawpama di' kamu magparachaya sin bayta' ku yan, na magparachaya kamu ha manga hinang kīta' niyu nahinang ku.",
        12: "Baytaan ta kamu sin kasabunnalan. Hisiyu-siyu in magparachaya kāku', makahinang siya sin mahinang ku. Lāgi', lumabi pa in hinang niya, sabab in aku magbalik na madtu pa Ama' ku.",
        13: "Na, unu-unu in pangayuun niyu sabab sin pangandul niyu kāku', na, hirihil ku kaniyu, ha supaya dayn ha hinang ku mapakita' in kalagguan sin Tuhan, Ama' ku.",
        14: "Bang kamu mangayu' kāku' unu-unu na ha sabab sin pangandul niyu kāku', hirihil ku kaniyu in pangayuun niyu.”",
        15: "Laung pa isab hi Īsa, “Bang kamu malasa kāku', agarun niyu hadja in katān daakan ku.",
        16: "Pangayuan ta kamu ha Ama' ku hambuuk Mananabang ganti' ku, amu in dumuun kaniyu kasaumulan.",
        17: "In Mananabang ini amuna in Rū sin Tuhan, amu in mamayta' sin kasabunnalan pasal sin Tuhan. Na, in manga tau bukun agad ha Tuhan di' makatayma' ha Mananabang ini, sabab di' nila siya kahātihan iban di' nila siya kaingatan. Sagawa' in kamu, kaingatan niyu siya sabab yari siya, kiyakahagad niyu siya iban taptap siya ha lawm atay niyu.",
        18: "“Minsan aku mutas dayn kaniyu, di' ta kamu pasāran. Magbalik da aku mari kaniyu.",
        19: "Bukun na malugay di' na aku kakitaan sin manga tau bukun agad ha Tuhan. Sagawa' kakitaan aku magbalik ha susūngun. Na, pagga aku taga kabuhi' salama-lama, na in kamu ha susūngun taga kabuhi' da isab salama-lama.",
        20: "Bang dumatung na in waktu yan, kaingatan niyu na sin in aku iban sin Ama' ku naghahambuuk tuud. Damikkiyan, in aku iban sin kamu naghahambuuk da isab.",
        21: "“Hisiyu-siyu in tumayma' iban magkahagad sin daakan ku, amuna in tau malasa kāku' lāgi' hisiyu-siyu in malasa kāku' kalasahan da isab sin Ama' ku. Damikkiyan, in aku malasa da isab ha tau yan, iban hipaingat ku kaniya in katān kahālan pasal ku.”",
        22: "Sakali laung hi Judas, bukun hi Judas tau dayn ha Kiriyud, “Panghu', mayta' kami sadja in paingatun mu sin kahālan mu, hāti in mānusiya' katān di' mu paingatun?”",
        23: "In sambung hi Īsa kaniya, “Hisiyu-siyu in malasa kāku' magkahagad sin hindu' ku. Kalasahan siya sin Ama' ku, lāgi' in aku iban sin Ama' ku duun taptap kaniya.",
        24: "Sagawa' in tau di' malasa kāku' di' magkahagad sin hindu' ku. Na, in hindu' ku yan diyungug niyu bukun guwa' dayn kāku', sagawa' dayn ha Ama' ku amu in nagdaak kāku' mari.",
        25: "“Na, in manga yan asal ku na biyayta' kaniyu ha salugay ku dī pa kaniyu.",
        26: "Sagawa' ha susūngun in Mananabang amu in Rū sin Tuhan patulunun sin Tuhan mawn kaniyu gumanti' kāku'. Hinduan niya kamu sin unu-unu katān, iban siya in magpatumtum kaniyu sin katān kiyahindu' ku kaniyu.",
        27: "“Kasannyangan sin lawm atay iban pikilan in hibīn ku dī kaniyu. In kasannyangan yan guwa' dayn kāku', iban di' yan magsali' iban sin kasannyangan hikarihil kaniyu sin pagkahi niyu mānusiya'. Hangkan ayaw niyu pasusaha in lawm atay niyu. Ayaw kamu mabuga'.",
        28: "“Biya' na sin agi ku kaniyu, in aku mag'iīg na dayn kaniyu, sagawa' magbalik da aku mari kaniyu. Na, bang kamu malasa kāku', subay kamu kūgan sin magbalik na aku madtu pa Ama' ku, karna' labi siya makawasa dayn kāku'.",
        29: "Biyayta' ku na yan kaniyu bihaun ha wala' pa naabut, ha supaya bang yan maabut na, na magparachaya na kamu.",
        30: "Na, di' na aku makapahaba' sin bichara ku kaniyu, sabab masuuk na dumatung in Puntukan Saytan, amu in magbaya' dī ha lawm dunya ini. In aku di' niya kapagbayaan.",
        31: "Sagawa' subay kaingatan sin manga mānusiya' katān sin malasa aku ha Ama' ku, hangkan akuhun ku in katān daakan hipahinang niya kāku'.” Na, mahuli dayn duun, laung hi Īsa, “Sūng na. Mīg na kitaniyu dayn dī.”",
    },
    15: {
        1: "Manjari nagdalil hi Īsa ha manga mulid niya, laung niya, “Aku in puunan batangan sin tiyanum iban Ama' ku in magparuli sin tiyanum.",
        2: "Bang awn sanga ha batangan sin tiyanum ini in di' magbunga, īgan sin Ama' ku. Sagawa' bang in sanga magbunga, hawanan niya yan, ha supaya tumaud in bunga.",
        3: "Na, in kamu yan limanu' na pasal sin hindu' ku kaniyu.",
        4: "Sagawa' subay kamu tutug humambuuk kāku', iban in aku tutug humambuuk kaniyu. Karna' biya' da sa yan sapantun sin sanga. Bang yan matigpu' dayn ha puunan batangan niya, na, di' yan magbunga. Magbunga sadja yan bang di' matigpu' dayn ha puunan batangan niya. Damikkiyan, in kamu, di' kamu makahinang sin marayaw bang kamu bukun tutug himahambuuk kāku'.",
        5: "“In aku amuna in biya' sapantun puunan batangan sin tiyanum, hāti in kamu amuna in manga sanga. Hisiyu-siyu in tutug humambuuk kāku' iban tutug da isab aku humambuuk kaniya, na, sumūng in dayaw sin kawl-piil niya biya' sin sanga mataud bunga niya. Sagawa' bang kamu umukat dayn kāku', in guwaan sin manga hinang niyu way kapūsan.",
        6: "Hisiyu-siyu in di' tumutug humambuuk kāku' hibugit siya biya' sapantun sin sanga uturun patahayun. Ubus in katān sanga biya' ha yan tipunun ampa hilaruk pa kāyu sunugun.",
        7: "Sagawa' bang kamu tutug humambuuk kāku', iban pahūpun niyu pa lawm pikilan niyu in hindu' ku, na hirihil ku kaniyu in unu-unu pangayuun niyu kāku'.",
        8: "Bang sumūng in dayaw sin kawl-piil niyu, na, in yan amu in magpakita' sin kalagguan sin Tuhan, iban dayn duun kaingatan na sin in kamu tantu tuud manga mulid ku.",
        9: "“In lasa ku kaniyu biya' da sin lasa sin Ama' ku kāku'. Hangkan taw'an ha lawm atay niyu in lasa ku kaniyu.",
        10: "Bang niyu agarun in daakan ku tumutug in lasa ku kaniyu. Biya' da isab sin aku iyagad ku in daakan kāku' sin Ama' ku, hangkan tutug in lasa niya kāku'.",
        11: "“Biyaytaan ta kamu ha yan ha supaya taptap kananaman niyu in kakuyagan guwa' dayn kāku', iban ha supaya jumukup in kakuyagan niyu.",
        12: "Na, bihaun amu tuud ini in daakan ku kaniyu. Paglasa-liyasahi kamu biya' sin lasa ku kaniyu.",
        13: "Bang awn tau lilla' matay pasal sin lasa niya ha manga bagay niya, na wayruun na makaliyu sin lasa biya' ha yan.",
        14: 'In manga kamu yan, bagay ku na, bang niyu agarun in unu-unu daakan ku kaniyu.',
        15: "Di' ta na kamu itungun manga tindug ku, sabab in tindug di' pagpaingatun sin nakura' sin unu-unu katān pasal niya. Sagawa' in manga kamu yan itungun ku na manga bagay ku tuud sabab piyaingat ku na kaniyu in katān diyungug ku dayn ha Ama' ku.",
        16: "Bukun kamu in nagpī' kāku' manghindu' kaniyu, sagawa' aku in nagpī' kaniyu hīnang manga wakil ku huminang sin manga marayaw. In karayawan sin hinang niyu yan tumatas kasaumulan. Hangkan hirihil sin Ama' ku kaniyu in unu-unu pangayuun niyu, sabab sin pangandul niyu kāku'.",
        17: 'Na, ini in daakan ku kaniyu, paglasa-liyasahi kamu.”',
        18: 'Laung pa isab hi Īsa, “Na, ayaw kamu mainu-inu, bang kamu kabunsihan sin manga tau bukun agad ha Tuhan. Amu sadja in tumtuma niyu minsan in aku kiyabunsihan nila da. Aku in muna dayn kaniyu kiyabunsihan.',
        19: "Bang sawpama kamu hangka-agaran iban sin manga tau bukun agad ha Tuhan, tantu kalasahan nila kamu. Sagawa' dugaing kamu. Bukun kamu hangka-agaran iban sila sabab pinī' ta kamu piyakandī dayn kanila. Hangkan na sila mabunsi kaniyu.",
        20: "Tumtuma niyu in bakas biyayta' ku kaniyu sin in tindug bukun makawasa dayn ha nakura'. Pagga in aku ngī' sin manga tau yan, na damikkiyan in kamu ngīun nila da isab. Pagga nila wala' kiyahagad in hindu' ku, na di' nila da isab kahagarun in hindu' niyu.",
        21: "Sagawa' kabunsihan iban ngīun nila kamu sabab in kamu agad kāku'. Hangkan biya' ha yan in hinang nila kaniyu, sabab di' nila kaingatan tuud in Tuhan amu in nagdaak kāku' mari.",
        22: "Bang aku wala' miyari pa dunya namayta' kanila sin kasabunnalan di' tumampal in manga dusa nila. Sagawa' bihaun way na hikadaawa nila sin dusa nila, sabab piyaingat ku na kanila in kasabunnalan.",
        23: "Hisiyu-siyu in mabunsi kāku', kabunsihan niya da isab in Ama' ku.",
        24: "Di' tumampal in manga dusa nila bang nila wala' kīta' sin duwa mata nila in manga hinang nahinang ku amu in wala' nahinang sin minsan hisiyu tau. Sagawa' minsan yan kīta' nila na, masi sila mabunsi kāku' iban ha Ama' ku.",
        25: "Sagawa' asal subay aku kabunsihan nila ha supaya mabunnal in kiyasulat ha lawm sara' biyabantug nila, amu agi, ‘Kabunsihan nila aku minsan way puun sabab.’",
        26: "“Patulunun ku mari kaniyu in Mananabang. In Mananabang ini, amuna in Rū sin Tuhan, amu in mamayta' sin kasabunnalan pasal sin Tuhan sabab in siya naug dayn ha Tuhan. Patulunun ku siya mawn kaniyu, mamayta' kaniyu sin pasal ku.",
        27: "Na, damikkiyan in kamu mamayta' da isab ha manga tau sin pasal ku sabab dayn sin tagna' in kamu miyamagad kāku'.”",
    },
    16: {
        1: "Laung pa isab hi Īsa ha manga mulid niya, “Na, in yan asal ku na biyayta' kaniyu ha supaya di' maīg in īman niyu kāku'.",
        2: "Sabab ha susūngun di' na kamu palamurun sin manga nakura' sin agama ha lawm sin manga langgal nila. Lāgi' ha susūngun bang awn tau mamatay hisiyu-siyu na kaniyu, in pangannal niya in nahinang niya yadtu kabayaan sin Tuhan.",
        3: "Biya' ha yan in hinang sin manga tau yan kaniyu, sabab wala' nila tuud kiyaingatan in Ama' ku iban di' nila da isab aku kaingatan.",
        4: "Biyaytaan ta kamu asal sin pasal yan ha supaya bang maabut na in waktu kabunsihan na kamu sin manga tau yan, na katumtuman niyu in biyayta' ku kaniyu.",
        5: "“Na in manga yan wala' ku biyayta' kaniyu sin tagna' sabab yari pa aku dī kaniyu. Sagawa' bihaun maray' na aku magbalik madtu pa bakas nagdaak kāku' mari pa dunya. Malayngkan, way minsan hambuuk kaniyu in nangasubu bang pakain aku.",
        6: "Na, bihaun landu' nasusa in lawm atay niyu pasal sin biyayta' ku kaniyu.",
        7: "Sagawa' baytaan ta kamu sin kasabunnalan, hikarayaw kaniyu sin mutas aku dayn kaniyu. Sabab bang aku di' mutas dayn kaniyu, in Mananabang di' makakari kaniyu. Sagawa' bang aku mutas dayn kaniyu, mapakari ku in Mananabang kaniyu.",
        8: 'Na, bang dumatung na mari in Mananabang yan, pahātihun niya tuud marayaw in manga tau pasal sin dusa nila, pasal sin kabuntulan iban pasal sin hukuman sin Tuhan.',
        9: "Pahātihun niya in manga tau sin in sila nagdusa pasal wala' sila nagparachaya kāku'.",
        10: "Pahātihun niya in manga tau sin in aku tantu mabuntul tuud sabab in aku magbalik na madtu pa Tuhan, Ama' ku, iban di' niyu na aku kakitaan.",
        11: "Pahātihun niya in manga tau pasal sin hukuman sin Tuhan, karna' in Puntukan Saytan, amu in magbabaya' ha lawm dunya ini kiyabutangan na hukuman sin Tuhan.",
        12: "“Mataud pa in hibayta' ku kaniyu, sagawa' bihaun di' marā sin pikilan niyu bang ku hibayta' kaniyu.",
        13: "Sagawa' bang dumatung na mari in Rū sin Tuhan, amu in magpaingat kaniyu sin kasabunnalan pasal sin Tuhan, hinduan niya kamu sin katān kasabunnalan. In hindu' niya kaniyu bukun guwa' dayn kaniya, sagawa' in unu-unu karungugan niya dayn ha Tuhan amu in hibayta' niya kaniyu. Baytaan niya kamu bang unu in maawn ha susūngun.",
        14: "Iban dihilan niya aku kalagguan sabab in katān hihindu' niya kaniyu asal da dayn kāku'.",
        15: "In unu-unu katān sin Ama' ku kāku' da isab, hangkan laung ku kaniyu in unu-unu katān hihindu' kaniyu sin Rū sin Tuhan guwa' dayn kāku'.”",
        16: "Laung pa isab hi Īsa, “Bukun na malugay di' niyu na aku kakitaan. Sagawa' bukun na isab malugay kakitaan niyu na aku magbalik.”",
        17: "Na, nag'asubu-iyasubuhi na in manga mulid niya kaibanan, laung nila, “Unu baha' in hāti sin bichara niya yadtu, sin bukun na malugay, di' natu' na siya kakitaan, sagawa' bukun da isab malugay, kakitaan natu' da siya magbalik? Iban imiyan pa isab siya, karna' in siya magkakadtu pa Ama' niya.",
        18: "Unu baha' in hāti sin bichara niya, bukun na malugay? Di' natu' kahātihan bang unu in piyagbibichara niya!”",
        19: "Na, kiyaiingatan hi Īsa sin mabaya' mangasubu kaniya in manga mulid niya. Hangkan laung niya kanila, “Amu ka in piyag'asubu-iyasubuhi niyu in hāti sin bichara ku amu in biyayta' ku kaniyu, laung ku, ‘Bukun na malugay di' niyu na aku kakitaan, sagawa' bukun da isab malugay, kakitaan niyu da aku magbalik’?",
        20: "Na, in bunnal niya, in kamu yan magtangis iban magdukka, sagawa' makuyag in manga tau bukun agad ha Tuhan. Masusa kamu sagawa' kakuyagan in ganti' sin kasusahan niyu.",
        21: "In kasusahan niyu yan bihaun biya' da sa yan sapantun sin kasusahan sin hambuuk babai masuuk na mag'anak. Masusa siya sabab masuuk na dumatung in waktu numanam siya sin masakit. Sagawa' pag'ubus niya mag'anak, kalupahan niya na in sakit niyanam niya sabab makuyag na siya sin in anak niya limahil na pa dunya.",
        22: "Na, biya' da isab ha yan in hantang niyu. Bihaun masusa kamu, sagawa' kakitaan ta kamu magbalik. Lāgi' kūgan tuud kamu iban wayruun makaīg sin kakuyagan niyu yan dayn ha lawm atay niyu.",
        23: "“Na, bang dumatung na in waktu yan, minsan kamu di' na mangasubu kāku' unu-unu. Baytaan ta kamu sin bunnal, unu-unu in pangayuun niyu ha Ama' ku sabab sin pangandul niyu kāku', hirihil niya kaniyu.",
        24: "Dayn sin tagna' sampay pa bihaun wala' kamu nakapangayu' unu-unu sabab sin pangandul niyu kāku'. Pangayu' kamu ampa kamu karihilan, ha supaya jumukup in kakuyagan niyu.”",
        25: "Laung pa isab hi Īsa, “In manga hindu' kiyahindu' ku kaniyu labay dayn ha manga bichara dalil, sumagawa' awn da waktu dumatung ha susūngun di' ku na hilabay dayn ha manga bichara dalil. Pahantapun ku na tuud kaniyu in paghindu' ku ha pasalan sin Ama' ku.",
        26: "Ha waktu susūngun, bang awn pangayuun niyu, baran niyu na in mangayu' ha Ama' ku sabab sin pangandul niyu kāku'. Minsan bukun na aku in mangayu' kaniya para kaniyu,",
        27: "sabab in Ama' ku malasa kaniyu. Hangkan kamu kiyalasahan niya sabab malasa kamu kāku' iban magparachaya kamu sin naug aku dayn ha Tuhan.",
        28: "Mattan tuud in aku miyari pa dunya naug dayn ha Tuhan, Ama' ku. Na, bihaun mīg na aku dayn ha dunya ini, madtu na magbalik pa Ama' ku.”",
        29: "Sakali laung sin manga mulid niya kaniya, “Na, bihaun mahantap na in bichara mu kāmu' sabab wala' na kaw nagbichara dalil.",
        30: "Bihaun natantu namu' na tuud sin kaingatan mu in unu-unu katān, sabab minsan in tau di' pa makapangasubu kaymu, kaingatan mu na asal in hipangasubu niya. Hangkan magparachaya na tuud kami sin in ikaw naug dayn ha Tuhan.”",
        31: "In sambung hi Īsa kanila, “Bunnal ka yan sin magparachaya na tuud kamu kāku' bihaun?",
        32: "Ingat kamu, masuuk na tuud dumatung in waktu in kamu katān makawkanat na. Mag'uwian na kamu pakaniya-pakaniya pa luggiya' hula' niyu. Hibīn niyu na aku isa-isa ku. Sagawa' minsan niyu aku hibīn, awn da iban ku sabab in Ama' ku tutug himahambuuk kāku'.",
        33: "“Na, hangkan ku ini biyayta' kaniyu ha supaya awn kasannyangan sin lawm atay niyu pasal sin paghambuuk niyu iban aku. Pananamun kamu kabinsanaan sin manga tau bukun agad ha Tuhan, sagawa' ayaw kamu mabuga', sabab diyaug ku na in manga tau bukun agad ha Tuhan.”",
    },
    17: {
        1: "Manjari pag'ubus hi Īsa nagbichara ha manga mulid niya, himangad siya pa langit ampa siya nangarap pa Tuhan, laung niya, “Ū Ama' ku, naabut na in waktu kiyaganta'. Dihili aku kalagguan, aku amu in Anak mu, ha supaya ku isab mapakita' in kalagguan mu.",
        2: "Kiyarihilan mu aku kawasa magbaya'-baya' ha katān mānusiya' ha supaya ku karihilan kabuhi' salama-lama in sasuku' sin manga tau kiyasuku' mu kāku'.",
        3: "Na, ha supaya in manga mānusiya' makabaak sin kabuhi' salama-lama, subay nila kaw kaingatan sin ikaw na tuud in hambuuk-buuk Tuhan sabunnal iban subay nila da isab aku kaingatan sin aku amuna in Almasi kiyawakilan mu mari pa dunya.",
        4: "Napakita' ku na in kalagguan mu dī ha dunya sabab naubus ku na hīnang in katān hinang piyahinang mu kāku'.",
        5: "Ū, Ama', dihili aku kalagguan duun ha haddarat mu biya' sin kalagguan ku sin waktu duun aku kaymu ha wala' pa naawn in dunya ini.",
        6: "“Piyahāti ku na ha manga mānusiya' in pasal mu, amu in manga mānusiya' siyuku' mu kāku' dī ha lawm dunya. In sila asal manga suku' mu, ampa siyuku' mu isab sila kāku'. Nagkahagad na sila sin Parman mu,",
        7: "iban nakaingat na sila sin in katān dīhil mu kāku' tantu tuud naug dayn kaymu.",
        8: "Sabab napasampay ku na kanila in manga hindu' amu in nakawa' ku dayn kaymu iban tiyayma' nila na. Lāgi' natantu nila na tuud sin in aku naug dayn kaymu iban magparachaya na sila sin in aku naraak mu.",
        9: "“In pangayuan ku ini duwaa bukun amu in manga mānusiya' katān, sagawa' amu in manga tau siyuku' mu kāku' karna' in sila asal manga suku' mu.",
        10: "In katān suku' ku, suku' mu da isab, iban in katān suku' mu, suku' ku da isab. Sila ini in magpakita' sin kalagguan ku.",
        11: "Na, bihaun mag'uuwi' na aku magbalik mawn kaymu. Mag'iīg na aku dayn ha dunya ini sagawa' in manga tau suku' ku yari pa masi ha dunya. Ū, Ama' ku Mahasuchi, ayari kaagi sin kusug sin kawasa mu, in manga tau amu in dīhil mu kāku'. Ayari sila ha supaya tutug in paghambuuk nila biya' sin katutug sin paghambuuk ku iban ikaw.",
        12: "Ha salugay ku nag'aagad iban sin manga tau kiyasuku' mu kāku', iyaayaran ku sila kaagi sin kusug sin kawasa mu. Wayruun minsan hambuuk kanila in nalawa' dayn kāku' luwal da in hambuuk suku' sin narka' amu in asal kiyaganta' malawa' dayn kāku' ha supaya maagad in kiyabayta' ha lawm Kitab.",
        13: "“Na, bihaun mag'uuwi' na aku magbalik mawn kaymu. Hangkan ha salugay ku pa dī ha dunya hibayta' ku in katān ini kanila ha supaya in lawm atay nila mahipu' sin kakuyagan biya' sin kakuyagan ku.",
        14: "Kiyapasampay ku na in hindu' mu pa manga tau suku' mu. Sakali kiyarugalan sila sin manga pagkahi nila mānusiya' sabab in manga tau suku' mu bukun hangka-pikilan iban sin manga tau bukun agad kaymu. Biya' da isab sila kāku', bukun hangka-pikilan iban sin manga tau bukun agad kaymu.",
        15: "Malayngkan, bukun in pangayuun ku kaymu in īgan mu sila dayn ha dunya ini, sagawa' in pangayuun ku kaymu ayaran mu sila bat sila di' kapagbayaan sin Iblis, amu in puunan sin katān kangīan.",
        16: "In manga tau suku' ku sibu' na tuud iban aku sabab in pikilan nila bukun na biya' sin pikilan sin manga mānusiya' dī ha dunya.",
        17: "Bang mayan isab sila pakandihun mu, iban suchihun mu in lawm atay nila. In kasabunnalan sin manga katān kiyabayta' ha Parman mu amu in makasuchi sin lawm atay nila.",
        18: "Naraak ku na sila mawn pa manga mānusiya' biya' da isab sin aku naraak mu mari pa dunya.",
        19: "Iban dayn ha pasal nila hibugsu' ku kaymu in dugu'-nyawa ku ha supaya masuchi in lawm atay nila iban tūpun sila mahinang manga suku' mu.",
        20: "“Bukun sadja isab manga mulid ku in pangayuan ku duwaa,” laung hi Īsa, “sagawa' sampay manga tau amu in ha susūngun magparachaya kāku' sabab sin pagnasīhat sin manga mulid ku.",
        21: "Iban, Ū Ama', pangayuun ku isab kaymu bang mayan isab in sila katān maghangka-atay iban maghangka-pikilan. Bang mayan sila humambuuk kātu' biya' sin ikaw tutug himahambuuk kāku' iban in aku tutug himahambuuk kaymu. Bang mayan sila humambuuk kātu' ha supaya in manga mānusiya' magparachaya sin ikaw in nagpakari kāku'.",
        22: "Damikkiyan, kiyarihil ku na kanila in kalagguan biya' sin kalagguan kiyarihil mu kāku', ha supaya sila mahambuuk biya' sin kita maghahambuuk.",
        23: "Tutug aku humambuuk kanila biya' sin ikaw tutug himahambuuk kāku', ha supaya sila maghangka-atay tuud. Na, bang sila maghangka-atay na, na kaingatan na sin manga mānusiya' sin ikaw in nagdaak kāku' mari, iban kaingatan nila na sin kalasahan mu in manga tau suku' ku biya' sin lasa mu kāku'.",
        24: "“Ū Ama', in kabayaan ku makapaghambuuk aku didtu ha hulaan ku iban sin manga kiyasuku' mu kāku', ha supaya kakitaan nila in sahaya iban kalagguan ku, amu in kalagguan dīhil mu kāku' pasal asal kaw malasa kāku' ha wala' pa naawn in dunya.",
        25: "“Ū, Ama', ikaw in puunan sin kabuntulan. Di' kaw kaingatan sin manga tau bukun agad kaymu, sagawa' kaingatan ta kaw iban kaingatan da isab sin manga tau agad kāku' sin ikaw in nagpakari kāku'.",
        26: "Piyahāti ku na kanila in pasal mu, iban di' ku bugtuun in pagpahāti kanila ha supaya humūp in lasa mu kanila biya' sin lasa mu himūp kāku', iban ha supaya aku di' malawa' dayn ha lawm atay nila.”",
    },
    18: {
        1: "Manjari pag'ubus hi Īsa nangayu' duwaa, miyadtu siya iban sin manga mulid niya pa hansipak sin Sapa' Kidrun. Pagdatung nila pa lugal yaun, timūy siya iban sin manga mulid pa lawm kabbun.",
        2: 'Na, kiyaingatan hi Judas, amu in panipu, in lugal kiyadtuan hinda Īsa sabab asal niya kabiyaksahan sin mawmu hinda Īsa magtipun duun iban sin manga mulid niya.',
        3: "Hangkan hi Judas in nagmalim ha manga sundalu bangsa Rūm iban sin manga pulis jaga sin Bāy sin Tuhan amu in naraak sin manga nakura' kaimaman iban sin manga Parisi, madtu pa lawm kabbun. Nagdarā sila manga pakukus, manga tanju', iban parul.",
        4: "Sakali asal kiyatalusan hi Īsa in unu-unu katān sūng kumugdan kaniya. Hangkan pagdatung mawn sin manga sundalu iban manga pulis jaga, biyāk niya sila sarta' laung hi Īsa kanila, “Hisiyu in liyawag niyu?”",
        5: 'Na, in sambung nila, “Hi Īsa, amu in tau dayn ha Nasarit.” Laung hi Īsa, “Na, aku na sa ini in tau piyaglawag niyu.” Na, in hi Judas amu in manipu kan Īsa, yaun miyamagad ha manga sundalu iban manga pulis jaga.',
        6: "Sakali pag'iyan hi Īsa sin siya na in tau piyaglawag nila nakasigput sila pa ulihan iban naligad sila pa lupa'.",
        7: 'Na, iyasubu sila nagbalik hi Īsa, laung niya, “Hisiyu in liyawag niyu?” In sambung nila, “Hi Īsa, amu in tau dayn ha Nasarit.”',
        8: "Laung hi Īsa kanila, “Biyaytaan ta na kamu sin aku na in tau piyaglawag niyu. Bang aku tuud in tau piyaglawag niyu, na yari na aku. Sagawa' ayaw niyu lapaya in manga iban ku ini.”",
        9: "Piyamung niya yan ha supaya maagad in bakas kiyapamung niya, amu agi, “Ū Ama', di' kalawaan minsan hambuuk in manga tau kiyasuku' mu kāku'.”",
        10: "Sakali ini magtūy liyarut hi Simun Pitrus in pakukus tiyatakus niya, ampa niya liyagut in hambuuk īpun sin Imam Dakula'. Nautud in taynga dapit pa tuu sin tau liyagut niya. In ngān sin īpun yadtu hi Malkus.",
        11: "Laung hi Īsa kan Pitrus, “Butangan magbalik in pakukus mu pa taguban niya! Akuhun ku in katān kabinsanaan ini sabab asal ini in kiyaganta' kāku' sin Ama' ku.”",
        12: 'Na, siyaggaw na hi Īsa sin manga sundalu bangsa Rūm iban sin kapitan nila iban sin manga pulis jaga sin bangsa Yahudi, ampa nila siya hiyukutan.',
        13: "Pag'ubus ampa nila siya diyā muna madtu kan Annas amu in ugangan usug hi Kayapas. In hi Kayapas amu in Imam Dakula' sin tahun yadtu.",
        14: "In hi Kayapas ini amu in bakas nanghindu' ha manga nakura' Yahudi, sin marayaw pa hambuuk sadja tau in mapatay ganti' sin sila katān.",
        15: "Na, miyurul kan Īsa hi Simun Pitrus iban sin hambuuk mulid, amu in mag'īngati tuud iban sin Imam Dakula'. Hangkan in mulid ini nakaagad kan Īsa simūd pa lawm halaman sin bāy sin Imam Dakula'.",
        16: "Na, in hi Pitrus duun nakabīn ha guwa' sin lawang. Hangkan gimuwa' nagbalik in mulid amu in mag'īngati iban sin Imam Dakula', ampa niya biyairan piyasūd hi Pitrus dayn ha babai amu in jaga sin lawang. Na, nakasūd na hi Pitrus.",
        17: 'Sakali iyasubu hi Pitrus sin babai nagjajaga ha lawang, amu agi, “Bukun ka in ikaw hambuuk mulid sin tau nasaggaw yaun?” Namaylu hi Pitrus, laung niya, “Bukun.”',
        18: "Manjari nagpabaga buling in manga daraakun sin Imam Dakula' iban sin manga jaga sabab mahaggut in hula' sin dūm yadtu. Ubus ampa sila duun timindug nagpaanag ha katilibut sin baga kāyu. Na, miyawn hi Pitrus limamud kanila nagpaanag.",
        19: "Manjari siyumariya hi Īsa kaagi hi Annas, amu in bakas Imam Dakula', pasal sin manga mulid niya iban sin panghindu' niya ha manga tau.",
        20: "In sambung hi Īsa, “In aku nanghindu' duun sadja ha mayran bat karungugan sin manga tau katān. Nanghindu' aku ha manga kalanggalan iban ha Bāy sin Tuhan, amu in pagtitipunan sin manga Yahudi. Bukun tapuk in pagnasīhat ku ha manga tau.",
        21: "Na, mayta' mu aku sumariyahun pasal sin paghindu' ku? In subay sumariyahun mu in manga tau nakarungug sin hindu' ku. Asubuha sila bang unu in biyayta' ku kanila. Kaingatan nila bang unu in hīndu' ku kanila.”",
        22: "Pag'ubus hi Īsa namichara biya' hādtu nagtūy siya siyampak ha bayhu' sin hambuuk pulis jaga. Amu agi sin jaga kaniya, “Halipulu kaw ini. Ayaw kaw magpamung biya' ha yan ha Imam Dakula'.”",
        23: "In sambung hi Īsa, “Bang sawpama awn mangī' kiyapamung ku ha Imam Dakula', na baytaan pa tau katān yari ha lawm paghuhukuman ini, sagawa' bang wayruun mangī' kiyapamung ku, na mayta' mu aku siyampak?”",
        24: "Na, pag'ubus tiyukbal na hi Annas hi Īsa pa lawm lima hi Kayapas, amu in Imam Dakula', sagawa' in hi Īsa masi hiyuhukutan.",
        25: "Na, in hi Pitrus masi duun nagtitindug ha daig sin kāyu pagpaanagan. Sakali iyasubu siya sin manga kaibanan tau nagtitindug duun, amu agi kaniya, “Bukun ka in ikaw hambuuk mulid sin tau yaun?” Sagawa' namaylu hi Pitrus, laung niya, “Bukun.”",
        26: "Sakali namung in hambuuk īpun sin Imam Dakula', kampung sin tau amu in nalagut in taynga kaagi hi Pitrus. Amu agi kan Pitrus, “Bukun ka kīta' ta kaw didtu ha lawm sin kabbun miyamagad kan Īsa?”",
        27: 'Na, namaylu na isab nagbalik hi Pitrus. Sakali saruun-duun timagauk na in manuk usug.',
        28: "Manjari pagga lapit adlaw na, diyā nila na hi Īsa dayn ha bāy hi Kayapas madtu pa astana' sin gubnul sin bangsa Rūm. Sagawa' in manga nakura' Yahudi wala' simūd pa lawm sin astana' sabab maba'tal sila bang sila sumūd pa bāy sin bukun Yahudi. Ampa bang sila maba'tal di' sila makalamud kumaun sin pagjamu sin Haylaya Paglappas dayn ha Kamatay.",
        29: "Hangkan gimuwa' hi Gubnul Pilatu, miyawn nangasubu ha manga nakura' Yahudi. Amu agi hi Gubnul Pilatu kanila, “Unu ta' in narusa sin tau ini hangkan niyu siya tiyuntutan?”",
        30: "In sambung nila, “Bang in tau yan wala' nakarusa di' namu' siya dāhun mari kaymu.”",
        31: "Laung hi Pilatu kanila, “Na, pagga biya' ha yan, dāha niyu na siya ampa niyu butangi hukuman agad ha aturan sin sara' niyu.” In sambung sin manga nakura' Yahudi, “Way kawasa namu' dumihil hukuman hipapatay in hisiyu-siyu tau nakarusa.”",
        32: "Na, dayn ha sambung nila yan, naagad in bakas bichara hi Īsa pasalan sin bang biya' diin kaagi in pagpatay kaniya.",
        33: "Sakali simūd nagbalik hi Pilatu pa lawm sin astana' ampa niya piyatawag hi Īsa iyasubu. Laung niya kan Īsa, “Ikaw na ka in sultan sin manga Yahudi?”",
        34: "In sambung hi Īsa, “In pangasubu mu yan, guwa' ka dayn ha pikilan mu atawa awn tau dugaing namayta' kaymu pasal ku?”",
        35: "In sambung hi Pilatu, “Mayta', in pangannal mu Yahudi aku? Manga pagkahi mu Yahudi iban sin manga nakura' kaimaman in timukbal kaymu mari kāku'. Unu in narusa mu?”",
        36: "Na, in sambung hi Īsa, “In hula' piyagsusultanan ku bukun dī ha dunya ini. Sabab bang in hula' piyagsusultanan ku bat dī ha dunya ini, na umatu in manga tau agad kāku' ha supaya aku di' masaggaw sin manga nakura' Yahudi. Sagawa' wala' sila imatu sabab bukun dī ha dunya in hula' piyagsusultanan ku!”",
        37: "Na, laung hi Pilatu, “Na, bang bihādtu, sultan kaw?” In sambung hi Īsa, “Na, biya' sin agi mu, in aku sultan. Amu yan in sabab hangkan aku piyag'anak iban limahil mari pa dunya ha supaya ku hikabayta' in kasabunnalan. Na, hisiyu-siyu in agad ha kasabunnalan, magparachaya siya sin bayta' ku.”",
        38: "Laung hi Pilatu, “Unu baha' in kasabunnalan?”",
        39: "Manjari pag'ubus hi Pilatu nangasubu kan Īsa, gimuwa' siya nagbalik madtu pa manga Yahudi. Laung niya kanila, “Wayruun dusa niya kiyabaakan ku amu in mapatut ku butangan hukuman. Malayngkan,” laung hi Pilatu, “biya' na sin pagkabiyaksahan niyu, ha sakaba' waktu sin Haylaya Paglappas dayn ha Kamatay, awn pagpaguwaun ku hambuuk pilisu. Mabaya' kamu paguwaun ku kaniyu in sultan sin manga Yahudi?”",
        40: "Na, imulang in manga nakura' Yahudi, amu agi, “Ayaw mu siya paguwaa! Hi Barabbas in kabayaan namu' paguwaun mu!” (In hi Barabbas ini hambuuk mundu.)",
    },
    19: {
        1: "Manjari nag'uldin na hi Pilatu palubakan hi Īsa sin lalagut hipanglulubak.",
        2: "Pag'ubus ampa in manga sundalu kimawa' manga sanga kahuy matunuk, ampa nila liyubid hīnang biya' kuruna ampa siyangun pa ū hi Īsa. Sarta' siyulugan nila hi Īsa sin siub badju' taluk biya' sin siub badju' sin sultan.",
        3: "Ubus ampa siya iyalup sin manga sundalu iyudju'-udju', laung nila, “Mabuhay in Sultan sin manga Yahudi!” Ubus ampa nila siyampak hi Īsa.",
        4: "Sakali gimuwa' nagbalik hi Pilatu miyadtu pa manga tau mataud natitipun, laung niya ha manga tau, “Kitaa niyu ba, paguwaun ku hi Īsa mari kaniyu ha supaya niyu kaingatan sin wayruun ngī' kiyabaakan ku kaniya amu in mapatut butangan hukuman.”",
        5: "Na, narā na mawn pa guwa' hi Īsa, lāgi' masi siyasangunan in ū niya sin sanga kahuy matunuk, iban nagsusu'lug siya sin siub badju' taluk. Laung hi Pilatu ha manga tau, “Kitaa niyu ba, yari na in tau ini!”",
        6: "Pagkita' sin manga nakura' kaimaman iban sin manga pulis jaga sin Bāy sin Tuhan kan Īsa, magtūy sila nag'ulang-ulang, laung nila, “Pataya siya! Palansangan siya pa usuk bat siya mapatay na!” Laung hi Pilatu kanila, “Dāha niyu na siya ampa niyu lansangan pa usuk karna' wayruun ngī' kiyabaakan ku kaniya amu in mapatut pamatayan ku kaniya.”",
        7: "In sambung sin manga Yahudi, “Bang ha lawm sara' namu' subay siya patayun sabab naggulal siya sin baran niya Anak Tuhan.”",
        8: "Pagdungug hi Pilatu sin bichara nila, gām mayan na siya miyuga'.",
        9: "Simūd siya nagbalik pa lawm astana' ampa niya iyasubu hi Īsa, laung niya, “Tau dayn diin kaw?” Sagawa' wala' simambung hi Īsa.",
        10: "Laung hi Pilatu kaniya, “Mayta' kaw di' sumambung kāku'? Wala' mu ka kiyaingatan sin awn kawasa ku magpaguwa' kaymu? Damikkiyan, awn da isab kawasa ku magpalansang kaymu pa usuk bat kaw matay.”",
        11: "In sambung hi Īsa, “Bang kaw wala' dīhilan sin Tuhan kawasa, na way sa yan kapatut mu dumihil hukuman kāku'. Hangkan labi dakula' in dusa sin tau timukbal kāku' mari kaymu dayn sin dusa mu.”",
        12: "Pagdungug hi Pilatu sin bichara hi Īsa, limāg siya dān sin hikapuas niya kan Īsa. Sagawa' imulang in manga tau mataud, amu in manga Yahudi, laung nila, “Bang mu siya paguwaun kumangī' na in pagbagay mu iban sin sultan sin hula' Rūm! Karna' hisiyu-siyu in naggulal sin baran niya sultan, na in siya yan kimuntara ha sultan sin hula' Rūm!”",
        13: "Na, pagdungug hi Pilatu sin bichara sin manga tau, diyā niya hi Īsa pa guwa' ampa siya limingkud ha lingkuran sin manghuhukum didtu ha lugal pagtawagun Halaman Batu. (Bang ha bahasa Hibrani in ngān sin lugal yadtu Gabbata.)",
        14: 'Na, in adlaw yadtu kimugdan ha waktu sin Haylaya Paglappas dayn ha Kamatay, ha adlaw pagngānan Adlaw Pagsakap. Pagga mataas na suga, laung hi Pilatu ha manga tau, “Yari na in sultan niyu!”',
        15: "Sagawa' imulang na isab in manga tau, laung nila, “Papatayan siya! Papatayan siya! Palansangan siya pa usuk!” Laung hi Pilatu kanila, “Mabaya' kamu hipalansang ku pa usuk in sultan niyu?” In sambung sin manga nakura' kaimaman, “Way sultan namu' dugaing dayn sin sultan sin hula' Rūm!”",
        16: "Na, pagga biya' hādtu in bichara sin manga tau, na tiyukbal na hi Pilatu kanila hi Īsa, hipapalansang pa usuk bat matay.",
        17: "Sakali diyā nila na hi Īsa gimuwa' dayn ha lawm dāira. Hi Īsa in piyapagguyud nila sin usuk pagpatayan kaniya sampay sila nakaabut pa lugal pagngānan kulakub ū. (Bang ha bahasa Hibrani, Gulguta.)",
        18: "Na, pagdatung nila mawn, liyansang na sin manga sundalu hi Īsa pa usuk, ubus ampa nila piyatindug iyusuk pa lupa'. Sakali awn isab duwa tau liyansang pa usuk, ubus ampa iyusuk pa lupa' duun ha kīd pa kīd sin kiyausukan kan Īsa.",
        19: 'Manjari awn sulat pahāti biyutang ha usuk piyaglansangan kan Īsa. In pahāti ini siyulat hi Pilatu, amu agi sin pahāti, “Hi Īsa, tau Nasarit, Sultan sin manga Yahudi.”',
        20: "Mataud tau in nakabacha sin pahāti sabab in lugal piyagpatayan kan Īsa bukun malayu' dayn ha dāira. In pahāti yadtu siyulat ha tūngka-ginis bahasa: ha bahasa Hibrani, ha bahasa sin manga tau Rūm, iban ha bahasa Girik.",
        21: "Sakali laung sin manga nakura' kaimaman kan Pilatu, “In sulat pahāti mu wala' nakaamu sabab biya' ha ini in siyulat mu, ‘In tau ini amuna in Sultan sin manga Yahudi!’ Subay biya' ha ini in sulat pahāti mu bat makaamu, laung mu, ‘In tau ini nag'iyan sin in siya Sultan sin manga Yahudi!’”",
        22: "In sambung hi Pilatu kanila, “In bakas ku na kiyasulat di' na kapindahan.”",
        23: "Na, pagga naubus na kiyalansang sin manga sundalu hi Īsa pa usuk, kiyawa' nila in katān siyusu'lug hi Īsa ampa nila piyagbahagian nag'upat. In hambuuk pa hambuuk sundalu kimā' hangka-bahagi'. Kiyawa' nila da isab in juba hi Īsa amu in hiyahablun way sugpat niya.",
        24: "Laung sin manga sundalu pakaniya-pakaniya, “Subay natu' di' gisiun in juba ini. Sapādpād gisiun gām natu' na piyagkuut-kuutan, ingatun bang hisiyu in makakawa'.” Na, in hīnang sin manga sundalu yan nakarihil kasabunnalan sin asal kiyasulat ha lawm Kitab Jabur, amu agi, “Piyagbahagian nila in siyusu'lug ku, iban piyagkuut-kuutan nila in juba ku.” Na, naagad tuud in kiyasulat ha lawm Kitab karna' biya' da hādtu in hinang sin manga sundalu.",
        25: "Na, in ina' hi Īsa duun nagtitindug masuuk pa usuk piyaglansangan kan Īsa, iban duun isab in taymanghud babai sin ina' niya iban hi Mariyam amu in asawa hi Kurupas iban hi Mariyam amu in dayn ha dāira Magdala.",
        26: "Kīta' hi Īsa nagtitindug duun in ina' niya iban sin mulid kalasahan niya. Hangkan laung hi Īsa ha ina' niya, “Ina', bihaun in mulid ku yan, anak mu na.”",
        27: "Pag'ubus laung niya isab ha mulid niya, “Bihaun in ina' ku, ina' mu na.” Na, tagnaan dayn ha waktu yadtu in ina' hi Īsa himula' na ha lawman sin mulid yan.",
        28: 'Manjari kiyaingatan na hi Īsa sin in katān daakan piyahinang kaniya naubus na nahinang. Na, ha supaya maagad in kiyasulat ha lawm Kitab, mīchara hi Īsa, laung niya, “Iyuhaw aku.”',
        29: "Sakali asal awn duun bingki' hipu' sin tubig anggul (biya' tuba'). Na, pag'iyan hi Īsa iyuhaw siya, kimā' luppus in hambuuk sundalu ampa niya liyu'gum pa tubig anggul (biya' tuba'). Ubus ampa niya biyutang in luppus pa duhul kahuy ampa niya siyungit pa simud hi Īsa.",
        30: "Na, siyupsup hi Īsa in tubig anggul ampa siya namichara, laung niya, “Naubus na in hinang ku!” Pag'ubus tiyukku' niya in ū niya sarta' miyugtu' na in napas niya.",
        31: "Manjari in adlaw yadtu adlaw Jumaat. Na, miyadtu in manga nakura' Yahudi kan Pilatu nangayu' sin subay baliun in paa sin manga tau, amu in liyansang pa usuk bat matay magtūy, ha supaya hikaīg magtūy in manga mayat dayn ha usuk. Hangkan nangayu' in manga nakura' sin bihādtu, sabab di' sila mabaya' sin masi makaruun in manga mayat ha taas usuk bang maabut na adlaw paghali-hali iban pagpudji pa Tuhan. Karna' in adlaw yan, adlaw mulliya, amu in liyalaggu' tuud sin manga bangsa Yahudi.",
        32: "Na, miyadtu na in manga sundalu ampa nila biyali' in paa sin hambuuk tau amu in iyagad kan Īsa liyansang pa usuk. Damikkiyan da isab in hambuuk.",
        33: "Sakali pagsuuk nila mawn kan Īsa, kīta' nila miyamatay na. Hangkan wala' nila na biyali' in paa niya.",
        34: "Sagawa' biyudjak sin hambuuk sundalu in kīd hi Īsa. Na, saruun-duun gimuwa' in dugu' iban tubig.",
        35: "In nakakita' ha manga pakaradjaan kimugdan kan Īsa, amuna in nagsulat ha ini ha supaya kamu isab magparachaya. Kapangandulan in saksi' sin tau nagsulat ha ini iban kaingatan niya in kasabunnalan sin bayta' niya.",
        36: "Na, in hīnang (sin manga sundalu) yan nakarihil kasabunnalan sin asal kiyasulat ha lawm Kitab, amu agi, “Way mabali' minsan hambuuk bukug niya.”",
        37: 'Iban awn pa isab kiyasulat ha lawm Kitab, amu agi, “Aturun nila in tau amu in piyabudjak nila.”',
        38: "Manjari awn hambuuk tau dayn ha kawman Arimati, in ngān niya hi Yusup. Miyadtu siya kan Pilatu namaid bang makajari kawaun in bangkay hi Īsa dayn ha usuk. In hi Yusup ini hambuuk da isab agad kan Īsa, sagawa' wala' siya nagpatampal sabab mabuga' siya ha manga nakura' Yahudi. Na, tiyugutan mān siya hi Pilatu kumā' sin bangkay, miyadtu na hi Yusup kimā' sin bangkay.",
        39: "Miyagad da isab kan Yusup hi Nikudimus, amu in bakas miyadtu kan Īsa sin dūm dimā nagbichara. Nagdarā siya duwangka-ginis ubat mahamut (hipag'adjal sin bangkay hi Īsa). In hinang ubat yan burak amu in pagtawagun “mira” piyapaglamud iban sin kahuy alus. In bu'gat sin ubat mahamut awn manga kay'man kilu.",
        40: "Manjari kiyawa' na sin duwangka-tau ini in bangkay hi Īsa ampa nila siyaput sin kuku puti' marayaw biyubutangan nila sin ubat mahamut, karna' biya' hādtu in addat sin manga Yahudi bang magkubul sin mayat nila.",
        41: "Na, duun ha lugal masuuk ha piyagpatayan kan Īsa awn hambuuk kabbun. Duun ha kabbun yan awn hambuuk kubul biya' lupa sungab batu in ba'gu hīnang amu in wala' pa kiyapangubulan.",
        42: "Na pagga pagkikinsumun na in adlaw Sabtu' iban in kubul yaun masuuk pa lugal piyagpatayan kan Īsa, na duun nila na kiyubul in bangkay hi Īsa.",
    },
    20: {
        1: "Manjari pag'adlaw Ahad subu-subu pa, miyadtu hi Mariyam amu in babai dayn ha Magdala pa kubul hi Īsa. Pagdatung niya pa kubul, kīta' niya naīg na in batu bakas piyagtambul sin sūran pa lawm kubul.",
        2: "Na, dimagan siya madtu namayta' kan Simun Pitrus iban pa mulid amu in kalasahan hi Īsa. Laung niya kanila, “Kiyawa' nila in Panghu' dayn ha lawm kubul. Di' natu' na ini kaingatan bang haunu nila siya biyutang!”",
        3: 'Na, saruun-duun miyadtu hi Pitrus pa kubul hi Īsa iban sin mulid kalasahan hi Īsa.',
        4: "Dimagan sila karuwa madtu pa kubul sa' in hi Pitrus kiyabīn ha ulihan sabab mabiskay dumagan in mulid kalasahan hi Īsa. Hangkan siya in nakauna dimatung pa kubul.",
        5: "Pagdatung niya pa kubul, sinīb niya in lawm kubul. Kīta' niya in saput nagbubutang sagawa' wala' siya simūd pa lawm kubul.",
        6: "Sakali pagdatung mawn hi Simun Pitrus, timūy siya simūd pa lawm kubul. Kīta' niya in saput nagbubutang,",
        7: "iban kīta' niya nalulūn na in kakana' bakas piyagputus sin ū hi Īsa, lāgi' nakakandi na dayn ha saput.",
        8: "Na, in mulid amu in nakaratung muna pa kubul, simūd da isab pa lawm kubul. Pagkita' niya sin saput, magtūy siya nagparachaya sin in hi Īsa nabuhi' na nagbalik.",
        9: "Asal awn kiyasulat ha lawm Kitab sin mabuhi' hi Īsa magbalik dayn ha kamatay, sagawa' ha waktu yadtu in yan wala' pa kiyahātihan sin manga mulid hi Īsa.",
        10: "Sakali in duwa mulid minuwi' na nagbalik.",
        11: "Sakali in hi Mariyam masi duun nagtitindug nagtatangis ha guwa' sin kubul. Ha sa'bu niya nagtatangis sinīb niya in lawm kubul.",
        12: "Pagsīb niya, kīta' niya in duwa malāikat nagtatamung puti', limilingkud ha bakas kiyabutangan sin bangkay hi Īsa. In hambuuk ha dapit pa ūhan, ampa in hambuuk ha dapit pa sikān.",
        13: "Laung sin manga malāikat kaniya, “Inda', unu in piyagtangisan?” In sambung niya, “Inīgan nila in bangkay sin Panghu' ku dayn dī iban di' ku na kaingatan bang haunu nila biyutang!”",
        14: "Pag'ubus yadtu himarap hi Mariyam pa ulihan sarta' kīta' niya hi Īsa nagtitindug duun, sagawa' wala' niya kiyakilāhan hi Īsa.",
        15: "Laung hi Īsa kaniya, “Inda', mayta' kaw nagtangis? Iban hisiyu in liyawag mu?” Sagawa' in pangannal hi Mariyam tau nagtutunggu' sin kabbun pangungubulan in dimā nagbichara kaniya. Hangkan in sambung niya, laung niya, “Tuwan, bang ikaw in kimawa' sin bangkay niya dayn dī, baytai aku bang haunu na, bat kadtuun ku kawaun.”",
        16: "Sakali laung hi Īsa kaniya, “Mariyam.” Saruun-duun iyatud niya hi Īsa sarta' timulik siya, laung niya ha bahasa Hibrani, “Rabbuni.” (Hāti niya, “Guru”.)",
        17: "“Ayaw mu aku gunggungi,” laung hi Īsa kaniya, “sabab wala' pa aku nakabalik madtu pa Ama' ku. Sagawa' kadtu kaw pa katawtaymanghuran ku ampa mu sila baytai sin magbabalik na aku madtu pa Ama' ku amu in Tuhan ku. Siya da isab in Ama' iban Tuhan niyu.”",
        18: "Na, miyadtu hi Mariyam, amu in babai dayn ha Magdala, namayta' ha manga mulid hi Īsa sin kīta' niya in Panghu' iban biyaytaan niya sila sin bichara hi Īsa kaniya.",
        19: "Sakali narūm mayan sin adlaw Ahad, nagtipun in manga mulid hi Īsa ha hambuuk bāy sa' tiyatambul nila in lawang kiyakandaru sabab mabuga' sila ha manga nakura' Yahudi. Sakali miyadtu hi Īsa nagpanyata' timindug ha gi'tungan nila, laung niya kanila. “Bang mayan awn kasannyangan ha lawm atay niyu.”",
        20: "Pag'ubus hi Īsa nagbichara piyakita' niya ha manga mulid niya in duwa lima niya iban sin kīd niya, (amu in tanda' nagpakita' sin siya na tuud hi Īsa). Na landu' tuud in kakuyagan sin manga mulid pagkita' nila ha Panghu'.",
        21: "Sakali biyalikan hi Īsa in bichara niya kanila, laung niya, “Bang mayan awn kasannyangan ha lawm atay niyu. Bihaun daakun ta kamu biya' da isab kāku' naraak sin Ama' ku mari.”",
        22: "Pag'ubus ampa hi Īsa himanggut sin napas niya pa guwa' piyatudju pa manga mulid niya, sarta' laung niya kanila, “Taymaa niyu in Rū sin Tuhan.",
        23: "Bang niyu maapun in manga tau, tantu ampunun da isab sila sin Tuhan, sagawa' bang niyu sila di' maapun, na tantu di' da isab sila ampunun sin Tuhan.”",
        24: "Na, in waktu pagkawn hi Īsa pa manga mulid niya sa'bu wala' duun hi Tumas, (amu in pagtawagun Kambal.) In hi Tumas ini agad ha hangpu' tagduwa mulid hi Īsa.",
        25: "Hangkan biyaytaan siya sin kaibanan mulid, laung nila kaniya, “Nakapagkita' kami iban sin Panghu'!” Laung hi Tumas kanila, “Bang ku di' kakitaan sin duwa mata ku iban kakumpitan in limpa' sin lansang ha duwang sipak lima niya iban masanaw in limpa' sin pali' ha kīd niya, di' aku magparachaya sin bayta' niyu.”",
        26: "Manjari pagga hangka-pitu na nakalabay, nagpūn na isab nagbalik in manga mulid hi Īsa iban nakaagad na hi Tumas kanila. Sakali pagsayu nila, yaun na hi Īsa timitindug ha gi'tungan nila, malayngkan kiyakandaruhan nila in lawang. Laung hi Īsa kanila, “Bang mayan awn kasannyangan ha lawm atay niyu.”",
        27: "Pag'ubus laung niya kan Tumas, “Kitaa iban kumpiti in lima ku ha supaya mu kananaman in limpa' sin pali' ku, iban sānawa in kīd ku bat kananaman in limpa'. Ayaw na kaw magduwa-ruwa. Pagparachaya na kaw kāku'!”",
        28: "In sambung hi Tumas kaniya, “Ū Panghu' ku, ikaw in Tuhan ku!”",
        29: "Laung hi Īsa kaniya, “In ikaw nagparachaya kāku' pasal sin kīta' mu aku nagbaran mari. Dakula' in karayawan sin manga tau magparachaya kāku' minsan nila aku wala' kīta'!”",
        30: "Na, mataud pa manga mu'jijat nahinang hi Īsa ha matahan sin manga mulid niya, amu in wala' nakalamud siyulat ha Kitab ini.",
        31: "Sagawa' kiyasulat ha lawm Kitab ini in manga pakaradjaan pasal hi Īsa, ha supaya kamu magparachaya sin in hi Īsa amuna tuud in Almasi, amu in Anak Tuhan, iban ha supaya da isab makabaak kamu kabuhi' salama-lama sabab sin pangandul niyu kaniya.",
    },
    21: {
        1: "Manjari manga pilay adlaw na limabay miyadtu na isab hi Īsa nagbalik nagpanyata' ha manga mulid niya didtu ha higad sin Dagat Tibiri. Biya' ha ini in pagpanyata' hi Īsa ha manga mulid niya.",
        2: "Ha wala' pa nakapagpanyata' hi Īsa mawn pa manga mulid niya, nagpupūn hinda Pitrus, hi Tumas, amu in pagtawagun Kambal, hi Natanyal, amu in dayn ha Kana ha hula' Jalil, in duwa anak hi Sibidi iban sin duwa pa mulid hi Īsa.",
        3: "Laung hi Simun Pitrus ha manga iban niya, “Madtu pa aku manglaya.” Laung sin manga iban niya, “Magad kami kaymu.” (Na, diyayungan nila na in kumpit nila asibi' pa lawd.) Sagawa' dayn ha dūm sampay naabut lapit adlaw wayruun ista' nakawa' nila.",
        4: "Baya-baya mān maadlaw na, didtu hi Īsa timitindug ha higad dagat. Sagawa' wala' siya kiyakilāhan sin manga mulid niya.",
        5: "Sakali tiyawag sila hi Īsa, “Uwa', manga tuwan, awn da ka nakawa' niyu yan?” Laung nila, “Wayruun.”",
        6: "Laung hi Īsa kanila, “Larukan in laya niyu ha dapit pa tuu sin kumpit niyu bat kamu makakawa' ista'.” Na, liyaruk nila na in laya nila, sakali di' nila na mautung pasal mataud tuud ista' in nakawa' sin laya nila.",
        7: "Manjari mīchara kan Pitrus in mulid kalasahan hi Īsa, laung niya, “Hi Panghu' in tau yaun!” Pagdungug hi Pitrus sin bichara sin mulid yaun, magtūy siya nag'ūs-'ūs nagbadju'. (Pasal bakas niya inīgan in badju' niya.) Ubus ampa siya timugpa' pa dagat.",
        8: "Na, in kaibanan mulid nagdayung na pa higad dagat ha sa'bu nila nag'uutung sin laya nila hipu' sin ista'. Bukun sila malayu' dayn ha higad dagat karna' awn da manga kay'man ngarupa in layu' nila.",
        9: "Pagdatung nila pa higad dagat, kīta' nila in baga kāyu piyagdarangdangan sin ista' iban awn da isab manga tinapay.",
        10: "Na, laung hi Īsa kanila, “Dā kamu mari sin manga ista' nakawa' niyu.”",
        11: "Sakali simakat magtūy hi Pitrus pa kumpit nila ampa niya hiyubaran in laya. Ubus ampa niya giyuyud in laya pa higad dagat. In laya nila nahipu' sin manga ista' maaslag sadja. In taud sin manga ista' awn hanggatus tagkay'man tagtū katān. Sagawa' minsan bihādtu in taud sin ista' wala' minsan nagisi' in laya nila.",
        12: "Laung hi Īsa kanila, “Kari na kamu kaun.” Na, wayruun tuud minsan hambuuk mulid niya in timawakkal nangasubu kaniya bang hisiyu siya sabab asal kiyaingatan nila sin siya na in Panghu' nila.",
        13: "Sakali kiyawa' na madtu hi Īsa in tinapay ampa niya dīhil mawn pa manga mulid niya. Damikkiyan in ista'.",
        14: "Na, amuna ini in hikatū pagpanyata' hi Īsa mawn pa manga mulid niya dayn ha waktu kabuhi' kaniya magbalik dayn ha kamatay.",
        15: "Pag'ubus nila nagkaun, laung hi Īsa kan Pitrus, “Simun, anak hi Yahiya, in lasa mu kāku' lumabi tuud baha' dayn ha lasa sin manga kaibanan ini kāku'?” In sambung hi Pitrus, “Huun, Panghu', kaingatan mu sin malasa aku kaymu.” Laung hi Īsa kaniya, “Palihalaa in manga tau suku' ku biya' sin pagpalihala' sin mag'iipat bili-bili ha manga anak bili-bili niya.”",
        16: "Nangasubu na isab nagbing hi Īsa kan Pitrus, “Simun, anak hi Yahiya, malasa ka kaw tuud kāku'?” In sambung hi Pitrus, “Huun, Panghu', kaingatan mu sin malasa aku kaymu.” Laung hi Īsa kaniya, “Palihalaa in manga tau suku' ku biya' sin pagpalihala' sin mag'iipat bili-bili ha manga bili-bili niya.”",
        17: "Sakali iyasubu na isab nagbalik hi Īsa hi Pitrus, laung niya, “Simun, anak hi Yahiya, malasa ka kaw tuud kāku'?” Na, nasusa hi Pitrus sabab nakatū na siya iyasubu hi Īsa bang siya malasa tuud kaniya. Na, hangkan laung niya, “Panghu', kaingatan mu in unu-unu katān. Na, tantu kaingatan mu sin malasa aku kaymu!” Laung hi Īsa kaniya, “Palihalaa in manga tau suku' ku biya' sin pagpalihala' sin mag'iipat bili-bili ha manga bili-bili niya.",
        18: "Baytaan ta kaw sin kasabunnalan. Sin bata' pa kaw luhaya kaw magbadju' iban maglunsul pakain-pakain in kabayaan mu. Sagawa' lumaas mayan kaw, sayangun mu in karuwang sipak buktun mu ampa kaw hukutan sin dugaing tau. Ubus ampa kaw dāhun pa lugal di' mu kabayaan kadtuun.”",
        19: "Hangkan hi Īsa namichara bihādtu sabab hipaingat niya bang biya' diin in kamatay hi Pitrus. Lāgi' in kamatay niya makarihil da isab kalagguan ha Tuhan. Na, laung hi Īsa kan Pitrus, “Agad na kaw kāku'!”",
        20: "Manjari pagharap hi Pitrus pa ulihan, kīta' niya in mulid amu in kalasahan hi Īsa. In mulid ini amuna in simuuk tuud kan Īsa ha waktu sa'bu nila nagjamu ampa nangasubu kan Īsa, laung niya, “Panghu' hisiyu in manipu kaymu?”",
        21: "Pagkita' hi Pitrus ha mulid ini, iyasubu niya hi Īsa, laung niya, “Panghu', na biya' diin in siya yaun?”",
        22: "In sambung hi Īsa kaniya, “Mayta', unu in kibil mu bang in kabayaan ku buhi' siya sampay aku magbalik mari pa dunya? In pasal ha yan wayruun lamud mu. Agad na kaw kāku'!”",
        23: "Na, dayn didtu naglatag in suysuy pa manga tau agad kan Īsa sin in mulid amu in kalasahan niya di' mapatay. Sagawa' wala' imiyan hi Īsa sin di' matay in mulid yaun. In agi niya biya' ha ini, laung niya, “Mayta', unu in kibil mu bang in kabayaan ku buhi' siya sampay aku magbalik mari pa dunya?”",
        24: "In mulid piyag'iyan hi Īsa, amuna in namayta' iban simulat sin katān pakaradjaan ini pasal hi Īsa. Lāgi' kaingatan sin kitaniyu katān sin bunnal in bayta' sin mulid yan.",
        25: "Mataud pa tuud in manga nahinang hi Īsa, sumagawa' bang hisulat in katān nahinang niya ha manga Kitab, na maray' di' maluun dī ha dunya ini in taud sin manga Kitab pasal niya. Wassalam!",
    },
}
